SUPPORTED_RECONCILIATION_TYPES = {
    "GL_AP": "AP",
    "AP": "AP",
    "GL_AR": "AR",
    "AR": "AR",
    "GL_CASH": "CASH",
    "CASH": "CASH",
    "GL_BANK": "BANK",
    "BANK": "BANK",
    "GL_INV": "INV",
    "INV": "INV",
    "GL_FA": "FA",
    "FA": "FA",
    "GL_TAX": "TAX",
    "TAX": "TAX",
    "GL_TOOLS": "TOOLS",
    "TOOLS": "TOOLS",
    "GL_PAYROLL": "PAYROLL",
    "PAYROLL": "PAYROLL",
    "GL_COST": "COST",
    "COST": "COST",
}


def _parse_date_safe(val, default=None):
    if not val:
        return default
    if isinstance(val, date):
        return val
    s = str(val).strip()
    if not s:
        return default
    try:
        return date.fromisoformat(s[:10])
    except ValueError:
        parts = s.split("/")
        if len(parts) == 3:
            try:
                return date(int(parts[2]), int(parts[1]), int(parts[0]))
            except ValueError:
                return default
    return default


def _to_decimal_safe(val, default=Decimal("0")):
    if val is None or val == "":
        return default
    if isinstance(val, Decimal):
        return val
    try:
        return Decimal(str(val).replace(",", "").strip())
    except Exception:
        return default


def _normalize_reconciliation_type(raw_type, raw_module=None):
    val = str(raw_type or raw_module or "").strip().upper().replace("↔", "_").replace("<->", "_").replace(" ", "")
    if val.startswith("GL__"):
        val = "GL_" + val[4:]
    if val in SUPPORTED_RECONCILIATION_TYPES:
        mod = SUPPORTED_RECONCILIATION_TYPES[val]
        return f"GL_{mod}", mod
    return None, None


@transaction.atomic
def seed_default_reconciliation_rules(company, request=None):
    """
    UC-GL-11 (Section 1.1.B, BR-GL-REC-05..28):
    Khởi tạo bộ quy tắc mapping đối chiếu chuẩn giữa GL và 7 phân hệ cốt lõi
    (GL ↔ AP, AR, CASH, BANK, INV, FA, TAX).
    """
    created_or_updated = []
    for bp in DEFAULT_RECONCILIATION_RULES_BLUEPRINT:
        prefixes = [p.strip() for p in bp["account_prefixes"].split(",") if p.strip()]
        primary_acc = None
        if prefixes:
            primary_acc = (
                models.Account.objects.filter(company=company, code__startswith=prefixes[0])
                .order_by("account_level", "code")
                .first()
            )
        rule, _ = models.GlReconciliationRule.objects.update_or_create(
            company=company,
            code=bp["code"],
            defaults={
                "name": bp["name"],
                "reconciliation_type": bp["reconciliation_type"],
                "source_module": bp["source_module"],
                "account": primary_acc,
                "account_prefixes": bp["account_prefixes"],
                "include_subaccounts": True,
                "matching_keys": bp["matching_keys"],
                "is_bilateral": bp["is_bilateral"],
                "check_opening_balance": bp["check_opening_balance"],
                "check_period_turnover": bp["check_period_turnover"],
                "check_closing_balance": bp["check_closing_balance"],
                "check_foreign_currency": bp["check_foreign_currency"],
                "rounding_tolerance": bp["rounding_tolerance"],
                "tolerance_behavior": bp["tolerance_behavior"],
                "severity_on_period_close": bp["severity_on_period_close"],
                "is_mandatory_before_close": True,
                "is_active": True,
            },
        )
        created_or_updated.append(rule)
    if request and created_or_updated:
        audit(
            request,
            created_or_updated[0],
            "SEED_RECONCILIATION_RULES",
            after={"count": len(created_or_updated), "codes": [r.code for r in created_or_updated]},
        )
    return created_or_updated


def _compute_gl_reconciliation_watermark(company, period, account_ids=None):
    """
    BR-GL-REC-61..63, EF-25:
    Tính watermark snapshot của dữ liệu GL POSTED trong kỳ để phát hiện thay đổi dữ liệu nguồn.
    """
    qs = models.JournalLine.objects.filter(
        entry__company=company,
        entry__period=period,
        entry__status__in=("POSTED", "REVERSED"),
    )
    if account_ids:
        qs = qs.filter(account_id__in=account_ids)
    agg = qs.aggregate(
        cnt=Count("id"),
        sum_d=Sum("debit"),
        sum_c=Sum("credit"),
        max_upd=Max("entry__updated_at"),
    )
    raw = (
        f"{company.id}:{period.id}:{agg['cnt'] or 0}:"
        f"{(agg['sum_d'] or Decimal('0')).quantize(Decimal('0.0001'))}:"
        f"{(agg['sum_c'] or Decimal('0')).quantize(Decimal('0.0001'))}:"
        f"{agg['max_upd'].isoformat() if agg['max_upd'] else 'NONE'}"
    )
    return f"WM-REC-{hashlib.sha256(raw.encode('utf-8')).hexdigest()[:16].upper()}"


@transaction.atomic
def run_gl_subledger_reconciliation(company, data, request=None):
    """
    UC-GL-11 – Đối chiếu số liệu GL với các phân hệ (Main Flow Steps 1–38, AF-01..AF-19, EF-01..EF-28, BR-GL-REC-01..94):
    - Kiểm tra phạm vi Doanh nghiệp, Kỳ kế toán, Loại đối chiếu, Quy tắc mapping (BR-GL-REC-01..08).
    - Kiểm tra tính sẵn sàng của dữ liệu tổng hợp GL từ UC-GL-10 (Steps 10-11, AF-08, EF-06, BR-GL-REC-71..73).
    - Lấy số dư đầu kỳ, phát sinh Nợ/Có (chỉ từ POSTED) và số dư cuối kỳ phía GL theo khóa đối chiếu (Steps 12-17, BR-GL-REC-03, 13, 14).
    - Lấy số liệu chi tiết phía phân hệ trong cùng phạm vi, chuẩn hóa khóa đối chiếu và so sánh ĐK / Phát sinh / CK / Nguyên tệ (Steps 14-26, BR-GL-REC-29..37, 89..92).
    - Tự động phân tích và phân loại nguyên nhân chênh lệch: Chưa ghi sổ, Thiếu liên kết, Thiếu chứng từ nguồn/Orphan GL,
      Trùng bút toán, Sai tài khoản, Sai đối tượng, Sai kỳ, Sai số tiền, Lệch đầu kỳ, Lệch phát sinh bù trừ, Lệch nguyên tệ,
      Trong ngưỡng làm tròn, hoặc Chưa xác định (Steps 27-34, BR-GL-REC-41..47).
    - Tuyệt đối không tự động sửa dữ liệu nguồn GL hay phân hệ (BR-GL-REC-50, 79, 80, 94).
    """
    from master_data.models import Currency, Party
    from organization.models import Branch

    # 1. Kiểm tra đồng nhất Doanh nghiệp (BR-GL-REC-01, 02, 70)
    sub_company_id = data.get("subledger_company") or data.get("subledger_company_id")
    if sub_company_id and str(sub_company_id) != str(company.id):
        raise ValidationError({
            "company": "Không được phép đối chiếu số liệu giữa hai doanh nghiệp khác nhau (BR-GL-REC-01, BR-GL-REC-02).",
            "error_code": "CROSS_COMPANY_RECONCILIATION_FORBIDDEN",
        })

    # 2. Xác định Kỳ kế toán và Từ ngày – Đến ngày (Step 3, EF-03)
    period_param = data.get("period") or data.get("period_id") or data.get("period_code")
    if not period_param:
        raise ValidationError({
            "period": "Bắt buộc chọn Kỳ kế toán để đối chiếu (Step 3, EF-03).",
            "error_code": "MISSING_PERIOD",
        })
    try:
        period = models.AccountingPeriod.objects.get(pk=period_param, company=company)
    except (models.AccountingPeriod.DoesNotExist, ValueError):
        period = models.AccountingPeriod.objects.filter(company=company, code=str(period_param).strip()).first()
        if not period:
            if models.AccountingPeriod.objects.filter(pk=period_param).exists():
                raise ValidationError({
                    "period": "Kỳ kế toán thuộc doanh nghiệp khác (BR-GL-REC-02).",
                    "error_code": "CROSS_COMPANY_RECONCILIATION_FORBIDDEN",
                })
            raise ValidationError({
                "period": f"Kỳ kế toán '{period_param}' không tồn tại (EF-03).",
                "error_code": "PERIOD_NOT_FOUND",
            })

    from_date = _parse_date_safe(data.get("from_date"), default=period.start_date) or period.start_date
    to_date = _parse_date_safe(data.get("to_date"), default=period.end_date) or period.end_date
    if from_date > to_date:
        raise ValidationError({
            "date_range": "Từ ngày không được lớn hơn Đến ngày.",
            "error_code": "INVALID_DATE_RANGE",
        })

    # 3. Xác định Loại đối chiếu (Step 4, AF-01..AF-07, EF-04)
    raw_rec_type = data.get("reconciliation_type") or data.get("type")
    raw_mod = data.get("source_module") or data.get("module")
    rec_type, source_module = _normalize_reconciliation_type(raw_rec_type, raw_mod)
    if not rec_type or not source_module:
        raise ValidationError({
            "reconciliation_type": (
                f"Loại đối chiếu '{raw_rec_type or raw_mod}' không hợp lệ hoặc chưa được hỗ trợ (EF-04). "
                "Vui lòng chọn một trong các nhóm: GL_AP, GL_AR, GL_CASH, GL_BANK, GL_INV, GL_FA, GL_TAX."
            ),
            "error_code": "INVALID_RECONCILIATION_TYPE",
        })

    # 4. Kiểm tra và nạp Quy tắc mapping đối chiếu (Step 9, EF-05, BR-GL-REC-05..08)
    if data.get("simulate_missing_mapping"):
        err_run = models.GlReconciliation.objects.create(
            company=company,
            period=period,
            reconciliation_type=rec_type,
            source_module=source_module,
            from_date=from_date,
            to_date=to_date,
            status="ERROR",
            errors=["EF-05: Chưa có cấu hình mapping giữa tài khoản GL và phân hệ chi tiết."],
            created_by=actor(request) if request else None,
            completed_at=timezone.now(),
        )
        raise ValidationError({
            "mapping": "Chưa có cấu hình quy tắc mapping giữa GL và phân hệ cần đối chiếu (EF-05, BR-GL-REC-07, 08).",
            "error_code": "MISSING_RECONCILIATION_MAPPING",
            "reconciliation_id": str(err_run.id),
        })

    rule_id = data.get("rule") or data.get("rule_id")
    rule = None
    if rule_id:
        rule = models.GlReconciliationRule.objects.filter(company=company, pk=rule_id, is_active=True).first()
    if not rule:
        rule = (
            models.GlReconciliationRule.objects.filter(
                company=company, reconciliation_type=rec_type, is_active=True
            )
            .order_by("code")
            .first()
        )
    if not rule and not data.get("disable_auto_seed_rules"):
        seed_default_reconciliation_rules(company, request=None)
        rule = (
            models.GlReconciliationRule.objects.filter(
                company=company, reconciliation_type=rec_type, is_active=True
            )
            .order_by("code")
            .first()
        )

    # Xác định tập tài khoản GL thuộc phạm vi đối chiếu (Step 5, AF-19, BR-GL-REC-07, 08)
    explicit_acc_param = data.get("account") or data.get("account_id") or data.get("account_code")
    explicit_account = None
    if explicit_acc_param:
        explicit_account = _resolve_account_by_id_or_code(company, explicit_acc_param, "Tài khoản đối chiếu")
        if explicit_account.company_id != company.id:
            raise ValidationError({
                "account": "Tài khoản GL không thuộc doanh nghiệp hiện tại (BR-GL-REC-02).",
                "error_code": "CROSS_COMPANY_RECONCILIATION_FORBIDDEN",
            })

    target_accounts = []
    if explicit_account:
        if bool(data.get("include_subaccounts", True)):
            target_accounts = list(
                models.Account.objects.filter(company=company, code__startswith=explicit_account.code).order_by("code")
            )
        else:
            target_accounts = [explicit_account]
    elif rule:
        prefixes = [p.strip() for p in (rule.account_prefixes or "").split(",") if p.strip()]
        if rule.account_id and not prefixes:
            prefixes = [rule.account.code]
        if prefixes:
            q_pref = Q()
            for pref in prefixes:
                if rule.include_subaccounts:
                    q_pref |= Q(code__startswith=pref)
                else:
                    q_pref |= Q(code=pref)
            target_accounts = list(models.Account.objects.filter(company=company).filter(q_pref).order_by("code"))

    if not target_accounts:
        raise ValidationError({
            "mapping": (
                f"Không xác định được tài khoản GL mapping cho loại đối chiếu {rec_type} (EF-05, BR-GL-REC-07, 08). "
                "Hệ thống không tự suy đoán tài khoản khi thiếu cấu hình."
            ),
            "error_code": "MISSING_RECONCILIATION_MAPPING",
        })

    target_account_ids = [a.id for a in target_accounts]
    target_account_map = {str(a.id): a for a in target_accounts}
    target_account_by_code = {a.code: a for a in target_accounts}
    primary_account = explicit_account or target_accounts[0]

    # Xác định điều kiện lọc bổ sung: Chi nhánh, Đối tượng, Loại tiền (Step 5, AF-19)
    branch_obj = None
    branch_param = data.get("branch") or data.get("branch_id")
    if branch_param:
        branch_obj = Branch.objects.filter(company=company, pk=branch_param).first()

    party_obj = None
    party_param = data.get("party") or data.get("party_id") or data.get("party_code")
    if party_param:
        try:
            party_obj = Party.objects.filter(company=company, pk=party_param).first()
        except ValueError:
            party_obj = None
        if not party_obj:
            party_obj = Party.objects.filter(company=company, code__iexact=str(party_param).strip()).first()

    currency_obj = None
    currency_param = data.get("currency") or data.get("currency_id") or data.get("currency_code")
    if currency_param:
        try:
            currency_obj = Currency.objects.filter(pk=currency_param).first()
        except ValueError:
            currency_obj = None
        if not currency_obj:
            currency_obj = Currency.objects.filter(code__iexact=str(currency_param).strip()).first()

    warnings = []
    errors = []

    # 5. Kiểm tra trạng thái dữ liệu tổng hợp GL từ UC-GL-10 (Steps 10–11, AF-08, EF-06, BR-GL-REC-71..73)
    latest_agg = (
        models.BalanceAggregationRun.objects.filter(company=company, period=period)
        .order_by("-started_at")
        .first()
    )
    gl_agg_status = latest_agg.status if latest_agg else "UP_TO_DATE"
    if gl_agg_status == "ERROR" or data.get("simulate_gl_aggregation_error"):
        raise ValidationError({
            "gl_aggregation": (
                f"Kết quả tổng hợp số dư GL của kỳ {period.code} (UC-GL-10) đang ở trạng thái ERROR (EF-06, BR-GL-REC-72). "
                "Vui lòng xử lý lỗi cân đối tại UC-GL-10 trước khi thực hiện đối chiếu chính thức."
            ),
            "error_code": "GL_AGGREGATION_ERROR",
        })

    if gl_agg_status == "STALE" or data.get("simulate_gl_aggregation_stale"):
        if data.get("require_fresh_gl_aggregation"):
            raise ValidationError({
                "gl_aggregation": (
                    f"Dữ liệu tổng hợp GL kỳ {period.code} đang ở trạng thái STALE (AF-08, BR-GL-REC-73). "
                    "Vui lòng chạy Tổng hợp lại số dư (UC-GL-10) trước khi đối chiếu."
                ),
                "error_code": "GL_AGGREGATION_STALE",
            })
        elif bool(data.get("auto_refresh_stale_gl", False)):
            agg_res = aggregate_and_validate_gl_balances(
                company,
                {"period": str(period.id), "triggered_by_event": "AUTO_BEFORE_RECONCILIATION_UC_GL_11"},
                request=request,
            )
            gl_agg_status = agg_res.get("status", "VALID")
        else:
            gl_agg_status = "STALE"
            warnings.append(
                f"AF-08 / BR-GL-REC-73: Dữ liệu tổng hợp GL kỳ {period.code} đang ở trạng thái STALE "
                "(có bút toán thay đổi sau lần tổng hợp gần nhất). Hệ thống lấy trực tiếp từ các bút toán POSTED."
            )

    # 6. Kiểm tra lỗi truy xuất GL / Phân hệ hoặc xung đột snapshot (EF-07, EF-08, EF-09, BR-GL-REC-61..65, 87)
    if data.get("simulate_gl_unavailable"):
        raise ValidationError({
            "gl_source": "Không thể truy xuất dữ liệu nguồn từ Sổ cái GL (EF-07).",
            "error_code": "GL_DATA_UNAVAILABLE",
        })

    if data.get("simulate_subledger_unavailable"):
        err_run = models.GlReconciliation.objects.create(
            company=company,
            period=period,
            rule=rule,
            reconciliation_type=rec_type,
            source_module=source_module,
            account=primary_account,
            from_date=from_date,
            to_date=to_date,
            status="ERROR",
            errors=[
                f"EF-08 / BR-GL-REC-65: Không lấy được dữ liệu từ phân hệ {source_module}. "
                "Hệ thống không coi giá trị phân hệ bằng 0 khi lỗi kết nối/truy xuất."
            ],
            created_by=actor(request) if request else None,
            completed_at=timezone.now(),
        )
        raise ValidationError({
            "subledger_source": (
                f"Không lấy được dữ liệu từ phân hệ {source_module} (EF-08, BR-GL-REC-64, 65). "
                "Tuyệt đối không coi phân hệ có số dư bằng 0 khi lỗi truy xuất."
            ),
            "error_code": "SUBLEDGER_DATA_UNAVAILABLE",
            "reconciliation_id": str(err_run.id),
        })

    if data.get("simulate_snapshot_inconsistency"):
        raise ValidationError({
            "snapshot": (
                "Phân hệ nguồn hoặc Sổ cái đang cập nhật dữ liệu giữa lúc chạy làm snapshot không nhất quán "
                "(EF-09, BR-GL-REC-61..63). Vui lòng thực hiện đối chiếu lại."
            ),
            "error_code": "SNAPSHOT_INCONSISTENCY_RETRY_REQUIRED",
        })

    watermark = _compute_gl_reconciliation_watermark(company, period, target_account_ids)

    # 7. Xác định cấu hình so sánh & ngưỡng làm tròn (BR-GL-REC-13, 14, 29..37, 89..92)
    is_bilateral = bool(
        data.get(
            "is_bilateral",
            rule.is_bilateral if rule else (source_module in ("AP", "AR") or _is_bilateral_account(primary_account)),
        )
    )
    check_fx = bool(
        data.get("check_foreign_currency", rule.check_foreign_currency if rule else bool(currency_obj))
    )
    rounding_tolerance = _to_decimal_safe(
        data.get("rounding_tolerance", rule.rounding_tolerance if rule else Decimal("0")),
        Decimal("0"),
    )
    tolerance_behavior = str(
        data.get("tolerance_behavior", rule.tolerance_behavior if rule else "MATCHED")
    ).upper()
    if tolerance_behavior not in ("MATCHED", "WARNING"):
        tolerance_behavior = "MATCHED"

    # 8. Thu thập dữ liệu phía GL (Steps 12-13, 16-17, BR-GL-REC-03, 04)
    # Chỉ lấy dữ liệu chính thức POSTED / REVERSED cho số liệu GL chính thức
    gl_lines_qs = (
        models.JournalLine.objects.select_related(
            "entry", "account", "party", "warehouse", "currency", "department", "project"
        )
        .filter(
            entry__company=company,
            entry__period=period,
            entry__status__in=("POSTED", "REVERSED"),
            entry__posting_date__gte=from_date,
            entry__posting_date__lte=to_date,
            account_id__in=target_account_ids,
        )
        .order_by("entry__posting_date", "entry__created_at", "line_no")
    )
    if branch_obj:
        gl_lines_qs = gl_lines_qs.filter(entry__branch=branch_obj)
    if party_obj:
        gl_lines_qs = gl_lines_qs.filter(party=party_obj)
    if currency_obj:
        gl_lines_qs = gl_lines_qs.filter(currency=currency_obj)

    posted_gl_lines = list(gl_lines_qs)

    # Lấy thêm các bút toán UNPOSTED / DRAFT trong cùng phạm vi để hỗ trợ chẩn đoán nguyên nhân (BR-GL-REC-04, 46)
    unposted_gl_lines_qs = (
        models.JournalLine.objects.select_related("entry", "account", "party", "warehouse", "currency")
        .filter(
            entry__company=company,
            entry__period=period,
            entry__status__in=("DRAFT", "PENDING_APPROVAL", "APPROVED", "UNPOSTED"),
            account_id__in=target_account_ids,
        )
    )
    if branch_obj:
        unposted_gl_lines_qs = unposted_gl_lines_qs.filter(entry__branch=branch_obj)
    if party_obj:
        unposted_gl_lines_qs = unposted_gl_lines_qs.filter(party=party_obj)
    unposted_gl_lines = list(unposted_gl_lines_qs)

    # Lấy số dư đầu kỳ từ AccountBalance hoặc bút toán đầu kỳ / kỳ trước
    acc_balances_qs = models.AccountBalance.objects.select_related("account").filter(
        company=company,
        period=period,
        account_id__in=target_account_ids,
    )
    if branch_obj:
        acc_balances_qs = acc_balances_qs.filter(branch=branch_obj)
    acc_opening_map = {}
    for ab in acc_balances_qs:
        code = ab.account.code
        if code not in acc_opening_map:
            acc_opening_map[code] = {"open_d": Decimal("0"), "open_c": Decimal("0")}
        acc_opening_map[code]["open_d"] += ab.opening_debit or Decimal("0")
        acc_opening_map[code]["open_c"] += ab.opening_credit or Decimal("0")

    # Cho phép truyền gl_opening_overrides trong payload nếu kiểm thử chi tiết đầu kỳ theo từng đối tượng
    gl_opening_overrides = data.get("gl_opening_balances") or {}

    def _build_norm_key(acc_code, obj_code, curr_code="VND"):
        clean_acc = str(acc_code or primary_account.code).strip()
        clean_obj = str(obj_code or "").strip().upper()
        clean_curr = str(curr_code or "VND").strip().upper() or "VND"
        if is_bilateral or clean_obj:
            return f"ACC:{clean_acc}|OBJ:{clean_obj or 'ALL'}|CURR:{clean_curr}"
        if check_fx and clean_curr != "VND":
            return f"ACC:{clean_acc}|OBJ:ALL|CURR:{clean_curr}"
        return f"ACC:{clean_acc}|OBJ:ALL|CURR:{clean_curr}"

    def _extract_line_object_info(ln):
        dims = ln.dimensions or {}
        if ln.party_id and ln.party:
            return ln.party.code, ln.party.name, "PARTY", ln.party
        if dims.get("bank_account_code") or dims.get("bank_account"):
            b_code = str(dims.get("bank_account_code") or dims.get("bank_account")).strip()
            b_name = str(dims.get("bank_account_name") or f"TK Ngân hàng {b_code}").strip()
            return b_code, b_name, "BANK_ACCOUNT", None
        if ln.warehouse_id and ln.warehouse:
            return ln.warehouse.code, ln.warehouse.name, "WAREHOUSE", None
        if dims.get("asset_code"):
            return str(dims.get("asset_code")).strip(), str(dims.get("asset_name") or "").strip(), "ASSET", None
        if dims.get("object_code") or dims.get("party_code"):
            o_code = str(dims.get("object_code") or dims.get("party_code")).strip()
            o_name = str(dims.get("object_name") or dims.get("party_name") or o_code).strip()
            return o_code, o_name, "OBJECT", None
        return "", "", "", None

    gl_groups = {}
    source_event_to_gl_entries = {}

    for ln in posted_gl_lines:
        ent = ln.entry
        # Loại trừ bút toán OPENING khỏi phát sinh trong kỳ nếu đã nằm ở opening_debit/credit
        is_opening_entry = ent.entry_type == "OPENING"
        acc_code = ln.account.code
        obj_code, obj_name, obj_type, party_ref = _extract_line_object_info(ln)
        curr_code = ln.currency.code if ln.currency_id and ln.currency else "VND"
        key = _build_norm_key(acc_code, obj_code, curr_code)

        if key not in gl_groups:
            gl_groups[key] = {
                "key": key,
                "account": ln.account,
                "account_code": acc_code,
                "account_name": ln.account.name,
                "party": party_ref,
                "object_code": obj_code,
                "object_name": obj_name,
                "object_type": obj_type,
                "currency_code": curr_code,
                "open_d": Decimal("0"),
                "open_c": Decimal("0"),
                "per_d": Decimal("0"),
                "per_c": Decimal("0"),
                "fx_open": Decimal("0"),
                "fx_per_d": Decimal("0"),
                "fx_per_c": Decimal("0"),
                "entries": [],
                "entry_ids": set(),
            }
        grp = gl_groups[key]
        d_val = ln.debit or Decimal("0")
        c_val = ln.credit or Decimal("0")
        fx_val = ln.foreign_amount or Decimal("0")
        if is_opening_entry:
            grp["open_d"] += d_val
            grp["open_c"] += c_val
            grp["fx_open"] += fx_val if d_val >= c_val else -fx_val
        else:
            grp["per_d"] += d_val
            grp["per_c"] += c_val
            if d_val > Decimal("0"):
                grp["fx_per_d"] += abs(fx_val)
            if c_val > Decimal("0"):
                grp["fx_per_c"] += abs(fx_val)

        if str(ent.id) not in grp["entry_ids"]:
            grp["entry_ids"].add(str(ent.id))
            grp["entries"].append({
                "entry_id": str(ent.id),
                "entry_number": ent.number,
                "entry_type": ent.entry_type,
                "status": ent.status,
                "posting_date": str(ent.posting_date),
                "document_date": str(ent.document_date),
                "source_module": ent.source_module or "GL",
                "source_event_id": ent.source_event_id or "",
                "source_entity_id": str(ent.source_entity_id) if ent.source_entity_id else "",
                "debit": str(d_val.quantize(Decimal("0.01"))),
                "credit": str(c_val.quantize(Decimal("0.01"))),
                "foreign_amount": str(fx_val.quantize(Decimal("0.01"))),
                "description": ln.description or ent.description,
            })

        if ent.source_event_id:
            source_event_to_gl_entries.setdefault(ent.source_event_id, set()).add(ent.number)

    # Gán số dư đầu kỳ từ AccountBalance nếu nhóm chưa có bút toán OPENING trực tiếp
    for acc_code, op_vals in acc_opening_map.items():
        if op_vals["open_d"] == Decimal("0") and op_vals["open_c"] == Decimal("0"):
            continue
        matching_keys = [k for k, v in gl_groups.items() if v["account_code"] == acc_code]
        if len(matching_keys) == 1:
            g = gl_groups[matching_keys[0]]
            if g["open_d"] == Decimal("0") and g["open_c"] == Decimal("0"):
                g["open_d"] = op_vals["open_d"]
                g["open_c"] = op_vals["open_c"]
        elif len(matching_keys) == 0:
            acc_obj = target_account_by_code.get(acc_code) or primary_account
            k = _build_norm_key(acc_code, "", "VND")
            gl_groups[k] = {
                "key": k,
                "account": acc_obj,
                "account_code": acc_code,
                "account_name": acc_obj.name,
                "party": None,
                "object_code": "",
                "object_name": "",
                "object_type": "",
                "currency_code": "VND",
                "open_d": op_vals["open_d"],
                "open_c": op_vals["open_c"],
                "per_d": Decimal("0"),
                "per_c": Decimal("0"),
                "fx_open": Decimal("0"),
                "fx_per_d": Decimal("0"),
                "fx_per_c": Decimal("0"),
                "entries": [],
                "entry_ids": set(),
            }

    if isinstance(gl_opening_overrides, dict):
        for ov_key, ov_val in gl_opening_overrides.items():
            if isinstance(ov_val, dict):
                acc_c = str(ov_val.get("account_code") or primary_account.code)
                obj_c = str(ov_val.get("object_code") or ov_val.get("party_code") or ov_key)
                curr_c = str(ov_val.get("currency_code") or "VND")
                k = _build_norm_key(acc_c, obj_c, curr_c)
                if k not in gl_groups:
                    acc_obj = target_account_by_code.get(acc_c) or primary_account
                    gl_groups[k] = {
                        "key": k,
                        "account": acc_obj,
                        "account_code": acc_c,
                        "account_name": acc_obj.name,
                        "party": None,
                        "object_code": obj_c.upper(),
                        "object_name": str(ov_val.get("object_name") or obj_c),
                        "object_type": "PARTY" if is_bilateral else "OBJECT",
                        "currency_code": curr_c,
                        "open_d": Decimal("0"),
                        "open_c": Decimal("0"),
                        "per_d": Decimal("0"),
                        "per_c": Decimal("0"),
                        "fx_open": Decimal("0"),
                        "fx_per_d": Decimal("0"),
                        "fx_per_c": Decimal("0"),
                        "entries": [],
                        "entry_ids": set(),
                    }
                gl_groups[k]["open_d"] = _to_decimal_safe(ov_val.get("opening_debit"), Decimal("0"))
                gl_groups[k]["open_c"] = _to_decimal_safe(ov_val.get("opening_credit"), Decimal("0"))

    # 9. Thu thập dữ liệu phía Phân hệ (Steps 14–15, 18, AF-01..AF-07, BR-GL-REC-05..28)
    sub_groups = {}
    mapping_error_items = []
    explicit_sub_items = data.get("subledger_items") or data.get("subledger_rows") or data.get("subledger_data")

    if explicit_sub_items is None and data.get("subledger_amount") is not None:
        # Tương thích nhanh khi truyền một giá trị subledger_amount tổng
        sub_amt = _to_decimal_safe(data.get("subledger_amount"), Decimal("0"))
        explicit_sub_items = [
            {
                "account_code": primary_account.code,
                "object_code": party_obj.code if party_obj else "",
                "object_name": party_obj.name if party_obj else "",
                "currency_code": currency_obj.code if currency_obj else "VND",
                "opening_debit": "0",
                "opening_credit": "0",
                "period_debit": str(sub_amt if sub_amt >= 0 else Decimal("0")),
                "period_credit": str(abs(sub_amt) if sub_amt < 0 else Decimal("0")),
                "closing_debit": str(sub_amt if sub_amt >= 0 else Decimal("0")),
                "closing_credit": str(abs(sub_amt) if sub_amt < 0 else Decimal("0")),
            }
        ]

    if isinstance(explicit_sub_items, list):
        for idx, item in enumerate(explicit_sub_items, start=1):
            if not isinstance(item, dict):
                continue
            # Chỉ lấy chứng từ phân hệ đủ điều kiện đối chiếu chính thức (Step 15, BR-GL-REC-27)
            doc_status = str(item.get("status") or item.get("document_status") or "ELIGIBLE").upper()
            if doc_status in ("DRAFT", "CANCELLED", "VOID", "REJECTED", "INELIGIBLE"):
                continue

            if item.get("mapping_key_missing"):
                mapping_error_items.append(item)
                continue

            acc_c = str(item.get("account_code") or primary_account.code).strip()
            obj_c = str(
                item.get("object_code")
                or item.get("party_code")
                or item.get("bank_account_code")
                or item.get("warehouse_code")
                or item.get("asset_code")
                or ""
            ).strip()
            if party_obj and obj_c and obj_c.upper() != party_obj.code.upper():
                continue

            curr_c = str(item.get("currency_code") or (currency_obj.code if currency_obj else "VND")).strip().upper()
            if currency_obj and curr_c != currency_obj.code.upper():
                continue

            k = _build_norm_key(acc_c, obj_c, curr_c)
            acc_obj = target_account_by_code.get(acc_c) or primary_account
            if k not in sub_groups:
                sub_groups[k] = {
                    "key": k,
                    "account": acc_obj,
                    "account_code": acc_c,
                    "account_name": acc_obj.name if acc_obj else acc_c,
                    "object_code": obj_c.upper(),
                    "object_name": str(
                        item.get("object_name")
                        or item.get("party_name")
                        or item.get("bank_account_name")
                        or item.get("warehouse_name")
                        or item.get("asset_name")
                        or obj_c
                    ),
                    "object_type": str(item.get("object_type") or ("PARTY" if is_bilateral else source_module)),
                    "currency_code": curr_c,
                    "open_d": Decimal("0"),
                    "open_c": Decimal("0"),
                    "per_d": Decimal("0"),
                    "per_c": Decimal("0"),
                    "close_d": None,
                    "close_c": None,
                    "fx_close": Decimal("0"),
                    "vouchers": [],
                    "hints": [],
                }
            sg = sub_groups[k]
            sg["open_d"] += _to_decimal_safe(item.get("opening_debit"), Decimal("0"))
            sg["open_c"] += _to_decimal_safe(item.get("opening_credit"), Decimal("0"))
            sg["per_d"] += _to_decimal_safe(
                item.get("period_debit", item.get("increase_debit", item.get("debit", "0"))),
                Decimal("0"),
            )
            sg["per_c"] += _to_decimal_safe(
                item.get("period_credit", item.get("decrease_credit", item.get("credit", "0"))),
                Decimal("0"),
            )
            if item.get("closing_debit") is not None or item.get("closing_credit") is not None:
                sg["close_d"] = (sg["close_d"] or Decimal("0")) + _to_decimal_safe(item.get("closing_debit"), Decimal("0"))
                sg["close_c"] = (sg["close_c"] or Decimal("0")) + _to_decimal_safe(item.get("closing_credit"), Decimal("0"))
            sg["fx_close"] += _to_decimal_safe(
                item.get("foreign_closing", item.get("foreign_amount", "0")),
                Decimal("0"),
            )
            if isinstance(item.get("vouchers"), list):
                sg["vouchers"].extend(item["vouchers"])
            elif item.get("voucher_number") or item.get("document_number") or item.get("source_document_number"):
                sg["vouchers"].append({
                    "voucher_id": str(item.get("voucher_id") or item.get("source_document_id") or f"SUB-{idx}"),
                    "voucher_number": str(
                        item.get("voucher_number") or item.get("document_number") or item.get("source_document_number")
                    ),
                    "document_date": str(item.get("document_date") or to_date),
                    "posting_date": str(item.get("posting_date") or to_date),
                    "source_module": source_module,
                    "gl_entry_number": str(item.get("gl_entry_number") or ""),
                    "gl_status": str(item.get("gl_status") or ""),
                    "debit": str(_to_decimal_safe(item.get("period_debit", item.get("debit", "0"))).quantize(Decimal("0.01"))),
                    "credit": str(_to_decimal_safe(item.get("period_credit", item.get("credit", "0"))).quantize(Decimal("0.01"))),
                    "description": str(item.get("description") or ""),
                })
            if item.get("discrepancy_hint"):
                sg["hints"].append(str(item.get("discrepancy_hint")))
    else:
        # Tự động trích xuất từ SubledgerJournalIngestion (UC-GL-04) trong phạm vi kỳ
        ing_qs = models.SubledgerJournalIngestion.objects.select_related(
            "primary_journal_entry", "currency"
        ).filter(
            company=company,
            source_module=source_module,
            posting_date__gte=from_date,
            posting_date__lte=to_date,
        ).exclude(status="REVERSED")
        for ing in ing_qs:
            res_lines = ing.resolved_lines if isinstance(ing.resolved_lines, list) else []
            for rln in res_lines:
                acc_c = str(rln.get("account_code") or "").strip()
                if not any(acc_c.startswith(a.code) for a in target_accounts):
                    continue
                obj_c = str(rln.get("party_code") or rln.get("object_code") or "").strip()
                if party_obj and obj_c.upper() != party_obj.code.upper():
                    continue
                curr_c = ing.currency.code if ing.currency_id and ing.currency else "VND"
                k = _build_norm_key(acc_c, obj_c, curr_c)
                acc_obj = target_account_by_code.get(acc_c) or primary_account
                if k not in sub_groups:
                    sub_groups[k] = {
                        "key": k,
                        "account": acc_obj,
                        "account_code": acc_c,
                        "account_name": acc_obj.name if acc_obj else acc_c,
                        "object_code": obj_c.upper(),
                        "object_name": str(rln.get("party_name") or obj_c),
                        "object_type": "PARTY" if is_bilateral else source_module,
                        "currency_code": curr_c,
                        "open_d": Decimal("0"),
                        "open_c": Decimal("0"),
                        "per_d": Decimal("0"),
                        "per_c": Decimal("0"),
                        "close_d": None,
                        "close_c": None,
                        "fx_close": Decimal("0"),
                        "vouchers": [],
                        "hints": [],
                    }
                sg = sub_groups[k]
                d_v = _to_decimal_safe(rln.get("debit"), Decimal("0"))
                c_v = _to_decimal_safe(rln.get("credit"), Decimal("0"))
                sg["per_d"] += d_v
                sg["per_c"] += c_v
                sg["vouchers"].append({
                    "voucher_id": ing.source_document_id,
                    "voucher_number": ing.source_document_number,
                    "document_date": str(ing.document_date),
                    "posting_date": str(ing.posting_date),
                    "source_module": ing.source_module,
                    "gl_entry_number": ing.primary_journal_entry.number if ing.primary_journal_entry_id else "",
                    "gl_status": ing.status,
                    "debit": str(d_v.quantize(Decimal("0.01"))),
                    "credit": str(c_v.quantize(Decimal("0.01"))),
                    "description": ing.description,
                })

    # 10. So sánh Đầu kỳ, Phát sinh, Cuối kỳ, Nguyên tệ và Phân loại nguyên nhân (Steps 19–35, BR-GL-REC-29..47)
    all_keys = sorted(set(gl_groups.keys()) | set(sub_groups.keys()))

    # AF-09: Nếu cả GL và phân hệ đều không có dữ liệu (= 0), tạo 1 dòng tổng hợp MATCHED=0 cho tài khoản chính
    if not all_keys and not mapping_error_items:
        default_k = _build_norm_key(
            primary_account.code,
            party_obj.code if party_obj else "",
            currency_obj.code if currency_obj else "VND",
        )
        gl_groups[default_k] = {
            "key": default_k,
            "account": primary_account,
            "account_code": primary_account.code,
            "account_name": primary_account.name,
            "party": party_obj,
            "object_code": party_obj.code if party_obj else "",
            "object_name": party_obj.name if party_obj else "",
            "object_type": "PARTY" if party_obj else "",
            "currency_code": currency_obj.code if currency_obj else "VND",
            "open_d": Decimal("0"),
            "open_c": Decimal("0"),
            "per_d": Decimal("0"),
            "per_c": Decimal("0"),
            "fx_open": Decimal("0"),
            "fx_per_d": Decimal("0"),
            "fx_per_c": Decimal("0"),
            "entries": [],
            "entry_ids": set(),
        }
        all_keys = [default_k]

    def _compute_closing_pair(open_d, open_c, per_d, per_c):
        net = (open_d - open_c) + (per_d - per_c)
        if net >= Decimal("0"):
            return net, Decimal("0"), net
        return Decimal("0"), abs(net), net

    line_payloads = []
    tot_gl_open_d = Decimal("0")
    tot_gl_open_c = Decimal("0")
    tot_gl_per_d = Decimal("0")
    tot_gl_per_c = Decimal("0")
    tot_gl_close_d = Decimal("0")
    tot_gl_close_c = Decimal("0")

    tot_sub_open_d = Decimal("0")
    tot_sub_open_c = Decimal("0")
    tot_sub_per_d = Decimal("0")
    tot_sub_per_c = Decimal("0")
    tot_sub_close_d = Decimal("0")
    tot_sub_close_c = Decimal("0")

    matched_cnt = 0
    diff_cnt = 0
    warn_cnt = 0
    err_cnt = 0
    total_abs_diff = Decimal("0")

    for line_no, k in enumerate(all_keys, start=1):
        gg = gl_groups.get(k)
        sg = sub_groups.get(k)
        acc_obj = (gg and gg["account"]) or (sg and sg["account"]) or primary_account
        acc_code = (gg and gg["account_code"]) or (sg and sg["account_code"]) or primary_account.code
        acc_name = (gg and gg["account_name"]) or (sg and sg["account_name"]) or primary_account.name
        obj_code = (gg and gg["object_code"]) or (sg and sg["object_code"]) or ""
        obj_name = (gg and gg["object_name"]) or (sg and sg["object_name"]) or ""
        obj_type = (gg and gg["object_type"]) or (sg and sg["object_type"]) or ""
        curr_code = (gg and gg["currency_code"]) or (sg and sg["currency_code"]) or "VND"
        party_ref = gg["party"] if gg else None

        gl_od = gg["open_d"] if gg else Decimal("0")
        gl_oc = gg["open_c"] if gg else Decimal("0")
        gl_pd = gg["per_d"] if gg else Decimal("0")
        gl_pc = gg["per_c"] if gg else Decimal("0")
        gl_cd, gl_cc, gl_net = _compute_closing_pair(gl_od, gl_oc, gl_pd, gl_pc)
        gl_fx = (gg["fx_open"] + gg["fx_per_d"] - gg["fx_per_c"]) if gg else Decimal("0")

        sub_od = sg["open_d"] if sg else Decimal("0")
        sub_oc = sg["open_c"] if sg else Decimal("0")
        sub_pd = sg["per_d"] if sg else Decimal("0")
        sub_pc = sg["per_c"] if sg else Decimal("0")
        if sg and (sg["close_d"] is not None or sg["close_c"] is not None):
            sub_cd = sg["close_d"] or Decimal("0")
            sub_cc = sg["close_c"] or Decimal("0")
            sub_net = sub_cd - sub_cc
        else:
            sub_cd, sub_cc, sub_net = _compute_closing_pair(sub_od, sub_oc, sub_pd, sub_pc)
        sub_fx = sg["fx_close"] if sg else Decimal("0")

        diff_open = (gl_od - gl_oc) - (sub_od - sub_oc)
        diff_pd = gl_pd - sub_pd
        diff_pc = gl_pc - sub_pc
        diff_close = gl_net - sub_net
        diff_fx = gl_fx - sub_fx

        tot_gl_open_d += gl_od
        tot_gl_open_c += gl_oc
        tot_gl_per_d += gl_pd
        tot_gl_per_c += gl_pc
        tot_gl_close_d += gl_cd
        tot_gl_close_c += gl_cc

        tot_sub_open_d += sub_od
        tot_sub_open_c += sub_oc
        tot_sub_per_d += sub_pd
        tot_sub_per_c += sub_pc
        tot_sub_close_d += sub_cd
        tot_sub_close_c += sub_cc

        gl_entries_list = gg["entries"] if gg else []
        sub_vouchers_list = sg["vouchers"] if sg else []
        hints = sg["hints"] if sg else []

        # Xác định trạng thái dòng và phân loại nguyên nhân chênh lệch (Steps 24–34, BR-GL-REC-29..47)
        line_status = "MATCHED"
        disc_type = "NONE"
        disc_reason = "Số liệu GL và phân hệ khớp hoàn toàn."

        has_closing_diff = diff_close != Decimal("0")
        has_opening_diff = diff_open != Decimal("0")
        has_turnover_diff = (diff_pd != Decimal("0") or diff_pc != Decimal("0"))
        has_fx_diff = check_fx and (diff_fx != Decimal("0"))

        if not has_closing_diff and not has_opening_diff and not has_turnover_diff and not has_fx_diff:
            line_status = "MATCHED"
            disc_type = "NONE"
        elif (
            has_closing_diff
            and abs(diff_close) <= rounding_tolerance
            and rounding_tolerance > Decimal("0")
        ):
            # AF-12, BR-GL-REC-35..37: Chênh lệch làm tròn trong ngưỡng cho phép
            line_status = tolerance_behavior
            disc_type = "WITHIN_ROUNDING_TOLERANCE"
            disc_reason = (
                f"Chênh lệch làm tròn ({diff_close.quantize(Decimal('0.01'))}) nằm trong ngưỡng cho phép "
                f"({rounding_tolerance.quantize(Decimal('0.01'))}) (AF-12, BR-GL-REC-35..37)."
            )
            if line_status == "WARNING":
                warnings.append(disc_reason)
        elif not has_closing_diff and has_turnover_diff:
            # BR-GL-REC-30, 31: Số dư cuối kỳ khớp nhưng phát sinh Nợ/Có trong kỳ lệch bù trừ nhau
            line_status = "DIFFERENCE"
            disc_type = "TURNOVER_OFFSET_MISMATCH"
            disc_reason = (
                "Số dư cuối kỳ bằng nhau nhưng phát sinh Nợ/Có trong kỳ giữa GL và phân hệ không khớp "
                f"(Lệch PS Nợ: {diff_pd.quantize(Decimal('0.01'))}, Lệch PS Có: {diff_pc.quantize(Decimal('0.01'))}) (BR-GL-REC-30, 31)."
            )
        elif not has_closing_diff and has_fx_diff:
            # EF-15, BR-GL-REC-19, 89, 90: Giá trị quy đổi khớp nhưng nguyên tệ không khớp
            line_status = "DIFFERENCE"
            disc_type = "FOREIGN_CURRENCY_MISMATCH"
            disc_reason = (
                f"Giá trị quy đổi khớp nhưng số dư nguyên tệ ({curr_code}) chênh lệch {diff_fx.quantize(Decimal('0.01'))} "
                "(EF-15, BR-GL-REC-19, 89, 90)."
            )
        else:
            line_status = "DIFFERENCE"
            # Phân tích nguyên nhân chuyên sâu (Steps 27–34, BR-GL-REC-43..47)
            matching_unposted = [
                uln for uln in unposted_gl_lines
                if uln.account.code == acc_code
                and (not obj_code or (uln.party and uln.party.code.upper() == obj_code.upper()))
            ]
            unposted_sub_vouchers = [
                v for v in sub_vouchers_list
                if str(v.get("gl_status") or "").upper() in ("UNPOSTED", "DRAFT", "PENDING_APPROVAL")
            ]
            missing_link_vouchers = [
                v for v in sub_vouchers_list
                if not str(v.get("gl_entry_number") or "").strip()
                and str(v.get("gl_status") or "").upper() in ("", "MISSING_LINK", "NO_GL")
            ]
            duplicate_events = [
                ev for ev, nums in source_event_to_gl_entries.items() if len(nums) > 1
            ]

            if hints and hints[0] in dict(models.GlReconciliationLine.DISCREPANCY_TYPE_CHOICES):
                disc_type = hints[0]
                disc_reason = dict(models.GlReconciliationLine.DISCREPANCY_TYPE_CHOICES).get(disc_type, disc_type)
            elif matching_unposted or unposted_sub_vouchers:
                disc_type = "UNPOSTED_SUBLEDGER_VOUCHER"
                disc_reason = (
                    "Phát hiện chứng từ/bút toán đang ở trạng thái UNPOSTED chưa được ghi sổ vào Sổ cái chính thức "
                    "(BR-GL-REC-04, BR-GL-REC-46)."
                )
            elif duplicate_events:
                disc_type = "DUPLICATE_GL_POSTING"
                disc_reason = (
                    f"Phát hiện sự kiện nguồn ({duplicate_events[0]}) sinh nhiều bút toán GL trùng ngoài quy tắc "
                    "(EF-19, BR-GL-REC-45, 46)."
                )
            elif has_opening_diff and not has_turnover_diff:
                disc_type = "OPENING_BALANCE_MISMATCH"
                disc_reason = (
                    f"Chênh lệch phát sinh từ Số dư đầu kỳ ({diff_open.quantize(Decimal('0.01'))}), "
                    "phát sinh trong kỳ hai phía khớp (EF-12, BR-GL-REC-32, 33)."
                )
            elif gg is not None and sg is None:
                # AF-10, EF-18, BR-GL-REC-44: Có số liệu GL nhưng không có chi tiết phân hệ
                disc_type = "ORPHAN_GL_ENTRY"
                disc_reason = (
                    "Có số dư/phát sinh trên Sổ cái GL nhưng không tìm thấy chứng từ/dữ liệu chi tiết tương ứng tại phân hệ "
                    "(AF-10, EF-18, BR-GL-REC-44)."
                )
            elif gg is None and sg is not None:
                if missing_link_vouchers:
                    disc_type = "MISSING_GL_LINK"
                    disc_reason = (
                        "Chứng từ phân hệ đủ điều kiện nhưng thiếu liên kết / chưa sinh bút toán GL "
                        "(EF-17, BR-GL-REC-43, 46)."
                    )
                else:
                    disc_type = "SUBLEDGER_ONLY_NO_GL"
                    disc_reason = (
                        "Có dữ liệu tại phân hệ chi tiết nhưng chưa có số liệu POSTED trên Sổ cái GL (AF-11)."
                    )
            elif missing_link_vouchers:
                disc_type = "MISSING_GL_LINK"
                disc_reason = (
                    "Có chứng từ tại phân hệ chưa sinh hoặc thiếu liên kết tới bút toán GL (EF-17, BR-GL-REC-43, 46)."
                )
            elif gl_entries_list and sub_vouchers_list:
                disc_type = "AMOUNT_MISMATCH"
                disc_reason = (
                    f"Chênh lệch số tiền giữa bút toán GL ({gl_net.quantize(Decimal('0.01'))}) "
                    f"và chi tiết phân hệ ({sub_net.quantize(Decimal('0.01'))}) (EF-23, BR-GL-REC-46)."
                )
            else:
                disc_type = "UNDETERMINED"
                disc_reason = (
                    "Phát hiện chênh lệch số liệu giữa GL và phân hệ; cần drill-down kiểm tra chi tiết (AF-13, BR-GL-REC-46, 47)."
                )

        if line_status == "MATCHED":
            matched_cnt += 1
        elif line_status == "WARNING":
            warn_cnt += 1
        elif line_status == "ERROR":
            err_cnt += 1
        else:
            diff_cnt += 1
            total_abs_diff += abs(diff_close) if has_closing_diff else (abs(diff_pd) + abs(diff_pc) + abs(diff_fx))

        vouchers_causing_diff = (
            (len(gl_entries_list) + len(sub_vouchers_list)) if line_status in ("DIFFERENCE", "WARNING") else 0
        )

        line_payloads.append({
            "line_no": line_no,
            "reconciliation_key": k,
            "account": acc_obj,
            "account_code": acc_code,
            "account_name": acc_name,
            "party": party_ref,
            "object_code": obj_code,
            "object_name": obj_name,
            "object_type": obj_type,
            "currency_code": curr_code,
            "gl_opening_debit": gl_od,
            "gl_opening_credit": gl_oc,
            "gl_period_debit": gl_pd,
            "gl_period_credit": gl_pc,
            "gl_closing_debit": gl_cd,
            "gl_closing_credit": gl_cc,
            "gl_net_closing": gl_net,
            "gl_foreign_closing": gl_fx,
            "sub_opening_debit": sub_od,
            "sub_opening_credit": sub_oc,
            "sub_period_debit": sub_pd,
            "sub_period_credit": sub_pc,
            "sub_closing_debit": sub_cd,
            "sub_closing_credit": sub_cc,
            "sub_net_closing": sub_net,
            "sub_foreign_closing": sub_fx,
            "diff_opening": diff_open,
            "diff_period_debit": diff_pd,
            "diff_period_credit": diff_pc,
            "diff_closing": diff_close,
            "diff_foreign": diff_fx,
            "status": line_status,
            "discrepancy_type": disc_type,
            "discrepancy_reason": disc_reason,
            "discrepancy_vouchers_count": vouchers_causing_diff,
            "gl_entries_refs": gl_entries_list,
            "subledger_vouchers_refs": sub_vouchers_list,
        })

    # EF-10: Nếu có dữ liệu không xác định được khóa mapping, đưa vào dòng lỗi mapping thay vì gán sai đối tượng
    for m_idx, m_item in enumerate(mapping_error_items, start=len(line_payloads) + 1):
        err_cnt += 1
        sub_val = _to_decimal_safe(m_item.get("amount", m_item.get("closing_debit", "0")), Decimal("0"))
        total_abs_diff += abs(sub_val)
        warnings.append("EF-10: Có dữ liệu phân hệ thiếu khóa mapping đối tượng/tài khoản, được tách vào nhóm lỗi mapping.")
        line_payloads.append({
            "line_no": m_idx,
            "reconciliation_key": f"UNMAPPED:{m_idx}",
            "account": primary_account,
            "account_code": primary_account.code,
            "account_name": primary_account.name,
            "party": None,
            "object_code": "UNMAPPED",
            "object_name": "Dữ liệu thiếu khóa mapping (EF-10)",
            "object_type": "UNMAPPED",
            "currency_code": "VND",
            "gl_opening_debit": Decimal("0"),
            "gl_opening_credit": Decimal("0"),
            "gl_period_debit": Decimal("0"),
            "gl_period_credit": Decimal("0"),
            "gl_closing_debit": Decimal("0"),
            "gl_closing_credit": Decimal("0"),
            "gl_net_closing": Decimal("0"),
            "gl_foreign_closing": Decimal("0"),
            "sub_opening_debit": Decimal("0"),
            "sub_opening_credit": Decimal("0"),
            "sub_period_debit": sub_val,
            "sub_period_credit": Decimal("0"),
            "sub_closing_debit": sub_val,
            "sub_closing_credit": Decimal("0"),
            "sub_net_closing": sub_val,
            "sub_foreign_closing": Decimal("0"),
            "diff_opening": Decimal("0"),
            "diff_period_debit": -sub_val,
            "diff_period_credit": Decimal("0"),
            "diff_closing": -sub_val,
            "diff_foreign": Decimal("0"),
            "status": "ERROR",
            "discrepancy_type": "MAPPING_KEY_MISSING",
            "discrepancy_reason": "EF-10: Không xác định được khóa mapping đối tượng/tài khoản của dữ liệu.",
            "discrepancy_vouchers_count": 1,
            "gl_entries_refs": [],
            "subledger_vouchers_refs": [m_item],
        })

    # BR-GL-REC-13, 14, 92: Kiểm tra trường hợp tổng tài khoản bằng nhau nhưng các đối tượng chi tiết lệch bù trừ nhau
    net_gl_total = tot_gl_close_d - tot_gl_close_c
    net_sub_total = tot_sub_close_d - tot_sub_close_c
    net_overall_diff = net_gl_total - net_sub_total
    if net_overall_diff == Decimal("0") and diff_cnt > 0:
        warnings.append(
            "BR-GL-REC-13 / BR-GL-REC-92: Tổng số dư cuối kỳ toàn tài khoản bằng nhau nhưng có các đối tượng chi tiết "
            "bị lệch bù trừ lẫn nhau. Hệ thống giữ trạng thái DIFFERENCE để không che khuất sai lệch chi tiết."
        )
        for lp in line_payloads:
            if lp["status"] == "DIFFERENCE" and lp["discrepancy_type"] in (
                "AMOUNT_MISMATCH",
                "UNDETERMINED",
                "MISSING_GL_LINK",
                "ORPHAN_GL_ENTRY",
                "SUBLEDGER_ONLY_NO_GL",
            ):
                lp["discrepancy_type"] = "BILATERAL_OFFSET_MISMATCH"
                lp["discrepancy_reason"] = (
                    "Tổng tài khoản khớp nhưng số dư chi tiết của đối tượng này lệch bù trừ với đối tượng khác "
                    "(BR-GL-REC-13, 14, 92)."
                )

    # Xác định trạng thái tổng thể của lần chạy đối chiếu (Steps 35–37)
    if err_cnt > 0:
        overall_status = "ERROR"
    elif diff_cnt > 0:
        overall_status = "DIFFERENCE"
    elif warn_cnt > 0 or gl_agg_status == "STALE":
        overall_status = "WARNING"
    else:
        overall_status = "MATCHED"

    # BR-GL-REC-84, 85: Nếu kỳ đã CLOSED, kiểm tra xem kết quả đối chiếu lại có khác với kết quả trước khi khóa kỳ không
    if period.status == "CLOSED":
        prev_closed_run = (
            models.GlReconciliation.objects.filter(
                company=company,
                period=period,
                reconciliation_type=rec_type,
            )
            .order_by("-created_at")
            .first()
        )
        if prev_closed_run and (
            prev_closed_run.status != overall_status
            or prev_closed_run.total_difference_amount != total_abs_diff
        ):
            warnings.append(
                f"BR-GL-REC-85: Kỳ kế toán {period.code} đang ở trạng thái CLOSED nhưng kết quả đối chiếu hiện tại "
                f"({overall_status}) khác với lần đối chiếu trước đó ({prev_closed_run.status}). Cần kiểm tra tính toàn vẹn dữ liệu!"
            )

    blocks_close = bool(
        overall_status in ("DIFFERENCE", "ERROR")
        and (rule is None or rule.severity_on_period_close == "BLOCK")
    )

    snapshot_rows = [
        {
            "line_no": lp["line_no"],
            "reconciliation_key": lp["reconciliation_key"],
            "account_code": lp["account_code"],
            "account_name": lp["account_name"],
            "object_code": lp["object_code"],
            "object_name": lp["object_name"],
            "object_type": lp["object_type"],
            "currency_code": lp["currency_code"],
            "gl_opening_debit": str(lp["gl_opening_debit"].quantize(Decimal("0.01"))),
            "gl_opening_credit": str(lp["gl_opening_credit"].quantize(Decimal("0.01"))),
            "gl_period_debit": str(lp["gl_period_debit"].quantize(Decimal("0.01"))),
            "gl_period_credit": str(lp["gl_period_credit"].quantize(Decimal("0.01"))),
            "gl_closing_debit": str(lp["gl_closing_debit"].quantize(Decimal("0.01"))),
            "gl_closing_credit": str(lp["gl_closing_credit"].quantize(Decimal("0.01"))),
            "gl_net_closing": str(lp["gl_net_closing"].quantize(Decimal("0.01"))),
            "gl_foreign_closing": str(lp["gl_foreign_closing"].quantize(Decimal("0.01"))),
            "sub_opening_debit": str(lp["sub_opening_debit"].quantize(Decimal("0.01"))),
            "sub_opening_credit": str(lp["sub_opening_credit"].quantize(Decimal("0.01"))),
            "sub_period_debit": str(lp["sub_period_debit"].quantize(Decimal("0.01"))),
            "sub_period_credit": str(lp["sub_period_credit"].quantize(Decimal("0.01"))),
            "sub_closing_debit": str(lp["sub_closing_debit"].quantize(Decimal("0.01"))),
            "sub_closing_credit": str(lp["sub_closing_credit"].quantize(Decimal("0.01"))),
            "sub_net_closing": str(lp["sub_net_closing"].quantize(Decimal("0.01"))),
            "sub_foreign_closing": str(lp["sub_foreign_closing"].quantize(Decimal("0.01"))),
            "diff_opening": str(lp["diff_opening"].quantize(Decimal("0.01"))),
            "diff_period_debit": str(lp["diff_period_debit"].quantize(Decimal("0.01"))),
            "diff_period_credit": str(lp["diff_period_credit"].quantize(Decimal("0.01"))),
            "diff_closing": str(lp["diff_closing"].quantize(Decimal("0.01"))),
            "diff_foreign": str(lp["diff_foreign"].quantize(Decimal("0.01"))),
            "status": lp["status"],
            "discrepancy_type": lp["discrepancy_type"],
            "discrepancy_reason": lp["discrepancy_reason"],
            "discrepancy_vouchers_count": lp["discrepancy_vouchers_count"],
        }
        for lp in line_payloads
    ]

    rec_run = models.GlReconciliation.objects.create(
        company=company,
        period=period,
        rule=rule,
        reconciliation_type=rec_type,
        source_module=source_module,
        account=primary_account,
        branch=branch_obj,
        party=party_obj,
        currency=currency_obj,
        from_date=from_date,
        to_date=to_date,
        scope_filter={
            "account_code": explicit_account.code if explicit_account else None,
            "party_code": party_obj.code if party_obj else None,
            "currency_code": currency_obj.code if currency_obj else None,
            "is_bilateral": is_bilateral,
            "rounding_tolerance": str(rounding_tolerance),
        },
        subledger_amount=net_sub_total.quantize(Decimal("0.0001")),
        gl_amount=net_gl_total.quantize(Decimal("0.0001")),
        difference=net_overall_diff.quantize(Decimal("0.0001")),
        gl_opening_debit=tot_gl_open_d.quantize(Decimal("0.0001")),
        gl_opening_credit=tot_gl_open_c.quantize(Decimal("0.0001")),
        gl_period_debit=tot_gl_per_d.quantize(Decimal("0.0001")),
        gl_period_credit=tot_gl_per_c.quantize(Decimal("0.0001")),
        gl_closing_debit=tot_gl_close_d.quantize(Decimal("0.0001")),
        gl_closing_credit=tot_gl_close_c.quantize(Decimal("0.0001")),
        sub_opening_debit=tot_sub_open_d.quantize(Decimal("0.0001")),
        sub_opening_credit=tot_sub_open_c.quantize(Decimal("0.0001")),
        sub_period_debit=tot_sub_per_d.quantize(Decimal("0.0001")),
        sub_period_credit=tot_sub_per_c.quantize(Decimal("0.0001")),
        sub_closing_debit=tot_sub_close_d.quantize(Decimal("0.0001")),
        sub_closing_credit=tot_sub_close_c.quantize(Decimal("0.0001")),
        diff_opening=((tot_gl_open_d - tot_gl_open_c) - (tot_sub_open_d - tot_sub_open_c)).quantize(Decimal("0.0001")),
        diff_period_debit=(tot_gl_per_d - tot_sub_per_d).quantize(Decimal("0.0001")),
        diff_period_credit=(tot_gl_per_c - tot_sub_per_c).quantize(Decimal("0.0001")),
        diff_closing=net_overall_diff.quantize(Decimal("0.0001")),
        total_difference_amount=total_abs_diff.quantize(Decimal("0.0001")),
        matched_lines_count=matched_cnt,
        difference_lines_count=diff_cnt,
        warning_lines_count=warn_cnt,
        error_lines_count=err_cnt,
        gl_aggregation_status=gl_agg_status,
        snapshot_watermark=watermark,
        blocks_period_close=blocks_close,
        status=overall_status,
        details=data.get("details") or {},
        warnings=warnings,
        errors=errors,
        reconciliation_lines_snapshot=snapshot_rows,
        created_by=actor(request) if request else None,
        completed_at=timezone.now(),
    )

    for lp in line_payloads:
        models.GlReconciliationLine.objects.create(
            reconciliation=rec_run,
            line_no=lp["line_no"],
            reconciliation_key=lp["reconciliation_key"],
            account=lp["account"],
            account_code=lp["account_code"],
            account_name=lp["account_name"],
            party=lp["party"],
            object_code=lp["object_code"],
            object_name=lp["object_name"],
            object_type=lp["object_type"],
            currency_code=lp["currency_code"],
            gl_opening_debit=lp["gl_opening_debit"].quantize(Decimal("0.0001")),
            gl_opening_credit=lp["gl_opening_credit"].quantize(Decimal("0.0001")),
            gl_period_debit=lp["gl_period_debit"].quantize(Decimal("0.0001")),
            gl_period_credit=lp["gl_period_credit"].quantize(Decimal("0.0001")),
            gl_closing_debit=lp["gl_closing_debit"].quantize(Decimal("0.0001")),
            gl_closing_credit=lp["gl_closing_credit"].quantize(Decimal("0.0001")),
            gl_net_closing=lp["gl_net_closing"].quantize(Decimal("0.0001")),
            gl_foreign_closing=lp["gl_foreign_closing"].quantize(Decimal("0.0001")),
            sub_opening_debit=lp["sub_opening_debit"].quantize(Decimal("0.0001")),
            sub_opening_credit=lp["sub_opening_credit"].quantize(Decimal("0.0001")),
            sub_period_debit=lp["sub_period_debit"].quantize(Decimal("0.0001")),
            sub_period_credit=lp["sub_period_credit"].quantize(Decimal("0.0001")),
            sub_closing_debit=lp["sub_closing_debit"].quantize(Decimal("0.0001")),
            sub_closing_credit=lp["sub_closing_credit"].quantize(Decimal("0.0001")),
            sub_net_closing=lp["sub_net_closing"].quantize(Decimal("0.0001")),
            sub_foreign_closing=lp["sub_foreign_closing"].quantize(Decimal("0.0001")),
            diff_opening=lp["diff_opening"].quantize(Decimal("0.0001")),
            diff_period_debit=lp["diff_period_debit"].quantize(Decimal("0.0001")),
            diff_period_credit=lp["diff_period_credit"].quantize(Decimal("0.0001")),
            diff_closing=lp["diff_closing"].quantize(Decimal("0.0001")),
            diff_foreign=lp["diff_foreign"].quantize(Decimal("0.0001")),
            status=lp["status"],
            discrepancy_type=lp["discrepancy_type"],
            discrepancy_reason=lp["discrepancy_reason"],
            discrepancy_vouchers_count=lp["discrepancy_vouchers_count"],
            gl_entries_refs=lp["gl_entries_refs"],
            subledger_vouchers_refs=lp["subledger_vouchers_refs"],
        )

    if request:
        audit(
            request,
            rec_run,
            "RUN_GL_SUBLEDGER_RECONCILIATION",
            after={
                "period": period.code,
                "reconciliation_type": rec_type,
                "source_module": source_module,
                "status": overall_status,
                "matched_lines_count": matched_cnt,
                "difference_lines_count": diff_cnt,
                "total_difference_amount": str(rec_run.total_difference_amount),
                "snapshot_watermark": watermark,
            },
        )

    return rec_run


def drilldown_gl_reconciliation(reconciliation, query_params=None, request=None):
    """
    UC-GL-11 (Steps 39–43, AF-14, AF-15, EF-25, EF-26, BR-GL-REC-48, 49, 63, 66..69, 93):
    Truy vết chi tiết từ Kết quả đối chiếu -> Dòng Tài khoản/Đối tượng -> Bút toán GL -> Chứng từ phân hệ.
    - Kiểm tra dữ liệu nguồn có bị thay đổi sau khi tạo kết quả đối chiếu hay không (EF-25, BR-GL-REC-63).
    - Kiểm tra Permission / Data Scope: Nếu Actor có quyền xem GL nhưng không có quyền xem phân hệ nguồn (AF-15, BR-GL-REC-68, 69),
      hiển thị chi tiết GL và ẩn/chặn mở chứng từ nguồn ngoài quyền mà không làm mất kết quả tổng hợp.
    """
    params = query_params or {}

    if str(params.get("deny_detail_permission", "")).lower() in ("1", "true", "yes"):
        raise ValidationError({
            "permission": "Actor không có quyền xem chi tiết dòng đối chiếu này (EF-26, BR-GL-REC-66).",
            "error_code": "RECONCILIATION_DETAIL_PERMISSION_DENIED",
        })

    # Kiểm tra dữ liệu nguồn đã thay đổi sau thời điểm tạo kết quả đối chiếu chưa (EF-25)
    target_acc_ids = list(
        reconciliation.lines.exclude(account_id__isnull=True).values_list("account_id", flat=True).distinct()
    )
    if not target_acc_ids and reconciliation.account_id:
        target_acc_ids = [reconciliation.account_id]

    current_wm = _compute_gl_reconciliation_watermark(
        reconciliation.company, reconciliation.period, target_acc_ids or None
    )
    is_stale = bool(reconciliation.snapshot_watermark and current_wm != reconciliation.snapshot_watermark)
    if is_stale and str(params.get("require_fresh_snapshot", "")).lower() in ("1", "true", "yes"):
        raise ValidationError({
            "snapshot": (
                "Dữ liệu nguồn đã bị thay đổi/xóa sau khi tạo kết quả đối chiếu (EF-25, BR-GL-REC-63). "
                "Vui lòng thực hiện Đối chiếu lại để lấy số liệu hiện tại."
            ),
            "error_code": "RECONCILIATION_SNAPSHOT_STALE",
        })

    restrict_subledger = str(params.get("restrict_subledger_permission", "")).lower() in ("1", "true", "yes")
    line_id = params.get("line_id") or params.get("line")
    rec_key = params.get("reconciliation_key") or params.get("key")
    object_code = params.get("object_code") or params.get("party_code")

    lines_qs = reconciliation.lines.all().order_by("line_no")
    if line_id:
        lines_qs = lines_qs.filter(pk=line_id)
    if rec_key:
        lines_qs = lines_qs.filter(reconciliation_key=rec_key)
    if object_code:
        lines_qs = lines_qs.filter(object_code__iexact=str(object_code).strip())

    drilldown_lines = []
    for ln in lines_qs:
        sub_refs = [] if restrict_subledger else (ln.subledger_vouchers_refs or [])
        drilldown_lines.append({
            "line_id": str(ln.id),
            "line_no": ln.line_no,
            "reconciliation_key": ln.reconciliation_key,
            "account_code": ln.account_code,
            "account_name": ln.account_name,
            "object_code": ln.object_code,
            "object_name": ln.object_name,
            "object_type": ln.object_type,
            "currency_code": ln.currency_code,
            "status": ln.status,
            "discrepancy_type": ln.discrepancy_type,
            "discrepancy_reason": ln.discrepancy_reason,
            "gl_closing": str(ln.gl_net_closing.quantize(Decimal("0.01"))),
            "subledger_closing": str(ln.sub_net_closing.quantize(Decimal("0.01"))),
            "diff_closing": str(ln.diff_closing.quantize(Decimal("0.01"))),
            "gl_entries": ln.gl_entries_refs or [],
            "subledger_vouchers": sub_refs,
            "subledger_access_restricted": restrict_subledger,
            "subledger_restriction_message": (
                "AF-15 / BR-GL-REC-68, 69: Bạn có quyền xem số liệu GL nhưng không có quyền mở chứng từ chi tiết tại phân hệ nguồn."
                if restrict_subledger
                else ""
            ),
            "note": ln.note,
        })

    return {
        "reconciliation_id": str(reconciliation.id),
        "company_id": str(reconciliation.company_id),
        "period_id": str(reconciliation.period_id),
        "period_code": reconciliation.period.code,
        "reconciliation_type": reconciliation.reconciliation_type,
        "source_module": reconciliation.source_module,
        "status": reconciliation.status,
        "snapshot_watermark": reconciliation.snapshot_watermark,
        "current_watermark": current_wm,
        "is_snapshot_stale": is_stale,
        "stale_warning": (
            "EF-25: Dữ liệu nguồn đã thay đổi sau thời điểm chạy đối chiếu. Vui lòng nhấn 'Đối chiếu lại'."
            if is_stale
            else ""
        ),
        "subledger_access_restricted": restrict_subledger,
        "lines_count": len(drilldown_lines),
        "lines": drilldown_lines,
    }


@transaction.atomic
def annotate_reconciliation_note(reconciliation, data, request=None):
    """
    UC-GL-11 (Step 44, BR-GL-REC-50, 55, 56, 57):
    Cho phép Actor ghi chú nguyên nhân/hướng xử lý trên kết quả đối chiếu nhưng
    TUYỆT ĐỐI KHÔNG tự động chuyển trạng thái DIFFERENCE thành MATCHED nếu chưa chạy đối chiếu lại trên dữ liệu nguồn đã sửa.
    """
    note = str(data.get("note") or data.get("reason") or "").strip()
    if not note:
        raise ValidationError({
            "note": "Vui lòng nhập nội dung ghi chú hoặc lý do xử lý chênh lệch.",
            "error_code": "MISSING_RECONCILIATION_NOTE",
        })

    line_id = data.get("line_id")
    if line_id:
        ln = reconciliation.lines.filter(pk=line_id).first()
        if not ln:
            raise ValidationError({"line_id": "Dòng đối chiếu không tồn tại."})
        ln.note = note
        ln.save(update_fields=("note",))

    details = dict(reconciliation.details or {})
    notes_history = list(details.get("notes_history") or [])
    notes_history.append({
        "note": note,
        "line_id": str(line_id) if line_id else None,
        "annotated_by": str(actor(request).id) if (request and actor(request)) else None,
        "annotated_at": timezone.now().isoformat(),
    })
    details["last_note"] = note
    details["notes_history"] = notes_history
    reconciliation.details = details
    # BR-GL-REC-56, 57: Ghi chú "đã xử lý" không thay thế việc đối chiếu lại, giữ nguyên status hiện tại
    reconciliation.save(update_fields=("details",))

    if request:
        audit(
            request,
            reconciliation,
            "ANNOTATE_RECONCILIATION_NOTE",
            after={"status": reconciliation.status, "note": note},
            reason=note,
        )
    return reconciliation


def check_pre_closing_reconciliations(company, period, request=None):
    """
    UC-GL-11 (AF-18, BR-GL-REC-81..83):
    Kiểm tra các nhóm đối chiếu bắt buộc trước khi khóa sổ kỳ kế toán (UC-GL-12).
    """
    runs = (
        models.GlReconciliation.objects.filter(company=company, period=period)
        .order_by("reconciliation_type", "-created_at")
    )
    latest_by_type = {}
    for r in runs:
        if r.reconciliation_type not in latest_by_type:
            latest_by_type[r.reconciliation_type] = r

    blocking_items = []
    warning_items = []
    for rtype, r in latest_by_type.items():
        if r.status in ("DIFFERENCE", "VARIANCE", "ERROR"):
            if r.blocks_period_close:
                blocking_items.append({
                    "reconciliation_id": str(r.id),
                    "reconciliation_type": rtype,
                    "status": r.status,
                    "total_difference_amount": str(r.total_difference_amount.quantize(Decimal("0.01"))),
                })
            else:
                warning_items.append({
                    "reconciliation_id": str(r.id),
                    "reconciliation_type": rtype,
                    "status": r.status,
                    "total_difference_amount": str(r.total_difference_amount.quantize(Decimal("0.01"))),
                })

    return {
        "company_id": str(company.id),
        "period_id": str(period.id),
        "period_code": period.code,
        "can_close_period": len(blocking_items) == 0,
        "blocking_count": len(blocking_items),
        "warning_count": len(warning_items),
        "blocking_reconciliations": blocking_items,
        "warning_reconciliations": warning_items,
    }


# ==============================================================================
# UC-GL-01: Lập đề nghị quyết toán tạm ứng (Advance Settlement Request)
# ==============================================================================

def _generate_advance_request_number(company, requested_number=None):
    """
    Sinh Số đề nghị duy nhất trong phạm vi doanh nghiệp (BR-GL-ADV-13, EF-12).
    """
    if requested_number:
        clean_num = str(requested_number).strip()
        if clean_num and not models.AdvanceSettlementRequest.objects.filter(
            company=company, number=clean_num
        ).exists():
            return clean_num

    existing_numbers = list(
        models.AdvanceSettlementRequest.objects.filter(
            company=company, number__startswith="DNQT"
        ).values_list("number", flat=True)
    )
    max_seq = 0
    for num in existing_numbers:
        suffix = num[4:]
        if suffix.isdigit():
            max_seq = max(max_seq, int(suffix))
    next_seq = max_seq + 1
    candidate = f"DNQT{next_seq:04d}"
    while models.AdvanceSettlementRequest.objects.filter(company=company, number=candidate).exists():
        next_seq += 1
        candidate = f"DNQT{next_seq:04d}"
    return candidate


def _resolve_requester_and_department(company, data, request):
    """
    Xác thực Người đề nghị và Phòng ban/Đơn vị (AF-01, AF-02, EF-03, EF-04, EF-09, BR-GL-ADV-04..08, BR-GL-ADV-17).
    """
    from organization.models import Department, Employee
    from iam.permissions import has_effective_permission

    user_acc = actor(request)
    auth_user = getattr(request, "user", None)
    if auth_user and getattr(auth_user, "is_authenticated", False) and not getattr(auth_user, "is_active", True):
        raise ValidationError({"actor": "Tài khoản người dùng không còn hoạt động."})
    if user_acc and getattr(user_acc, "status", "ACTIVE") != "ACTIVE":
        raise ValidationError({"actor": "Tài khoản người dùng đã bị khóa hoặc ngừng hoạt động."})

    raw_requester = (
        data.get("requester")
        or data.get("requester_id")
        or data.get("employee_id")
        or data.get("employee")
    )

    # Tìm nhân viên gắn với user đang đăng nhập (AF-01)
    logged_in_employee = None
    if user_acc:
        q_filter = Q()
        if getattr(user_acc, "email", None):
            q_filter |= Q(email__iexact=user_acc.email)
        if getattr(user_acc, "username", None):
            q_filter |= Q(employee_code__iexact=user_acc.username)
        if q_filter:
            logged_in_employee = Employee.objects.filter(company=company).filter(q_filter).first()

    if not raw_requester and data.get("default_to_logged_in_employee"):
        if logged_in_employee:
            raw_requester = str(logged_in_employee.id)

    if not raw_requester:
        raise ValidationError({"requester": "Người đề nghị là bắt buộc."})

    requester_str = str(raw_requester).strip()
    if not requester_str:
        raise ValidationError({"requester": "Người đề nghị là bắt buộc."})

    emp = None
    try:
        emp = Employee.objects.select_related("department", "branch").filter(
            company=company, pk=requester_str
        ).first()
    except Exception:
        emp = None

    if not emp:
        emp = Employee.objects.select_related("department", "branch").filter(
            company=company
        ).filter(
            Q(employee_code__iexact=requester_str) | Q(full_name__iexact=requester_str)
        ).first()

    # Nếu truyền tên nhân viên từ giao diện và công ty chưa có hồ sơ đó nhưng không bật cờ strict_employee_lookup
    if not emp and data.get("auto_create_employee_if_missing"):
        dept_default = Department.objects.filter(company=company, status="ACTIVE").first()
        code_seq = Employee.objects.filter(company=company).count() + 1
        emp = Employee.objects.create(
            company=company,
            department=dept_default,
            employee_code=f"NV{code_seq:03d}",
            full_name=requester_str,
            status="ACTIVE",
        )

    if not emp or emp.company_id != company.id or emp.status != "ACTIVE":
        raise ValidationError({"requester": "Người đề nghị không tồn tại hoặc đã ngừng hoạt động."})

    # Kiểm tra quyền lập đề nghị thay cho nhân viên khác (AF-02, BR-GL-ADV-07, BR-GL-ADV-17)
    is_for_other = bool(
        (logged_in_employee and emp.id != logged_in_employee.id)
        or data.get("is_for_other_employee")
    )
    if is_for_other:
        if data.get("forbid_create_for_others"):
            raise ValidationError({"requester": "Bạn không có quyền lập đề nghị quyết toán thay cho nhân viên khác."})
        if (
            auth_user
            and getattr(auth_user, "is_authenticated", False)
            and not getattr(auth_user, "is_superuser", False)
            and user_acc
        ):
            if not has_effective_permission(user_acc, company, "GL.ADVANCE_REQUEST.CREATE_FOR_OTHERS"):
                raise ValidationError({"requester": "Bạn không có quyền lập đề nghị quyết toán thay cho nhân viên khác."})

    # Xác định Phòng ban/Đơn vị (Step 6, EF-09, BR-GL-ADV-08)
    raw_dept = data.get("department") or data.get("department_id")
    dept = None
    if raw_dept:
        dept_str = str(raw_dept).strip()
        try:
            dept = Department.objects.filter(company=company, pk=dept_str).first()
        except Exception:
            dept = None
        if not dept:
            dept = Department.objects.filter(company=company).filter(
                Q(code__iexact=dept_str) | Q(name__iexact=dept_str)
            ).first()
        if not dept or dept.status != "ACTIVE":
            raise ValidationError({"department": "Phòng ban/Đơn vị không tồn tại hoặc đã ngừng hoạt động."})
    else:
        dept = emp.department
        if dept and dept.status != "ACTIVE":
            raise ValidationError({"department": "Phòng ban/Đơn vị của người đề nghị đã ngừng hoạt động."})

    require_department = bool(data.get("require_department", False))
    if require_department and not dept:
        raise ValidationError({"department": "Người đề nghị chưa được khai báo Phòng ban/Đơn vị hợp lệ."})

    return emp, dept


def _validate_advance_amount_and_purpose(data):
    """
    Kiểm tra Số tiền đề nghị quyết toán (> 0) và Mục đích/Diễn giải (EF-05..EF-08, BR-GL-ADV-09..12).
    """
    from decimal import InvalidOperation

    raw_amount = data.get("amount")
    if raw_amount is None or str(raw_amount).strip() == "":
        raise ValidationError({"amount": "Số tiền đề nghị quyết toán là bắt buộc."})

    try:
        amount = Decimal(str(raw_amount).strip())
        if not amount.is_finite():
            raise InvalidOperation()
    except (InvalidOperation, ValueError, TypeError):
        raise ValidationError({"amount": "Số tiền đề nghị quyết toán không hợp lệ."})

    if amount <= Decimal("0"):
        raise ValidationError({"amount": "Số tiền đề nghị quyết toán phải lớn hơn 0."})

    raw_purpose = data.get("purpose") if "purpose" in data else data.get("description", "")
    purpose = str(raw_purpose or "").strip()
    if not purpose:
        raise ValidationError({"purpose": "Mục đích/Diễn giải là bắt buộc và không được chỉ chứa khoảng trắng."})

    return amount, purpose


def _validate_and_build_workflow_snapshot(company, data, user_acc):
    """
    Kiểm tra cấu hình Workflow và người phê duyệt trước khi chuyển sang PENDING_APPROVAL (EF-10, EF-13, BR-GL-ADV-18..20).
    """
    from iam.models import UserAccount

    wf_input = data.get("workflow_snapshot") or data.get("workflow") or {}
    if not isinstance(wf_input, dict):
        wf_input = {}

    if wf_input.get("workflow_configured") is False or wf_input.get("approver_missing") is True:
        raise ValidationError({"workflow": "Chưa cấu hình quy trình hoặc người phê duyệt cho đề nghị quyết toán tạm ứng."})

    try:
        levels = max(1, min(int(wf_input.get("levels", 1)), 10))
    except (TypeError, ValueError):
        raise ValidationError({"workflow": "Số cấp phê duyệt trong quy trình không hợp lệ."})

    approver_id = wf_input.get("approver_id")
    approver_name = wf_input.get("approver_name", "Kế toán trưởng / Trưởng bộ phận")
    if approver_id:
        approver_acc = UserAccount.objects.filter(pk=approver_id).first()
        if not approver_acc or getattr(approver_acc, "status", "ACTIVE") != "ACTIVE":
            raise ValidationError({"workflow": "Người phê duyệt trong quy trình không tồn tại hoặc đã ngừng hoạt động."})
        approver_name = (
            getattr(approver_acc, "full_name", "")
            or getattr(getattr(approver_acc, "auth_user", None), "username", "")
            or approver_name
        )

    sync_mode = str(wf_input.get("sync_mode") or data.get("sync_mode") or "IMMEDIATE").upper()
    if sync_mode not in ("IMMEDIATE", "SCHEDULED", "MANUAL"):
        sync_mode = "IMMEDIATE"

    return {
        "version": str(wf_input.get("version", "WF-GL-ADV-01")),
        "levels": levels,
        "allow_self_approval": bool(wf_input.get("allow_self_approval", True)),
        "approver_id": str(approver_id) if approver_id else None,
        "approver_name": approver_name,
        "sync_mode": sync_mode,
        "simulate_sync_error": bool(wf_input.get("simulate_sync_error", False)),
        "decisions": [],
    }


@transaction.atomic
def create_advance_settlement_request(company, data, request):
    """
    Main Flow Steps 1-20: Tạo và gửi phê duyệt Đề nghị quyết toán tạm ứng.
    Đảm bảo tính nguyên tử (BR-GL-ADV-41), chống gửi trùng (EF-11, BR-GL-ADV-14, BR-GL-ADV-42),
    và tuyệt đối không sinh bút toán Nợ/Có hay thay đổi số dư GL (BR-GL-ADV-29..32).
    """
    from organization.models import Company

    # Khóa dòng company để đảm bảo sinh số đề nghị tuần tự và chống race condition (EF-11, EF-12)
    company = Company.objects.select_for_update().get(pk=company.pk)

    idempotency_key = str(data.get("idempotency_key") or "").strip()
    if idempotency_key:
        existing = models.AdvanceSettlementRequest.objects.filter(
            company=company, idempotency_key=idempotency_key
        ).first()
        if existing:
            return existing, False

    emp, dept = _resolve_requester_and_department(company, data, request)
    amount, purpose = _validate_advance_amount_and_purpose(data)
    user_acc = actor(request)
    workflow_snapshot = _validate_and_build_workflow_snapshot(company, data, user_acc)

    raw_date = data.get("request_date")
    if raw_date:
        req_date = raw_date if isinstance(raw_date, date) else date.fromisoformat(str(raw_date))
    else:
        req_date = timezone.localdate()

    number = _generate_advance_request_number(company, data.get("number"))
    now = timezone.now()

    workflow_snapshot["decisions"].append({
        "level": 0,
        "action": "SUBMITTED",
        "actor_id": str(user_acc.id) if user_acc else None,
        "actor_name": (
            getattr(user_acc, "full_name", "")
            or getattr(getattr(user_acc, "auth_user", None), "username", "")
            if user_acc
            else ""
        ) or "Người lập",
        "timestamp": now.isoformat(),
        "comment": "Khởi tạo và gửi phê duyệt đề nghị quyết toán tạm ứng",
    })

    obj = models.AdvanceSettlementRequest.objects.create(
        company=company,
        branch=emp.branch or (dept.branch if dept else None),
        number=number,
        request_date=req_date,
        requester=emp,
        department=dept,
        amount=amount,
        purpose=purpose,
        status=models.AdvanceRequestStatus.PENDING_APPROVAL,
        sync_status=models.AdvanceRequestSyncStatus.NOT_SYNCED,
        idempotency_key=idempotency_key,
        workflow_snapshot=workflow_snapshot,
        current_approval_level=1,
        created_by=user_acc,
        submitted_at=now,
        version=1,
    )

    audit(
        request,
        obj,
        "SUBMIT_ADVANCE_REQUEST",
        before={},
        after={
            "number": obj.number,
            "requester": emp.full_name,
            "department": dept.name if dept else "",
            "amount": str(obj.amount),
            "status": obj.status,
        },
        reason=purpose,
    )
    return obj, True


@transaction.atomic
def update_or_resubmit_advance_request(req_obj, data, request):
    """
    AF-05, BR-GL-ADV-24, BR-GL-ADV-38..40:
    Chặn sửa đề nghị đang Chờ duyệt / Đã duyệt. Cho phép cập nhật và gửi duyệt lại khi ở trạng thái RETURNED / DRAFT.
    """
    req_obj = models.AdvanceSettlementRequest.objects.select_for_update().get(pk=req_obj.pk)

    if "version" in data and data.get("version") is not None:
        try:
            if int(data["version"]) != req_obj.version:
                raise ValidationError({"version": "Dữ liệu đề nghị đã thay đổi, vui lòng tải lại trước khi thao tác."})
        except (ValueError, TypeError):
            pass

    if req_obj.settlement_entry_id or req_obj.settlement_voucher_no:
        raise ValidationError({"status": "Đề nghị đã được kế thừa lập chứng từ quyết toán, không được phép chỉnh sửa."})

    if req_obj.status in (models.AdvanceRequestStatus.APPROVED, models.AdvanceRequestStatus.PENDING_APPROVAL):
        raise ValidationError({"status": "Không được phép chỉnh sửa trực tiếp đề nghị đang chờ duyệt hoặc đã được phê duyệt."})

    if req_obj.status not in (
        models.AdvanceRequestStatus.RETURNED,
        models.AdvanceRequestStatus.DRAFT,
        models.AdvanceRequestStatus.REJECTED,
    ):
        raise ValidationError({"status": "Trạng thái đề nghị hiện tại không cho phép chỉnh sửa hoặc gửi lại."})

    before_snapshot = {
        "requester": str(req_obj.requester_id),
        "department": str(req_obj.department_id) if req_obj.department_id else None,
        "amount": str(req_obj.amount),
        "purpose": req_obj.purpose,
        "status": req_obj.status,
    }

    merged_data = {
        "requester": data.get("requester", req_obj.requester_id),
        "department": data.get("department", req_obj.department_id),
        "amount": data.get("amount", req_obj.amount),
        "purpose": data.get("purpose", req_obj.purpose),
    }
    emp, dept = _resolve_requester_and_department(req_obj.company, merged_data, request)
    amount, purpose = _validate_advance_amount_and_purpose(merged_data)
    user_acc = actor(request)

    old_status = req_obj.status
    req_obj.requester = emp
    req_obj.department = dept
    req_obj.amount = amount
    req_obj.purpose = purpose
    req_obj.status = models.AdvanceRequestStatus.PENDING_APPROVAL
    req_obj.current_approval_level = 1
    req_obj.rejection_reason = ""
    req_obj.submitted_at = timezone.now()
    req_obj.version += 1

    wf = dict(req_obj.workflow_snapshot or {})
    decisions = list(wf.get("decisions") or [])
    decisions.append({
        "level": 0,
        "action": "RESUBMITTED",
        "actor_id": str(user_acc.id) if user_acc else None,
        "actor_name": (
            getattr(user_acc, "full_name", "")
            or getattr(getattr(user_acc, "auth_user", None), "username", "")
            if user_acc
            else ""
        ) or "Người lập",
        "timestamp": timezone.now().isoformat(),
        "comment": data.get("comment") or "Bổ sung thông tin và gửi phê duyệt lại",
    })
    wf["decisions"] = decisions
    req_obj.workflow_snapshot = wf
    req_obj.save()

    audit(
        request,
        req_obj,
        "RESUBMIT_ADVANCE_REQUEST",
        before=before_snapshot,
        after={
            "requester": str(req_obj.requester_id),
            "department": str(req_obj.department_id) if req_obj.department_id else None,
            "amount": str(req_obj.amount),
            "purpose": req_obj.purpose,
            "status": req_obj.status,
        },
        reason=f"Gửi duyệt lại từ trạng thái {old_status}",
    )
    return req_obj


@transaction.atomic
def decide_advance_settlement_request(req_obj, request, decision):
    """
    Main Flow Steps 21-32, AF-04..AF-09, EF-14..EF-17, BR-GL-ADV-21..37, BR-GL-ADV-43:
    Xử lý phê duyệt (APPROVE), yêu cầu bổ sung (RETURN) hoặc từ chối (REJECT).
    """
    req_obj = models.AdvanceSettlementRequest.objects.select_for_update().get(pk=req_obj.pk)
    data = request.data if hasattr(request, "data") else {}

    # Kiểm tra đồng thời / Optimistic Concurrency (EF-16, BR-GL-ADV-26, BR-GL-ADV-43)
    if "version" in data and data.get("version") is not None:
        try:
            if int(data["version"]) != req_obj.version:
                raise ValidationError({"version": "Đề nghị đã được người khác cập nhật hoặc xử lý, vui lòng tải lại."})
        except (ValueError, TypeError):
            pass

    if req_obj.status != models.AdvanceRequestStatus.PENDING_APPROVAL:
        raise ValidationError({"status": "Chỉ đề nghị đang ở trạng thái Chờ duyệt mới được phép phê duyệt hoặc từ chối."})

    user_acc = actor(request)
    auth_user = getattr(request, "user", None)
    wf = dict(req_obj.workflow_snapshot or {})

    # Kiểm tra chính sách tự phê duyệt (EF-15, BR-GL-ADV-23)
    if (
        user_acc
        and req_obj.created_by_id == user_acc.id
        and wf.get("allow_self_approval") is False
    ):
        raise ValidationError({"approver": "Người tạo đề nghị không được phép tự phê duyệt theo quy định kiểm soát nội bộ."})

    # Kiểm tra đúng người phê duyệt của cấp hiện tại nếu workflow chỉ định rõ approver_id (EF-14, BR-GL-ADV-21, BR-GL-ADV-22)
    designated_approver = wf.get("approver_id")
    if (
        designated_approver
        and user_acc
        and str(user_acc.id) != str(designated_approver)
        and not getattr(auth_user, "is_superuser", False)
    ):
        raise ValidationError({"approver": "Bạn không thuộc danh sách người có thẩm quyền phê duyệt ở cấp hiện tại."})

    comment = str(data.get("comment") or data.get("reason") or "").strip()
    old_status = req_obj.status
    now = timezone.now()
    decisions = list(wf.get("decisions") or [])

    actor_display = (
        (
            getattr(user_acc, "full_name", "")
            or getattr(getattr(user_acc, "auth_user", None), "username", "")
        )
        if user_acc
        else ""
    ) or "Người duyệt"

    if decision == "REJECT":
        if not comment:
            raise ValidationError({"comment": "Vui lòng nhập lý do từ chối đề nghị quyết toán tạm ứng."})
        req_obj.status = models.AdvanceRequestStatus.REJECTED
        req_obj.rejection_reason = comment
        req_obj.version += 1
        decisions.append({
            "level": req_obj.current_approval_level,
            "action": "REJECTED",
            "actor_id": str(user_acc.id) if user_acc else None,
            "actor_name": actor_display,
            "timestamp": now.isoformat(),
            "comment": comment,
        })
        wf["decisions"] = decisions
        req_obj.workflow_snapshot = wf
        req_obj.save()
        audit(request, req_obj, "REJECT_ADVANCE_REQUEST", {"status": old_status}, {"status": req_obj.status}, comment)
        return req_obj

    if decision == "RETURN":
        if not comment:
            raise ValidationError({"comment": "Vui lòng nhập nội dung yêu cầu bổ sung hoặc làm rõ."})
        req_obj.status = models.AdvanceRequestStatus.RETURNED
        req_obj.rejection_reason = comment
        req_obj.version += 1
        decisions.append({
            "level": req_obj.current_approval_level,
            "action": "RETURNED",
            "actor_id": str(user_acc.id) if user_acc else None,
            "actor_name": actor_display,
            "timestamp": now.isoformat(),
            "comment": comment,
        })
        wf["decisions"] = decisions
        req_obj.workflow_snapshot = wf
        req_obj.save()
        audit(request, req_obj, "RETURN_ADVANCE_REQUEST", {"status": old_status}, {"status": req_obj.status}, comment)
        return req_obj

    # decision == "APPROVE"
    total_levels = max(1, int(wf.get("levels", 1)))
    approved_level = req_obj.current_approval_level
    decisions.append({
        "level": approved_level,
        "action": "APPROVED",
        "actor_id": str(user_acc.id) if user_acc else None,
        "actor_name": actor_display,
        "timestamp": now.isoformat(),
        "comment": comment or f"Phê duyệt cấp {approved_level}",
    })
    wf["decisions"] = decisions
    req_obj.workflow_snapshot = wf

    if approved_level < total_levels:
        # AF-04: Còn cấp phê duyệt tiếp theo -> giữ PENDING_APPROVAL
        req_obj.current_approval_level = approved_level + 1
        req_obj.status = models.AdvanceRequestStatus.PENDING_APPROVAL
        req_obj.version += 1
        req_obj.save()
        audit(
            request,
            req_obj,
            "APPROVE_ADVANCE_REQUEST_STEP",
            {"status": old_status, "level": approved_level},
            {"status": req_obj.status, "level": req_obj.current_approval_level},
            comment,
        )
        return req_obj

    # Đã hoàn tất cấp phê duyệt cuối cùng -> chuyển sang APPROVED (Steps 24-30)
    req_obj.status = models.AdvanceRequestStatus.APPROVED
    req_obj.approved_by = user_acc
    req_obj.approved_at = now
    req_obj.rejection_reason = ""
    req_obj.version += 1

    # Xử lý đồng bộ sang danh sách chờ lập chứng từ quyết toán UC-GL-02 (AF-07..09, EF-17, BR-GL-ADV-33..37)
    simulate_sync_error = bool(data.get("simulate_sync_error") or wf.get("simulate_sync_error"))
    sync_mode = str(data.get("sync_mode") or wf.get("sync_mode") or "IMMEDIATE").upper()

    if simulate_sync_error:
        req_obj.sync_status = models.AdvanceRequestSyncStatus.SYNC_ERROR
        req_obj.sync_error_message = (
            "Đồng bộ sang phân hệ lập chứng từ quyết toán tạm thời thất bại. "
            "Đề nghị vẫn giữ trạng thái Đã duyệt, có thể thực hiện Đồng bộ lại."
        )
    elif sync_mode == "IMMEDIATE":
        req_obj.sync_status = models.AdvanceRequestSyncStatus.SYNCED
        req_obj.synced_at = now
        req_obj.sync_error_message = ""
    elif sync_mode == "SCHEDULED":
        req_obj.sync_status = models.AdvanceRequestSyncStatus.SYNC_PENDING
        req_obj.sync_error_message = ""
    else:
        req_obj.sync_status = models.AdvanceRequestSyncStatus.NOT_SYNCED
        req_obj.sync_error_message = ""

    req_obj.save()
    audit(
        request,
        req_obj,
        "APPROVE_ADVANCE_REQUEST",
        {"status": old_status},
        {"status": req_obj.status, "sync_status": req_obj.sync_status},
        comment,
    )
    return req_obj


@transaction.atomic
def retry_sync_advance_settlement_request(req_obj, request):
    """
    EF-17, EF-18, BR-GL-ADV-34..37:
    Thử đồng bộ lại đề nghị đã duyệt sang danh sách chờ lập chứng từ quyết toán mà không tạo bản ghi trùng.
    """
    req_obj = models.AdvanceSettlementRequest.objects.select_for_update().get(pk=req_obj.pk)
    if req_obj.status != models.AdvanceRequestStatus.APPROVED:
        raise ValidationError({"status": "Chỉ đề nghị ở trạng thái Đã duyệt mới được đồng bộ sang chức năng quyết toán."})

    # Idempotent: nếu đã SYNCED thì giữ nguyên, không tạo trùng (EF-18, BR-GL-ADV-35)
    if req_obj.sync_status == models.AdvanceRequestSyncStatus.SYNCED:
        return req_obj

    old_sync = req_obj.sync_status
    req_obj.sync_status = models.AdvanceRequestSyncStatus.SYNCED
    req_obj.synced_at = timezone.now()
    req_obj.sync_error_message = ""
    req_obj.version += 1
    req_obj.save(update_fields=("sync_status", "synced_at", "sync_error_message", "version", "updated_at"))
    audit(
        request,
        req_obj,
        "SYNC_ADVANCE_REQUEST",
        {"sync_status": old_sync},
        {"sync_status": req_obj.sync_status},
    )
    return req_obj


@transaction.atomic
def inherit_advance_request_for_settlement(req_obj, request):
    """
    AF-10, AF-11, EF-19, BR-GL-ADV-28, BR-GL-ADV-33, BR-GL-ADV-40:
    Kế toán tiếp nhận đề nghị đã duyệt để lập chứng từ quyết toán tạm ứng (UC-GL-02).
    """
    req_obj = models.AdvanceSettlementRequest.objects.select_for_update().get(pk=req_obj.pk)
    if req_obj.status != models.AdvanceRequestStatus.APPROVED:
        raise ValidationError({
            "status": "Đề nghị quyết toán tạm ứng chưa được phê duyệt hoàn tất hoặc đã bị từ chối, không thể lập chứng từ quyết toán."
        })

    if req_obj.settlement_entry_id or req_obj.settlement_voucher_no:
        raise ValidationError({
            "settlement_voucher_no": f"Đề nghị {req_obj.number} đã được kế thừa tại chứng từ {req_obj.settlement_voucher_no or req_obj.settlement_entry_id}."
        })

    data = request.data if hasattr(request, "data") else {}
    voucher_no = str(data.get("settlement_voucher_no") or "").strip()
    entry_id = data.get("settlement_entry") or data.get("settlement_entry_id")

    entry_obj = None
    if entry_id:
        entry_obj = models.JournalEntry.objects.filter(company=req_obj.company, pk=entry_id).first()
        if entry_obj and not voucher_no:
            voucher_no = entry_obj.number

    if not voucher_no:
        voucher_no = f"QTTU-{req_obj.number}"

    req_obj.settlement_entry = entry_obj
    req_obj.settlement_voucher_no = voucher_no
    req_obj.sync_status = models.AdvanceRequestSyncStatus.SYNCED
    if not req_obj.synced_at:
        req_obj.synced_at = timezone.now()
    req_obj.version += 1
    req_obj.save(
        update_fields=(
            "settlement_entry",
            "settlement_voucher_no",
            "sync_status",
            "synced_at",
            "version",
            "updated_at",
        )
    )
    audit(
        request,
        req_obj,
        "INHERIT_ADVANCE_REQUEST_TO_SETTLEMENT",
        {},
        {"settlement_voucher_no": voucher_no, "settlement_entry": str(entry_obj.id) if entry_obj else None},
    )
    return req_obj


# ==============================================================================
# UC-GL-02: Lập chứng từ quyết toán tạm ứng (Advance Settlement Voucher)
# ==============================================================================

MAX_ATTACHMENT_SIZE_BYTES = 5 * 1024 * 1024  # 5 MB (EF-20, BR-GL-QTTU-41)


def _parse_settlement_date(raw_val, field_name, label):
    """Parse ISO YYYY-MM-DD or DD/MM/YYYY date (EF-05, EF-06, BR-GL-QTTU-14..16)."""
    if isinstance(raw_val, date):
        return raw_val
    val_str = str(raw_val or "").strip()
    if not val_str:
        raise ValidationError({field_name: f"{label} là bắt buộc."})
    try:
        if "/" in val_str:
            parts = val_str.split("/")
            if len(parts) == 3:
                return date(int(parts[2]), int(parts[1]), int(parts[0]))
        return date.fromisoformat(val_str[:10])
    except (ValueError, TypeError):
        raise ValidationError({field_name: f"{label} ({val_str}) không đúng định dạng ngày hợp lệ."})


def _parse_settlement_decimal(raw_val, field_name, label, allow_zero=False):
    from decimal import InvalidOperation

    if raw_val is None or str(raw_val).strip() == "":
        if allow_zero:
            return Decimal("0")
        raise ValidationError({field_name: f"{label} là bắt buộc."})
    cleaned = str(raw_val).strip().replace(",", "")
    try:
        dec = Decimal(cleaned)
        if not dec.is_finite():
            raise InvalidOperation()
    except (InvalidOperation, ValueError, TypeError):
        raise ValidationError({field_name: f"{label} không phải là số hợp lệ."})
    if allow_zero and dec < Decimal("0"):
        raise ValidationError({field_name: f"{label} không được nhỏ hơn 0."})
    if not allow_zero and dec <= Decimal("0"):
        raise ValidationError({field_name: f"{label} phải lớn hơn 0."})
    return dec


def next_advance_settlement_voucher_number(company, custom_number=None, exclude_voucher_id=None, exclude_entry_id=None):
    """
    Sinh Số chứng từ quyết toán tạm ứng duy nhất theo định dạng QTTU00001 (Step 2, EF-08, EF-09, EF-27, BR-GL-QTTU-18..20).
    """
    import re

    if custom_number is not None:
        cleaned = str(custom_number).strip()
        if cleaned:
            v_qs = models.AdvanceSettlementVoucher.objects.filter(company=company, number__iexact=cleaned)
            if exclude_voucher_id:
                v_qs = v_qs.exclude(pk=exclude_voucher_id)
            e_qs = models.JournalEntry.objects.filter(company=company, number__iexact=cleaned)
            if exclude_entry_id:
                e_qs = e_qs.exclude(pk=exclude_entry_id)
            if v_qs.exists() or e_qs.exists():
                raise ValidationError({"number": f"Số chứng từ quyết toán tạm ứng '{cleaned}' đã tồn tại trong doanh nghiệp."})
            return cleaned

    existing_v_nums = list(
        models.AdvanceSettlementVoucher.objects.filter(company=company, number__istartswith="QTTU")
        .values_list("number", flat=True)
    )
    existing_e_nums = list(
        models.JournalEntry.objects.filter(company=company, number__istartswith="QTTU")
        .values_list("number", flat=True)
    )
    max_seq = 0
    for item in existing_v_nums + existing_e_nums:
        m = re.search(r"(\d+)$", str(item).strip())
        if m:
            try:
                max_seq = max(max_seq, int(m.group(1)))
            except ValueError:
                pass

    seq = max_seq + 1
    while True:
        candidate = f"QTTU{seq:05d}"
        if (
            not models.AdvanceSettlementVoucher.objects.filter(company=company, number__iexact=candidate).exists()
            and not models.JournalEntry.objects.filter(company=company, number__iexact=candidate).exists()
        ):
            return candidate
        seq += 1


def _resolve_settlement_employee_and_dept(company, data):
    """
    Kiểm tra Nhân viên được quyết toán tạm ứng và Phòng ban (Steps 9-12, EF-03, EF-04, BR-GL-QTTU-02..04).
    """
    from organization.models import Department, Employee

    raw_emp = data.get("employee") or data.get("employee_id") or data.get("employee_code")
    if not raw_emp or not str(raw_emp).strip():
        raise ValidationError({"employee": "Nhân viên quyết toán tạm ứng là bắt buộc."})

    emp_str = str(raw_emp).strip()
    emp = None
    try:
        emp = Employee.objects.select_related("department", "branch").filter(company=company, pk=emp_str).first()
    except Exception:
        emp = None

    if not emp:
        emp = (
            Employee.objects.select_related("department", "branch")
            .filter(company=company)
            .filter(Q(employee_code__iexact=emp_str) | Q(full_name__iexact=emp_str))
            .first()
        )
    if not emp and " - " in emp_str:
        prefix = emp_str.split(" - ", 1)[0].strip()
        suffix = emp_str.split(" - ", 1)[1].strip()
        emp = (
            Employee.objects.select_related("department", "branch")
            .filter(company=company)
            .filter(Q(employee_code__iexact=prefix) | Q(full_name__iexact=suffix) | Q(full_name__iexact=prefix))
            .first()
        )

    if not emp and data.get("auto_create_employee_if_missing"):
        dept_default = Department.objects.filter(company=company, status="ACTIVE").first()
        code_seq = Employee.objects.filter(company=company).count() + 1
        emp = Employee.objects.create(
            company=company,
            department=dept_default,
            employee_code=f"NV{code_seq:03d}",
            full_name=emp_str,
            status="ACTIVE",
        )

    if not emp or emp.company_id != company.id:
        raise ValidationError({"employee": "Nhân viên được chọn không tồn tại hoặc không thuộc doanh nghiệp hiện tại."})

    allow_historical = bool(data.get("allow_historical_employee", False))
    if emp.status != "ACTIVE" and not allow_historical:
        raise ValidationError({"employee": f"Nhân viên '{emp.full_name}' đã ngừng hoạt động, không thể lập chứng từ quyết toán mới."})

    raw_dept = data.get("department") or data.get("department_id")
    dept = None
    if raw_dept:
        dept_str = str(raw_dept).strip()
        try:
            dept = Department.objects.filter(company=company, pk=dept_str).first()
        except Exception:
            dept = None
        if not dept:
            dept = (
                Department.objects.filter(company=company)
                .filter(Q(code__iexact=dept_str) | Q(name__iexact=dept_str))
                .first()
            )
        if not dept or dept.status != "ACTIVE":
            raise ValidationError({"department": "Phòng ban/Đơn vị không tồn tại hoặc đã ngừng hoạt động."})
    else:
        dept = emp.department

    return emp, dept


def _resolve_and_validate_settlement_period(company, data):
    """
    Kiểm tra Ngày hạch toán, Ngày chứng từ, Kỳ kế toán và Khóa sổ chứng từ (Steps 17-20, EF-05..EF-07, BR-GL-QTTU-14..17).
    """
    import calendar

    raw_posting = data.get("posting_date") or data.get("postingDate")
    raw_doc = data.get("document_date") or data.get("docDate") or raw_posting

    if "posting_date" in data and (raw_posting is None or str(raw_posting).strip() == ""):
        raise ValidationError({"posting_date": "Ngày hạch toán là bắt buộc."})
    if "document_date" in data and (raw_doc is None or str(raw_doc).strip() == ""):
        raise ValidationError({"document_date": "Ngày chứng từ là bắt buộc."})

    posting_date = _parse_settlement_date(raw_posting or timezone.localdate(), "posting_date", "Ngày hạch toán")
    document_date = _parse_settlement_date(raw_doc or posting_date, "document_date", "Ngày chứng từ")

    if document_date > posting_date and not bool(data.get("allow_future_document_date", False)):
        raise ValidationError({"document_date": "Ngày chứng từ không được lớn hơn Ngày hạch toán."})

    # Kiểm tra khóa sổ chứng từ (Document Lock)
    try:
        assert_not_locked(company, "GL.JOURNAL_ENTRY", posting_date)
    except Exception as exc:
        msg = exc.detail if hasattr(exc, "detail") else str(exc)
        raise ValidationError({"posting_date": msg})

    period = models.AccountingPeriod.objects.filter(
        company=company,
        start_date__lte=posting_date,
        end_date__gte=posting_date,
    ).first()

    if not period:
        if bool(data.get("strict_period_exists", False)):
            raise ValidationError({"posting_date": f"Không tìm thấy kỳ kế toán mở cho ngày hạch toán {posting_date}."})
        last_day = calendar.monthrange(posting_date.year, posting_date.month)[1]
        p_code = f"{posting_date.year}-{posting_date.month:02d}"
        period, _ = models.AccountingPeriod.objects.get_or_create(
            company=company,
            fiscal_year=posting_date.year,
            period_number=posting_date.month,
            defaults={
                "code": p_code,
                "start_date": date(posting_date.year, posting_date.month, 1),
                "end_date": date(posting_date.year, posting_date.month, last_day),
                "status": "OPEN",
            },
        )

    if period.status != "OPEN":
        raise ValidationError({
            "posting_date": f"Kỳ kế toán {period.code} đã đóng/khóa sổ, không được phép lập hoặc sửa chứng từ quyết toán tạm ứng."
        })

    return posting_date, document_date, period


def _validate_settlement_attachments(raw_attachments):
    """
    Kiểm tra tệp đính kèm không vượt quá 5MB mỗi tệp (Steps 33-34, EF-20, BR-GL-QTTU-41, BR-GL-QTTU-42).
    """
    if not raw_attachments:
        return []
    if not isinstance(raw_attachments, list):
        raise ValidationError({"attachments": "Danh sách tệp đính kèm không hợp lệ."})

    validated = []
    for idx, item in enumerate(raw_attachments, start=1):
        if isinstance(item, str):
            validated.append({
                "file_name": item.strip(),
                "file_size": 0,
                "file_type": "",
            })
            continue
        if not isinstance(item, dict):
            raise ValidationError({"attachments": f"Tệp đính kèm thứ {idx} không đúng định dạng."})
        fname = str(item.get("file_name") or item.get("name") or f"file_{idx}").strip()
        raw_size = item.get("file_size", item.get("size", 0))
        size_bytes = 0
        if isinstance(raw_size, (int, float)):
            size_bytes = int(raw_size)
        elif isinstance(raw_size, str):
            s_lower = raw_size.strip().lower()
            try:
                if "mb" in s_lower:
                    size_bytes = int(float(s_lower.replace("mb", "").strip()) * 1024 * 1024)
                elif "kb" in s_lower:
                    size_bytes = int(float(s_lower.replace("kb", "").strip()) * 1024)
                else:
                    size_bytes = int(float(s_lower.replace("b", "").strip() or 0))
            except ValueError:
                size_bytes = 0

        if size_bytes < 0:
            raise ValidationError({"attachments": f"Dung lượng tệp '{fname}' không hợp lệ."})
        if size_bytes > MAX_ATTACHMENT_SIZE_BYTES:
            raise ValidationError({
                "attachments": f"Tệp đính kèm '{fname}' ({size_bytes / (1024 * 1024):.2f} MB) vượt quá giới hạn tối đa 5MB cho phép."
            })

        validated.append({
            "file_name": fname,
            "file_size": size_bytes,
            "file_type": str(item.get("file_type") or item.get("type") or ""),
            "file_url": str(item.get("file_url") or item.get("url") or ""),
        })
    return validated


def _resolve_account_for_settlement(company, raw_acc, field_label, line_idx, is_tax=False):
    """
    Xác thực Tài khoản hạch toán tồn tại, thuộc doanh nghiệp, đang ACTIVE và cho phép hạch toán chi tiết (EF-11, EF-12, BR-GL-QTTU-22, BR-GL-QTTU-23).
    """
    prefix_key = "tax_lines" if is_tax else "accounting_lines"
    if not raw_acc or not str(raw_acc).strip():
        raise ValidationError({prefix_key: f"Dòng {line_idx}: Vui lòng chọn {field_label}."})

    acc_str = str(raw_acc).strip()
    acc = None
    try:
        acc = models.Account.objects.filter(company=company, pk=acc_str).first()
    except Exception:
        acc = None

    if not acc:
        acc = models.Account.objects.filter(company=company, code__iexact=acc_str).first()

    if not acc:
        raise ValidationError({prefix_key: f"Dòng {line_idx}: {field_label} '{acc_str}' không tồn tại trong hệ thống tài khoản."})
    if acc.status != "ACTIVE":
        raise ValidationError({prefix_key: f"Dòng {line_idx}: {field_label} '{acc.code}' đã ngừng sử dụng."})
    if not acc.is_postable or acc.children.filter(status="ACTIVE").exists():
        raise ValidationError({
            prefix_key: f"Dòng {line_idx}: {field_label} '{acc.code}' là tài khoản tổng hợp hoặc không cho phép hạch toán trực tiếp."
        })
    return acc


def _validate_and_prepare_accounting_lines(company, emp, dept, posting_date, raw_lines, default_desc):
    """
    Kiểm tra các dòng hạch toán Tab 1 (Steps 21-26, EF-10..EF-16, BR-GL-QTTU-21..30).
    """
    from master_data.models import CostCenter, Party, Project, Warehouse
    from organization.models import Department

    if not isinstance(raw_lines, list) or len(raw_lines) == 0:
        raise ValidationError({"accounting_lines": "Chứng từ quyết toán tạm ứng phải có ít nhất một dòng hạch toán."})

    # Lọc các dòng trống hoàn toàn nếu có > 1 dòng, nhưng nếu tất cả đều trống thì báo lỗi rõ ràng
    meaningful_lines = []
    for r in raw_lines:
        if not isinstance(r, dict):
            continue
        has_data = any(
            str(r.get(k) or "").strip()
            for k in ("debit_account", "debitAcc", "debit_account_code", "amount")
        )
        if has_data or len(raw_lines) == 1:
            meaningful_lines.append(r)

    if not meaningful_lines:
        raise ValidationError({"accounting_lines": "Chứng từ quyết toán tạm ứng phải có ít nhất một dòng hạch toán hợp lệ."})

    prepared = []
    total_accounting = Decimal("0")
    total_141_credit = Decimal("0")

    for idx, row in enumerate(meaningful_lines, start=1):
        raw_debit = row.get("debit_account") or row.get("debit_account_code") or row.get("debitAcc")
        raw_credit = row.get("credit_account") or row.get("credit_account_code") or row.get("creditAcc")
        if raw_credit is None and "credit_account" not in row and "creditAcc" not in row:
            raw_credit = "141"

        debit_acc = _resolve_account_for_settlement(company, raw_debit, "Tài khoản Nợ", idx, is_tax=False)
        credit_acc = _resolve_account_for_settlement(company, raw_credit, "Tài khoản Có", idx, is_tax=False)

        if debit_acc.id == credit_acc.id:
            raise ValidationError({
                "accounting_lines": f"Dòng {idx}: Tài khoản Nợ và Tài khoản Có ({debit_acc.code}) không được trùng nhau."
            })

        amount = _parse_settlement_decimal(row.get("amount"), "accounting_lines", f"Số tiền hạch toán dòng {idx}", allow_zero=False)

        line_desc = str(row.get("description") or row.get("desc") or default_desc or "Quyết toán tạm ứng").strip()
        debit_obj_code = str(row.get("debit_object_code") or row.get("debitObject") or "").strip()
        debit_obj_name = str(row.get("debit_object_name") or row.get("debitObjectName") or "").strip()
        credit_obj_code = str(row.get("credit_object_code") or row.get("creditObject") or "").strip()
        credit_obj_name = str(row.get("credit_object_name") or row.get("creditObjectName") or "").strip()

        # Kiểm tra tính nhất quán giữa Nhân viên và tài khoản tạm ứng 141 (EF-15, BR-GL-QTTU-26)
        if credit_acc.code.startswith("141"):
            if credit_obj_code and credit_obj_code.lower() not in (
                emp.employee_code.lower(),
                emp.full_name.lower(),
                str(emp.id).lower(),
            ):
                raise ValidationError({
                    "accounting_lines": (
                        f"Dòng {idx}: Đối tượng Có '{credit_obj_code}' trên TK {credit_acc.code} "
                        f"không khớp với Nhân viên quyết toán '{emp.employee_code} - {emp.full_name}'."
                    )
                })
            credit_obj_code = emp.employee_code
            credit_obj_name = emp.full_name
            total_141_credit += amount

        if debit_acc.code.startswith("141"):
            if debit_obj_code and debit_obj_code.lower() not in (
                emp.employee_code.lower(),
                emp.full_name.lower(),
                str(emp.id).lower(),
            ):
                raise ValidationError({
                    "accounting_lines": (
                        f"Dòng {idx}: Đối tượng Nợ '{debit_obj_code}' trên TK {debit_acc.code} "
                        f"không khớp với Nhân viên quyết toán '{emp.employee_code} - {emp.full_name}'."
                    )
                })
            debit_obj_code = emp.employee_code
            debit_obj_name = emp.full_name

        # Giải quyết Party / Project / CostCenter / Warehouse / Department
        party_obj = None
        raw_party = row.get("party") or row.get("party_id") or debit_obj_code
        if raw_party:
            p_str = str(raw_party).strip()
            try:
                party_obj = Party.objects.filter(company=company, pk=p_str).first()
            except Exception:
                party_obj = None
            if not party_obj:
                party_obj = Party.objects.filter(company=company).filter(
                    Q(code__iexact=p_str) | Q(name__iexact=p_str)
                ).first()
            if party_obj and not debit_obj_name:
                debit_obj_code = party_obj.code
                debit_obj_name = party_obj.name

        line_dept = dept
        if row.get("department"):
            d_str = str(row["department"]).strip()
            try:
                line_dept = Department.objects.filter(company=company, pk=d_str).first() or line_dept
            except Exception:
                line_dept = Department.objects.filter(company=company).filter(
                    Q(code__iexact=d_str) | Q(name__iexact=d_str)
                ).first() or line_dept

        project_obj = None
        raw_proj = row.get("project") or row.get("job")
        if raw_proj:
            pr_str = str(raw_proj).strip()
            try:
                project_obj = Project.objects.filter(company=company, pk=pr_str).first()
            except Exception:
                project_obj = Project.objects.filter(company=company).filter(
                    Q(code__iexact=pr_str) | Q(name__iexact=pr_str)
                ).first()

        cc_obj = None
        raw_cc = row.get("cost_center")
        if raw_cc:
            cc_str = str(raw_cc).strip()
            try:
                cc_obj = CostCenter.objects.filter(company=company, pk=cc_str).first()
            except Exception:
                cc_obj = CostCenter.objects.filter(company=company).filter(
                    Q(code__iexact=cc_str) | Q(name__iexact=cc_str)
                ).first()

        wh_obj = None
        raw_wh = row.get("warehouse")
        if raw_wh:
            wh_str = str(raw_wh).strip()
            try:
                wh_obj = Warehouse.objects.filter(company=company, pk=wh_str).first()
            except Exception:
                wh_obj = Warehouse.objects.filter(company=company).filter(
                    Q(code__iexact=wh_str) | Q(name__iexact=wh_str)
                ).first()

        dims = dict(row.get("dimensions") or {})
        dims["employee_id"] = str(emp.id)
        dims["employee_code"] = emp.employee_code
        dims["employee_name"] = emp.full_name
        for extra_k in ("cost_item", "costItem", "stat_code", "statCode", "statistical_code", "contract", "order"):
            if row.get(extra_k):
                dims[extra_k] = str(row.get(extra_k)).strip()
        if dims.get("statCode") and not dims.get("statistical_code"):
            dims["statistical_code"] = dims["statCode"]

        # Kiểm tra chiều bắt buộc (Required Dimensions) trên TK Nợ và TK Có (EF-14, BR-GL-QTTU-27, BR-GL-QTTU-28)
        for acc_check, side_label in ((debit_acc, "Tài khoản Nợ"), (credit_acc, "Tài khoản Có")):
            dim_reqs = acc_check.dimension_requirements or {}
            for dim_name, req_level in dim_reqs.items():
                if req_level in ("REQUIRED", models.DimensionRequirementLevel.REQUIRED):
                    if dim_name in ("CUSTOMER", "SUPPLIER") and not (party_obj or debit_obj_code):
                        raise ValidationError({
                            "accounting_lines": f"Dòng {idx}: {side_label} {acc_check.code} bắt buộc nhập đối tượng ({dim_name})."
                        })
                    if dim_name == "PROJECT" and not (project_obj or dims.get("job")):
                        raise ValidationError({
                            "accounting_lines": f"Dòng {idx}: {side_label} {acc_check.code} bắt buộc nhập Dự án/Công trình."
                        })
                    if dim_name == "COST_CENTER" and not cc_obj:
                        raise ValidationError({
                            "accounting_lines": f"Dòng {idx}: {side_label} {acc_check.code} bắt buộc nhập Trung tâm chi phí."
                        })
                    if dim_name == "WAREHOUSE" and not wh_obj:
                        raise ValidationError({
                            "accounting_lines": f"Dòng {idx}: {side_label} {acc_check.code} bắt buộc nhập Kho."
                        })
                    if dim_name == "STATISTICAL_CODE" and not dims.get("statistical_code"):
                        raise ValidationError({
                            "accounting_lines": f"Dòng {idx}: {side_label} {acc_check.code} bắt buộc nhập Mã thống kê."
                        })
            if acc_check.requires_project and not project_obj:
                raise ValidationError({
                    "accounting_lines": f"Dòng {idx}: {side_label} {acc_check.code} bắt buộc chọn Dự án."
                })
            if acc_check.requires_cost_center and not cc_obj:
                raise ValidationError({
                    "accounting_lines": f"Dòng {idx}: {side_label} {acc_check.code} bắt buộc chọn Trung tâm chi phí."
                })
            if acc_check.requires_warehouse and not wh_obj:
                raise ValidationError({
                    "accounting_lines": f"Dòng {idx}: {side_label} {acc_check.code} bắt buộc chọn Kho."
                })

        total_accounting += amount
        prepared.append({
            "line_no": idx,
            "description": line_desc,
            "debit_account": debit_acc,
            "credit_account": credit_acc,
            "amount": amount,
            "debit_object_code": debit_obj_code,
            "debit_object_name": debit_obj_name,
            "credit_object_code": credit_obj_code,
            "credit_object_name": credit_obj_name,
            "party": party_obj,
            "department": line_dept,
            "project": project_obj,
            "cost_center": cc_obj,
            "warehouse": wh_obj,
            "dimensions": dims,
        })

    return prepared, total_accounting, total_141_credit


def _validate_and_prepare_tax_lines(
    company,
    emp,
    raw_tax_lines,
    exclude_voucher_id=None,
    allow_duplicate_invoice=False,
):
    """
    Kiểm tra các dòng kê khai hóa đơn và hạch toán thuế GTGT Tab 2 (Steps 27-32, AF-05..AF-07, EF-17..EF-19, BR-GL-QTTU-31..37).
    """
    from master_data.models import Party

    if not raw_tax_lines:
        return [], Decimal("0"), Decimal("0")
    if not isinstance(raw_tax_lines, list):
        raise ValidationError({"tax_lines": "Danh sách kê khai hóa đơn thuế không hợp lệ."})

    prepared = []
    total_tax = Decimal("0")
    total_141_tax_credit = Decimal("0")
    seen_invoices_in_payload = set()

    line_seq = 0
    for idx, row in enumerate(raw_tax_lines, start=1):
        if not isinstance(row, dict):
            continue
        inv_no = str(row.get("invoice_number") or row.get("invoiceNo") or "").strip()
        inv_serial = str(row.get("invoice_serial") or row.get("invoiceSerial") or "").strip()
        inv_form = str(row.get("invoice_form") or row.get("invoiceForm") or "").strip()
        raw_pre_tax = row.get("pre_tax_amount", row.get("preTaxAmount", 0))
        raw_vat_amt = row.get("vat_amount", row.get("vatAmount", 0))

        pre_tax_Check = _parse_settlement_decimal(raw_pre_tax, "tax_lines", f"Tiền chưa thuế dòng {idx}", allow_zero=True)
        vat_amt_check = _parse_settlement_decimal(raw_vat_amt, "tax_lines", f"Tiền thuế GTGT dòng {idx}", allow_zero=True)

        # Bỏ qua dòng mẫu trống hoàn toàn (AF-05: không kê khai hóa đơn)
        if pre_tax_Check == Decimal("0") and vat_amt_check == Decimal("0") and not inv_no:
            continue

        line_seq += 1
        raw_tax_acc = row.get("tax_account") or row.get("tax_account_code") or row.get("taxAcc") or "1331"
        raw_credit_acc = row.get("credit_account") or row.get("credit_account_code") or row.get("creditAcc") or "141"

        tax_acc = _resolve_account_for_settlement(company, raw_tax_acc, "TK thuế GTGT", idx, is_tax=True)
        credit_acc = _resolve_account_for_settlement(company, raw_credit_acc, "TK đối ứng thuế", idx, is_tax=True)

        if tax_acc.id == credit_acc.id:
            raise ValidationError({"tax_lines": f"Dòng thuế {idx}: TK thuế và TK đối ứng ({tax_acc.code}) không được trùng nhau."})

        # EF-17, BR-GL-QTTU-32: Bắt buộc Số hóa đơn và Ngày hóa đơn khi có kê khai thuế/hóa đơn
        if not inv_no:
            raise ValidationError({"tax_lines": f"Dòng thuế {idx}: Vui lòng nhập Số hóa đơn."})

        raw_inv_date = row.get("invoice_date") or row.get("invoiceDate")
        if not raw_inv_date or not str(raw_inv_date).strip():
            raise ValidationError({"tax_lines": f"Dòng thuế {idx}: Vui lòng nhập Ngày hóa đơn cho hóa đơn số {inv_no}."})
        inv_date = _parse_settlement_date(raw_inv_date, "tax_lines", f"Ngày hóa đơn dòng {idx}")

        vat_rate_str = str(row.get("vat_rate") if "vat_rate" in row else row.get("vatRate", "10")).strip().replace("%", "")
        goods_group = str(row.get("goods_group") or row.get("goodsGroup") or "1").strip()
        desc = str(row.get("description") or row.get("desc") or "Thuế GTGT đầu vào").strip()

        # Kiểm tra tính hợp lệ của Tiền thuế GTGT theo Tiền chưa thuế và Thuế suất (EF-18, BR-GL-QTTU-33, BR-GL-QTTU-34)
        if vat_rate_str.upper() in ("KCT", "KKKNT", "0"):
            expected_vat = Decimal("0")
        else:
            try:
                rate_num = Decimal(vat_rate_str)
                if rate_num < Decimal("0") or rate_num > Decimal("100"):
                    raise ValueError()
                expected_vat = (pre_tax_Check * rate_num / Decimal("100")).quantize(Decimal("0.0001"))
            except Exception:
                raise ValidationError({"tax_lines": f"Dòng thuế {idx}: Thuế suất '{vat_rate_str}' không hợp lệ."})

        # Nếu người dùng không truyền vat_amount (hoặc bằng 0 khi pre_tax > 0 và rate > 0 và không đánh dấu override),
        # nhưng nếu truyền sai lệch quá 10 đồng so với expected_vat thì cảnh báo/chặn theo EF-18
        if "vat_amount" not in row and "vatAmount" not in row:
            vat_amt_check = expected_vat
        else:
            tolerance = Decimal(str(row.get("vat_tolerance", "10")))
            if abs(vat_amt_check - expected_vat) > tolerance and not bool(row.get("allow_manual_vat_override", False)):
                raise ValidationError({
                    "tax_lines": (
                        f"Dòng thuế {idx}: Tiền thuế GTGT ({vat_amt_check:,.0f} đ) không khớp với "
                        f"Tiền chưa thuế ({pre_tax_Check:,.0f} đ) x Thuế suất {vat_rate_str}% ({expected_vat:,.0f} đ)."
                    )
                })

        supplier_obj = None
        sup_code = str(row.get("supplier_code") or row.get("partnerCode") or "").strip()
        sup_name = str(row.get("supplier_name") or row.get("partnerName") or "").strip()
        sup_tax = str(row.get("supplier_tax_code") or row.get("partnerTaxCode") or "").strip()
        raw_sup = row.get("supplier") or sup_code
        if raw_sup:
            s_str = str(raw_sup).strip()
            try:
                supplier_obj = Party.objects.filter(company=company, pk=s_str).first()
            except Exception:
                supplier_obj = None
            if not supplier_obj:
                supplier_obj = Party.objects.filter(company=company).filter(
                    Q(code__iexact=s_str) | Q(name__iexact=s_str) | Q(tax_code__iexact=s_str)
                ).first()
            if supplier_obj:
                sup_code = sup_code or supplier_obj.code
                sup_name = sup_name or supplier_obj.name
                sup_tax = sup_tax or (supplier_obj.tax_code or "")

        # Kiểm tra trùng hóa đơn đầu vào (EF-19, BR-GL-QTTU-35)
        inv_key = (
            inv_no.lower(),
            inv_serial.lower(),
            (sup_tax or sup_code).lower(),
        )
        if not allow_duplicate_invoice:
            if inv_key in seen_invoices_in_payload:
                raise ValidationError({
                    "tax_lines": f"Hóa đơn số '{inv_no}' (ký hiệu '{inv_serial or 'N/A'}') bị kê khai trùng lặp ngay trong cùng chứng từ."
                })
            seen_invoices_in_payload.add(inv_key)

            dup_qs = models.AdvanceSettlementTaxLine.objects.filter(
                voucher__company=company,
                invoice_number__iexact=inv_no,
            ).exclude(voucher__status=models.AdvanceSettlementVoucherStatus.CANCELLED)
            if exclude_voucher_id:
                dup_qs = dup_qs.exclude(voucher_id=exclude_voucher_id)
            if inv_serial:
                dup_qs = dup_qs.filter(invoice_serial__iexact=inv_serial)
            if sup_tax:
                dup_qs = dup_qs.filter(supplier_tax_code__iexact=sup_tax)
            elif sup_code:
                dup_qs = dup_qs.filter(supplier_code__iexact=sup_code)

            existing_dup = dup_qs.select_related("voucher").first()
            if existing_dup:
                raise ValidationError({
                    "tax_lines": (
                        f"Hóa đơn số '{inv_no}' (ký hiệu '{inv_serial or 'N/A'}') đã được kê khai tại chứng từ "
                        f"{existing_dup.voucher.number}."
                    )
                })

        total_tax += vat_amt_check
        if credit_acc.code.startswith("141"):
            total_141_tax_credit += vat_amt_check

        prepared.append({
            "line_no": line_seq,
            "description": desc,
            "tax_account": tax_acc,
            "credit_account": credit_acc,
            "goods_group": goods_group,
            "pre_tax_amount": pre_tax_Check,
            "vat_rate": vat_rate_str,
            "vat_amount": vat_amt_check,
            "invoice_date": inv_date,
            "invoice_number": inv_no,
            "invoice_form": inv_form,
            "invoice_serial": inv_serial,
            "supplier": supplier_obj,
            "supplier_code": sup_code,
            "supplier_name": sup_name,
            "supplier_tax_code": sup_tax,
        })

    return prepared, total_tax, total_141_tax_credit


def _validate_and_resolve_source_request(company, emp, data, accounting_amount, total_amount, exclude_voucher_id=None):
    """
    Kiểm tra liên kết Đề nghị quyết toán tạm ứng nguồn từ UC-GL-01 (AF-01, AF-02, EF-21, BR-GL-QTTU-09..13, BR-GL-QTTU-50, BR-GL-QTTU-51).
    """
    raw_req = data.get("advance_request") or data.get("advance_request_id") or data.get("advance_request_number")
    if not raw_req or not str(raw_req).strip():
        return None

    req_str = str(raw_req).strip()
    req_obj = None
    try:
        req_obj = models.AdvanceSettlementRequest.objects.select_for_update().filter(
            company=company, pk=req_str
        ).first()
    except Exception:
        req_obj = None

    if not req_obj:
        req_obj = models.AdvanceSettlementRequest.objects.select_for_update().filter(
            company=company, number__iexact=req_str
        ).first()

    if not req_obj:
        raise ValidationError({"advance_request": f"Đề nghị quyết toán tạm ứng '{req_str}' không tồn tại."})

    if req_obj.status != models.AdvanceRequestStatus.APPROVED:
        raise ValidationError({
            "advance_request": (
                f"Đề nghị quyết toán {req_obj.number} đang ở trạng thái '{req_obj.get_status_display()}', "
                "chưa đủ điều kiện lập chứng từ quyết toán (phải ở trạng thái Đã duyệt)."
            )
        })

    if req_obj.requester_id != emp.id and not bool(data.get("allow_different_requester", False)):
        raise ValidationError({
            "advance_request": (
                f"Nhân viên quyết toán ({emp.full_name}) không khớp với Người đề nghị "
                f"({req_obj.requester.full_name}) trên đề nghị {req_obj.number}."
            )
        })

    other_vouchers = models.AdvanceSettlementVoucher.objects.filter(
        company=company,
        advance_request=req_obj,
    ).exclude(status=models.AdvanceSettlementVoucherStatus.CANCELLED)
    if exclude_voucher_id:
        other_vouchers = other_vouchers.exclude(pk=exclude_voucher_id)

    already_settled = other_vouchers.aggregate(s=Sum("total_amount"))["s"] or Decimal("0")
    remaining_req = req_obj.amount - already_settled

    if remaining_req <= Decimal("0") and not bool(data.get("allow_exceed_request_amount", False)):
        raise ValidationError({
            "advance_request": f"Đề nghị quyết toán {req_obj.number} đã được lập chứng từ quyết toán hết ({req_obj.amount:,.0f} đ)."
        })

    # Cho phép quyết toán một phần (AF-02), nhưng không vượt quá số tiền còn lại của đề nghị trừ khi được cho phép rõ ràng
    if total_amount > remaining_req and not bool(data.get("allow_exceed_request_amount", False)):
        raise ValidationError({
            "advance_request": (
                f"Tổng tiền quyết toán ({total_amount:,.0f} đ) vượt quá số tiền còn được phép kế thừa "
                f"({remaining_req:,.0f} đ) của đề nghị {req_obj.number}."
            )
        })

    return req_obj


def _validate_and_resolve_source_advance(company, emp, data, total_141_settled, exclude_voucher_id=None):
    """
    Kiểm tra chế độ 'Quyết toán cho từng lần tạm ứng' và số dư còn lại của khoản/lần tạm ứng nguồn
    (AF-03, EF-22, EF-23, EF-24, BR-GL-QTTU-05..08).
    """
    from cash_management.models import CashAdvance

    settle_per_advance = bool(data.get("settle_per_advance") or data.get("settlePerAdvance") or False)
    raw_adv = data.get("cash_advance") or data.get("cash_advance_id") or data.get("source_advance_ref") or data.get("sourceAdvanceRef")
    adv_str = str(raw_adv or "").strip()

    if settle_per_advance and not adv_str:
        raise ValidationError({
            "source_advance_ref": "Khi chọn 'Quyết toán cho từng lần tạm ứng', bắt buộc phải chọn khoản/lần tạm ứng nguồn."
        })

    if not adv_str:
        return None, "", Decimal("0")

    cash_adv = None
    try:
        cash_adv = CashAdvance.objects.select_for_update().filter(company=company, pk=adv_str).first()
    except Exception:
        cash_adv = None

    if not cash_adv:
        cash_adv = CashAdvance.objects.select_for_update().filter(company=company, number__iexact=adv_str).first()

    if cash_adv:
        if cash_adv.recipient_id != emp.id:
            raise ValidationError({
                "cash_advance": (
                    f"Khoản tạm ứng {cash_adv.number} thuộc nhân viên khác, "
                    f"không khớp với nhân viên quyết toán {emp.full_name}."
                )
            })
        if cash_adv.status in ("CLOSED", "REJECTED", "DRAFT"):
            raise ValidationError({
                "cash_advance": f"Khoản tạm ứng {cash_adv.number} không ở trạng thái đang mở hoặc còn số dư cần quyết toán."
            })

        other_vouchers = models.AdvanceSettlementVoucher.objects.filter(
            company=company,
            cash_advance=cash_adv,
            status=models.AdvanceSettlementVoucherStatus.UNPOSTED,
        )
        if exclude_voucher_id:
            other_vouchers = other_vouchers.exclude(pk=exclude_voucher_id)
        pending_unposted = other_vouchers.aggregate(s=Sum("total_amount"))["s"] or Decimal("0")

        available_balance = Decimal(str(cash_adv.remaining_amount)) - pending_unposted
        if available_balance <= Decimal("0"):
            raise ValidationError({
                "cash_advance": f"Khoản tạm ứng {cash_adv.number} đã được quyết toán hết, không còn số dư khả dụng."
            })
        if settle_per_advance and total_141_settled > available_balance and not bool(data.get("allow_exceed_advance_balance", False)):
            raise ValidationError({
                "cash_advance": (
                    f"Số tiền quyết toán ({total_141_settled:,.0f} đ) vượt quá số dư còn lại "
                    f"({available_balance:,.0f} đ) của khoản tạm ứng {cash_adv.number}."
                )
            })
        return cash_adv, cash_adv.number, cash_adv.amount

    # Trường hợp tham chiếu theo mã chứng từ chi tạm ứng nguồn (source_advance_ref)
    raw_src_amt = data.get("source_advance_amount", data.get("sourceAdvanceAmount", 0))
    src_amount = _parse_settlement_decimal(raw_src_amt, "source_advance_amount", "Số tiền tạm ứng nguồn", allow_zero=True)

    if settle_per_advance and src_amount <= Decimal("0") and bool(data.get("require_source_advance_balance", False)):
        raise ValidationError({
            "source_advance_ref": f"Không xác định được số dư khả dụng của lần tạm ứng '{adv_str}'."
        })

    if src_amount > Decimal("0"):
        other_vouchers = models.AdvanceSettlementVoucher.objects.filter(
            company=company,
            source_advance_ref__iexact=adv_str,
        ).exclude(status=models.AdvanceSettlementVoucherStatus.CANCELLED)
        if exclude_voucher_id:
            other_vouchers = other_vouchers.exclude(pk=exclude_voucher_id)
        already_settled = other_vouchers.aggregate(s=Sum("total_amount"))["s"] or Decimal("0")
        remaining = src_amount - already_settled
        if remaining <= Decimal("0"):
            raise ValidationError({
                "source_advance_ref": f"Khoản tạm ứng '{adv_str}' đã được quyết toán hết."
            })
        if settle_per_advance and total_141_settled > remaining and not bool(data.get("allow_exceed_advance_balance", False)):
            raise ValidationError({
                "source_advance_ref": (
                    f"Số tiền quyết toán ({total_141_settled:,.0f} đ) vượt quá số dư còn lại "
                    f"({remaining:,.0f} đ) của lần tạm ứng '{adv_str}'."
                )
            })

    return None, adv_str, src_amount


def _sync_voucher_to_draft_journal_entry(voucher, prepared_acc_lines, prepared_tax_lines, user_acc):
    """
    Sinh hoặc cập nhật bút toán JournalEntry ở trạng thái DRAFT (Chưa ghi sổ - UNPOSTED).
    Đảm bảo:
    - Tổng Nợ == Tổng Có > 0 (EF-16, BR-GL-QTTU-30).
    - Nếu group_invoices = True (AF-07, BR-GL-QTTU-36, BR-GL-QTTU-37): gộp các dòng bút toán thuế GTGT
      có cùng cặp (tax_account, credit_account) thành 1 dòng hạch toán thuế trên JournalEntry.
    - Không thay đổi AccountBalance (BR-GL-QTTU-43, BR-GL-QTTU-44).
    """
    from master_data.models import Currency

    currency = (
        getattr(voucher.company, "accounting_currency", None)
        or Currency.objects.filter(code="VND").first()
        or Currency.objects.first()
    )

    journal_pairs = []
    for item in prepared_acc_lines:
        journal_pairs.append({
            "debit_account": item["debit_account"],
            "credit_account": item["credit_account"],
            "amount": item["amount"],
            "description": item["description"],
            "party": item["party"],
            "department": item["department"],
            "project": item["project"],
            "cost_center": item["cost_center"],
            "warehouse": item["warehouse"],
            "dimensions": item["dimensions"],
        })

    tax_with_vat = [t for t in prepared_tax_lines if t["vat_amount"] > Decimal("0")]
    if voucher.group_invoices and len(tax_with_vat) > 1:
        # AF-07: Gộp các dòng hạch toán thuế có cùng cặp TK thuế và TK đối ứng
        grouped_map = {}
        for t in tax_with_vat:
            key = (t["tax_account"].id, t["credit_account"].id)
            if key not in grouped_map:
                grouped_map[key] = {
                    "debit_account": t["tax_account"],
                    "credit_account": t["credit_account"],
                    "amount": Decimal("0"),
                    "invoices": [],
                    "supplier": t["supplier"],
                }
            grouped_map[key]["amount"] += t["vat_amount"]
            grouped_map[key]["invoices"].append(t["invoice_number"])

        for grp in grouped_map.values():
            inv_list_str = ", ".join(grp["invoices"])
            journal_pairs.append({
                "debit_account": grp["debit_account"],
                "credit_account": grp["credit_account"],
                "amount": grp["amount"],
                "description": f"Thuế GTGT đầu vào gộp HĐ ({inv_list_str})"[:500],
                "party": grp["supplier"],
                "department": voucher.department,
                "project": None,
                "cost_center": None,
                "warehouse": None,
                "dimensions": {
                    "employee_id": str(voucher.employee_id),
                    "employee_code": voucher.employee.employee_code,
                    "grouped_invoices": grp["invoices"],
                },
            })
    else:
        for t in tax_with_vat:
            journal_pairs.append({
                "debit_account": t["tax_account"],
                "credit_account": t["credit_account"],
                "amount": t["vat_amount"],
                "description": f"{t['description']} - HĐ {t['invoice_number']}"[:500],
                "party": t["supplier"],
                "department": voucher.department,
                "project": None,
                "cost_center": None,
                "warehouse": None,
                "dimensions": {
                    "employee_id": str(voucher.employee_id),
                    "employee_code": voucher.employee.employee_code,
                    "invoice_number": t["invoice_number"],
                    "invoice_serial": t["invoice_serial"],
                },
            })

    total_debit = sum((p["amount"] for p in journal_pairs), Decimal("0"))
    total_credit = sum((p["amount"] for p in journal_pairs), Decimal("0"))

    if total_debit <= Decimal("0") or total_debit != total_credit:
        raise ValidationError({"accounting_lines": "Tổng phát sinh Nợ và Tổng phát sinh Có của chứng từ không cân bằng."})

    entry = voucher.journal_entry if voucher.journal_entry_id else None
    if entry:
        entry.period = voucher.period
        entry.branch = voucher.branch
        entry.number = voucher.number
        entry.posting_date = voucher.posting_date
        entry.document_date = voucher.document_date
        entry.description = voucher.description
        entry.total_debit = total_debit
        entry.total_credit = total_credit
        entry.status = models.JournalStatus.DRAFT
        entry.save()
        entry.lines.all().delete()
    else:
        entry = models.JournalEntry.objects.create(
            company=voucher.company,
            branch=voucher.branch,
            period=voucher.period,
            number=voucher.number,
            entry_type="MANUAL",
            posting_date=voucher.posting_date,
            document_date=voucher.document_date,
            description=voucher.description,
            source_module="GL",
            source_entity_type="AdvanceSettlementVoucher",
            status=models.JournalStatus.DRAFT,
            total_debit=total_debit,
            total_credit=total_credit,
            created_by=user_acc,
            workflow_snapshot={
                "voucher_type": "ADVANCE_SETTLEMENT",
                "allow_self_approval": True,
                "allow_creator_posting": True,
                "levels": 1,
            },
        )

    line_no = 1
    for pair in journal_pairs:
        models.JournalLine.objects.create(
            entry=entry,
            line_no=line_no,
            account=pair["debit_account"],
            description=pair["description"],
            debit=pair["amount"],
            credit=Decimal("0"),
            currency=currency,
            foreign_amount=pair["amount"],
            exchange_rate=Decimal("1"),
            party=pair["party"],
            department=pair["department"],
            project=pair["project"],
            cost_center=pair["cost_center"],
            warehouse=pair["warehouse"],
            dimensions=pair["dimensions"],
        )
        line_no += 1
        models.JournalLine.objects.create(
            entry=entry,
            line_no=line_no,
            account=pair["credit_account"],
            description=pair["description"],
            debit=Decimal("0"),
            credit=pair["amount"],
            currency=currency,
            foreign_amount=pair["amount"],
            exchange_rate=Decimal("1"),
            party=pair["party"],
            department=pair["department"],
            project=pair["project"],
            cost_center=pair["cost_center"],
            warehouse=pair["warehouse"],
            dimensions=pair["dimensions"],
        )
        line_no += 1

    return entry


def _update_advance_request_settlement_link(req_obj):
    """
    Cập nhật thông tin truy vết trên Đề nghị quyết toán tạm ứng nguồn (UC-GL-01)
    khi có chứng từ quyết toán tạm ứng (UC-GL-02) liên kết tới (AF-01, AF-02, BR-GL-QTTU-50, BR-GL-QTTU-51).
    """
    if not req_obj:
        return
    active_vouchers = list(
        models.AdvanceSettlementVoucher.objects.filter(
            company=req_obj.company,
            advance_request=req_obj,
        )
        .exclude(status=models.AdvanceSettlementVoucherStatus.CANCELLED)
        .order_by("created_at")
    )
    if not active_vouchers:
        req_obj.settlement_entry = None
        req_obj.settlement_voucher_no = ""
    else:
        total_settled = sum((v.total_amount for v in active_vouchers), Decimal("0"))
        latest = active_vouchers[-1]
        voucher_numbers = ", ".join(v.number for v in active_vouchers)
        req_obj.settlement_voucher_no = voucher_numbers[:80]
        # Chỉ đánh dấu settlement_entry khi đã quyết toán đủ 100% số tiền đề nghị để AF-02 vẫn cho phép kế thừa phần còn lại
        if total_settled >= req_obj.amount:
            req_obj.settlement_entry = latest.journal_entry
        else:
            req_obj.settlement_entry = None
        req_obj.sync_status = models.AdvanceRequestSyncStatus.SYNCED
        if not req_obj.synced_at:
            req_obj.synced_at = timezone.now()
    req_obj.save(update_fields=("settlement_entry", "settlement_voucher_no", "sync_status", "synced_at", "updated_at"))


@transaction.atomic
def create_advance_settlement_voucher(company, data, request):
    """
    UC-GL-02 Main Flow Steps 1-41:
    Tạo và lưu Chứng từ quyết toán tạm ứng ở trạng thái Chưa ghi sổ (UNPOSTED).
    Đảm bảo tính nguyên tử (EF-26, BR-GL-QTTU-48), chống lưu trùng (EF-25, BR-GL-QTTU-47),
    không làm thay đổi số dư tài khoản chính thức khi chưa ghi sổ (BR-GL-QTTU-43, BR-GL-QTTU-44).
    """
    from organization.models import Company

    company = Company.objects.select_for_update().get(pk=company.pk)

    idempotency_key = str(data.get("idempotency_key") or "").strip()
    if idempotency_key:
        existing = models.AdvanceSettlementVoucher.objects.filter(
            company=company, idempotency_key=idempotency_key
        ).first()
        if existing:
            return existing, False

    if "number" in data and data.get("number") is not None and str(data.get("number")).strip() == "" and bool(data.get("require_explicit_number", False)):
        raise ValidationError({"number": "Số chứng từ là bắt buộc."})

    emp, dept = _resolve_settlement_employee_and_dept(company, data)
    posting_date, document_date, period = _resolve_and_validate_settlement_period(company, data)

    description = str(data.get("description") or "Quyết toán tạm ứng").strip() or "Quyết toán tạm ứng"
    settle_per_advance = bool(data.get("settle_per_advance") or data.get("settlePerAdvance") or False)
    group_invoices = bool(data.get("group_invoices") or data.get("groupInvoices") or False)
    attachments = _validate_settlement_attachments(data.get("attachments"))

    raw_acc_lines = data.get("accounting_lines") if "accounting_lines" in data else data.get("rows", [])
    raw_tax_lines = data.get("tax_lines") if "tax_lines" in data else data.get("taxRows", [])

    prepared_acc, accounting_amount, acc_141_credit = _validate_and_prepare_accounting_lines(
        company, emp, dept, posting_date, raw_acc_lines, description
    )
    prepared_tax, tax_amount, tax_141_credit = _validate_and_prepare_tax_lines(
        company,
        emp,
        raw_tax_lines,
        exclude_voucher_id=None,
        allow_duplicate_invoice=bool(data.get("allow_duplicate_invoice", False)),
    )

    total_amount = accounting_amount + tax_amount
    total_141_settled = acc_141_credit + tax_141_credit if (acc_141_credit + tax_141_credit) > Decimal("0") else total_amount

    req_obj = _validate_and_resolve_source_request(company, emp, data, accounting_amount, total_amount)
    cash_adv, src_adv_ref, src_adv_amt = _validate_and_resolve_source_advance(
        company, emp, data, total_141_settled
    )

    number = next_advance_settlement_voucher_number(company, data.get("number"))
    user_acc = actor(request)

    refs = list(data.get("references") or [])
    if req_obj and req_obj.number not in [str(r) for r in refs]:
        refs.append(req_obj.number)
    if src_adv_ref and src_adv_ref not in [str(r) for r in refs]:
        refs.append(src_adv_ref)

    # Tạo bản ghi JournalEntry ở trạng thái DRAFT (Chưa ghi sổ)
    dummy_voucher = models.AdvanceSettlementVoucher(
        company=company,
        branch=emp.branch or (dept.branch if dept else None),
        period=period,
        number=number,
        posting_date=posting_date,
        document_date=document_date,
        employee=emp,
        department=dept,
        description=description,
        settle_per_advance=settle_per_advance,
        group_invoices=group_invoices,
    )
    entry = _sync_voucher_to_draft_journal_entry(dummy_voucher, prepared_acc, prepared_tax, user_acc)

    voucher = models.AdvanceSettlementVoucher.objects.create(
        company=company,
        branch=emp.branch or (dept.branch if dept else None),
        period=period,
        number=number,
        posting_date=posting_date,
        document_date=document_date,
        employee=emp,
        department=dept,
        description=description,
        settle_per_advance=settle_per_advance,
        group_invoices=group_invoices,
        advance_request=req_obj,
        cash_advance=cash_adv,
        source_advance_ref=src_adv_ref,
        source_advance_amount=src_adv_amt,
        references=refs,
        attachments=attachments,
        accounting_amount=accounting_amount,
        tax_amount=tax_amount,
        total_amount=total_amount,
        status=models.AdvanceSettlementVoucherStatus.UNPOSTED,
        journal_entry=entry,
        idempotency_key=idempotency_key,
        version=1,
        created_by=user_acc,
    )

    entry.source_entity_id = voucher.id
    entry.save(update_fields=("source_entity_id",))

    for item in prepared_acc:
        models.AdvanceSettlementLine.objects.create(voucher=voucher, **item)

    for t_item in prepared_tax:
        models.AdvanceSettlementTaxLine.objects.create(voucher=voucher, **t_item)

    if req_obj:
        _update_advance_request_settlement_link(req_obj)

    audit(
        request,
        voucher,
        "CREATE_ADVANCE_SETTLEMENT_VOUCHER",
        before={},
        after={
            "number": voucher.number,
            "employee": emp.full_name,
            "posting_date": str(posting_date),
            "document_date": str(document_date),
            "accounting_amount": str(accounting_amount),
            "tax_amount": str(tax_amount),
            "total_amount": str(total_amount),
            "status": voucher.status,
            "advance_request": req_obj.number if req_obj else None,
            "source_advance_ref": src_adv_ref or None,
        },
        reason=description,
    )
    return voucher, True


@transaction.atomic
def update_advance_settlement_voucher(voucher, data, request):
    """
    AF-13, EF-28, BR-GL-QTTU-56, BR-GL-QTTU-57:
    Cập nhật chứng từ quyết toán tạm ứng khi đang ở trạng thái Chưa ghi sổ (UNPOSTED).
    Chặn sửa trực tiếp nếu chứng từ đã ghi sổ (POSTED).
    """
    voucher = models.AdvanceSettlementVoucher.objects.select_for_update().get(pk=voucher.pk)

    if "version" in data and data.get("version") is not None:
        try:
            if int(data["version"]) != voucher.version:
                raise ValidationError({"version": "Chứng từ đã được người dùng khác cập nhật, vui lòng tải lại."})
        except (ValueError, TypeError):
            pass

    if voucher.status != models.AdvanceSettlementVoucherStatus.UNPOSTED or voucher.journal_entry.status == models.JournalStatus.POSTED:
        raise ValidationError({
            "status": f"Chứng từ quyết toán tạm ứng {voucher.number} đã được ghi sổ, không được phép sửa trực tiếp (vui lòng Bỏ ghi trước khi sửa)."
        })

    before_snapshot = {
        "number": voucher.number,
        "employee": str(voucher.employee_id),
        "posting_date": str(voucher.posting_date),
        "document_date": str(voucher.document_date),
        "total_amount": str(voucher.total_amount),
        "status": voucher.status,
    }

    old_req = voucher.advance_request

    merged = {
        "employee": data.get("employee", voucher.employee_id),
        "department": data.get("department", voucher.department_id),
        "posting_date": data.get("posting_date", data.get("postingDate", voucher.posting_date)),
        "document_date": data.get("document_date", data.get("docDate", voucher.document_date)),
        "description": data.get("description", voucher.description),
        "settle_per_advance": data.get("settle_per_advance", data.get("settlePerAdvance", voucher.settle_per_advance)),
        "group_invoices": data.get("group_invoices", data.get("groupInvoices", voucher.group_invoices)),
        "advance_request": data.get("advance_request", voucher.advance_request_id),
        "cash_advance": data.get("cash_advance", voucher.cash_advance_id),
        "source_advance_ref": data.get("source_advance_ref", data.get("sourceAdvanceRef", voucher.source_advance_ref)),
        "source_advance_amount": data.get("source_advance_amount", data.get("sourceAdvanceAmount", voucher.source_advance_amount)),
        "attachments": data.get("attachments", voucher.attachments),
        "references": data.get("references", voucher.references),
        "allow_duplicate_invoice": data.get("allow_duplicate_invoice", False),
        "allow_exceed_request_amount": data.get("allow_exceed_request_amount", False),
        "allow_exceed_advance_balance": data.get("allow_exceed_advance_balance", False),
    }

    emp, dept = _resolve_settlement_employee_and_dept(voucher.company, merged)
    posting_date, document_date, period = _resolve_and_validate_settlement_period(voucher.company, merged)

    custom_num = data.get("number", voucher.number)
    if str(custom_num or "").strip() == "":
        raise ValidationError({"number": "Số chứng từ là bắt buộc."})
    number = next_advance_settlement_voucher_number(
        voucher.company,
        custom_number=custom_num,
        exclude_voucher_id=voucher.id,
        exclude_entry_id=voucher.journal_entry_id,
    )

    description = str(merged["description"] or "Quyết toán tạm ứng").strip() or "Quyết toán tạm ứng"
    settle_per_advance = bool(merged["settle_per_advance"])
    group_invoices = bool(merged["group_invoices"])
    attachments = _validate_settlement_attachments(merged["attachments"])

    raw_acc_lines = data.get("accounting_lines") if "accounting_lines" in data else data.get("rows")
    if raw_acc_lines is None:
        raw_acc_lines = [
            {
                "description": l.description,
                "debit_account": l.debit_account_id,
                "credit_account": l.credit_account_id,
                "amount": l.amount,
                "debit_object_code": l.debit_object_code,
                "debit_object_name": l.debit_object_name,
                "credit_object_code": l.credit_object_code,
                "credit_object_name": l.credit_object_name,
                "party": l.party_id,
                "department": l.department_id,
                "project": l.project_id,
                "cost_center": l.cost_center_id,
                "warehouse": l.warehouse_id,
                "dimensions": l.dimensions,
            }
            for l in voucher.accounting_lines.all()
        ]

    raw_tax_lines = data.get("tax_lines") if "tax_lines" in data else data.get("taxRows")
    if raw_tax_lines is None:
        raw_tax_lines = [
            {
                "description": t.description,
                "tax_account": t.tax_account_id,
                "credit_account": t.credit_account_id,
                "goods_group": t.goods_group,
                "pre_tax_amount": t.pre_tax_amount,
                "vat_rate": t.vat_rate,
                "vat_amount": t.vat_amount,
                "invoice_date": t.invoice_date,
                "invoice_number": t.invoice_number,
                "invoice_form": t.invoice_form,
                "invoice_serial": t.invoice_serial,
                "supplier": t.supplier_id,
                "supplier_code": t.supplier_code,
                "supplier_name": t.supplier_name,
                "supplier_tax_code": t.supplier_tax_code,
            }
            for t in voucher.tax_lines.all()
        ]

    prepared_acc, accounting_amount, acc_141_credit = _validate_and_prepare_accounting_lines(
        voucher.company, emp, dept, posting_date, raw_acc_lines, description
    )
    prepared_tax, tax_amount, tax_141_credit = _validate_and_prepare_tax_lines(
        voucher.company,
        emp,
        raw_tax_lines,
        exclude_voucher_id=voucher.id,
        allow_duplicate_invoice=bool(merged["allow_duplicate_invoice"]),
    )

    total_amount = accounting_amount + tax_amount
    total_141_settled = acc_141_credit + tax_141_credit if (acc_141_credit + tax_141_credit) > Decimal("0") else total_amount

    req_obj = _validate_and_resolve_source_request(
        voucher.company, emp, merged, accounting_amount, total_amount, exclude_voucher_id=voucher.id
    )
    cash_adv, src_adv_ref, src_adv_amt = _validate_and_resolve_source_advance(
        voucher.company, emp, merged, total_141_settled, exclude_voucher_id=voucher.id
    )

    refs = list(merged.get("references") or [])
    if req_obj and req_obj.number not in [str(r) for r in refs]:
        refs.append(req_obj.number)
    if src_adv_ref and src_adv_ref not in [str(r) for r in refs]:
        refs.append(src_adv_ref)

    voucher.branch = emp.branch or (dept.branch if dept else None)
    voucher.period = period
    voucher.number = number
    voucher.posting_date = posting_date
    voucher.document_date = document_date
    voucher.employee = emp
    voucher.department = dept
    voucher.description = description
    voucher.settle_per_advance = settle_per_advance
    voucher.group_invoices = group_invoices
    voucher.advance_request = req_obj
    voucher.cash_advance = cash_adv
    voucher.source_advance_ref = src_adv_ref
    voucher.source_advance_amount = src_adv_amt
    voucher.references = refs
    voucher.attachments = attachments
    voucher.accounting_amount = accounting_amount
    voucher.tax_amount = tax_amount
    voucher.total_amount = total_amount
    voucher.version += 1

    user_acc = actor(request)
    _sync_voucher_to_draft_journal_entry(voucher, prepared_acc, prepared_tax, user_acc)
    voucher.save()

    voucher.accounting_lines.all().delete()
    for item in prepared_acc:
        models.AdvanceSettlementLine.objects.create(voucher=voucher, **item)

    voucher.tax_lines.all().delete()
    for t_item in prepared_tax:
        models.AdvanceSettlementTaxLine.objects.create(voucher=voucher, **t_item)

    if old_req and (not req_obj or old_req.id != req_obj.id):
        _update_advance_request_settlement_link(old_req)
    if req_obj:
        _update_advance_request_settlement_link(req_obj)

    audit(
        request,
        voucher,
        "UPDATE_ADVANCE_SETTLEMENT_VOUCHER",
        before=before_snapshot,
        after={
            "number": voucher.number,
            "employee": emp.full_name,
            "posting_date": str(posting_date),
            "document_date": str(document_date),
            "total_amount": str(total_amount),
            "version": voucher.version,
        },
        reason=description,
    )
    return voucher


