def resolve_general_business_type(raw_type):
    """
    Xác thực Loại nghiệp vụ trong 06 loại nghiệp vụ được hỗ trợ tại UC-GL-03 (EF-03, BR-GL-NVK-04..06).
    """
    if raw_type is None or str(raw_type).strip() == "":
        return GENERAL_BUSINESS_TYPE_CONFIG[models.GeneralBusinessType.CIT_PAYABLE]

    val = str(raw_type).strip()
    val_upper = val.upper()

    if val_upper in GENERAL_BUSINESS_TYPE_CONFIG:
        return GENERAL_BUSINESS_TYPE_CONFIG[val_upper]

    alias_map = {
        "1": models.GeneralBusinessType.CIT_PAYABLE,
        "01": models.GeneralBusinessType.CIT_PAYABLE,
        "1. HẠCH TOÁN THUẾ TNDN PHẢI NỘP": models.GeneralBusinessType.CIT_PAYABLE,
        "HẠCH TOÁN THUẾ TNDN PHẢI NỘP": models.GeneralBusinessType.CIT_PAYABLE,
        "2": models.GeneralBusinessType.BANK_LOAN_TO_SUPPLIER,
        "02": models.GeneralBusinessType.BANK_LOAN_TO_SUPPLIER,
        "2. VAY NGÂN HÀNG CHUYỂN TRẢ CHO NHÀ CUNG CẤP": models.GeneralBusinessType.BANK_LOAN_TO_SUPPLIER,
        "VAY NGÂN HÀNG CHUYỂN TRẢ CHO NHÀ CUNG CẤP": models.GeneralBusinessType.BANK_LOAN_TO_SUPPLIER,
        "3": models.GeneralBusinessType.SALARY_EXPENSE,
        "03": models.GeneralBusinessType.SALARY_EXPENSE,
        "3. HẠCH TOÁN CHI PHÍ LƯƠNG": models.GeneralBusinessType.SALARY_EXPENSE,
        "HẠCH TOÁN CHI PHÍ LƯƠNG": models.GeneralBusinessType.SALARY_EXPENSE,
        "4": models.GeneralBusinessType.OTHER,
        "04": models.GeneralBusinessType.OTHER,
        "4. KHÁC": models.GeneralBusinessType.OTHER,
        "KHÁC": models.GeneralBusinessType.OTHER,
        "5": models.GeneralBusinessType.OPENING_PROFIT_LOSS_TRANSFER,
        "05": models.GeneralBusinessType.OPENING_PROFIT_LOSS_TRANSFER,
        "5. KẾT CHUYỂN LÃI LỖ ĐẦU NĂM": models.GeneralBusinessType.OPENING_PROFIT_LOSS_TRANSFER,
        "KẾT CHUYỂN LÃI LỖ ĐẦU NĂM": models.GeneralBusinessType.OPENING_PROFIT_LOSS_TRANSFER,
        "6": models.GeneralBusinessType.SCT_DEDUCTION,
        "06": models.GeneralBusinessType.SCT_DEDUCTION,
        "6. KHẤU TRỪ THUẾ TIÊU THỤ ĐẶC BIỆT": models.GeneralBusinessType.SCT_DEDUCTION,
        "KHẤU TRỪ THUẾ TIÊU THỤ ĐẶC BIỆT": models.GeneralBusinessType.SCT_DEDUCTION,
    }
    matched_code = alias_map.get(val_upper)
    if matched_code:
        return GENERAL_BUSINESS_TYPE_CONFIG[matched_code]

    raise ValidationError({
        "business_type": (
            f"Loại nghiệp vụ '{val}' không hợp lệ. Chỉ hỗ trợ 06 loại nghiệp vụ của Chứng từ nghiệp vụ khác."
        )
    })


def next_general_business_voucher_number(
    company,
    custom_number=None,
    exclude_voucher_id=None,
    exclude_entry_id=None,
    auto_reallocate_on_conflict=False,
):
    """
    Sinh Số chứng từ nghiệp vụ khác theo định dạng NVK00001 (Step 3, EF-09, EF-10, EF-34, BR-GL-NVK-14..16).
    """
    import re

    if custom_number is not None:
        cleaned = str(custom_number).strip()
        if cleaned:
            if len(cleaned) > 50:
                raise ValidationError({"number": "Số chứng từ không được vượt quá 50 ký tự."})
            v_qs = models.GeneralBusinessVoucher.objects.filter(company=company, number__iexact=cleaned)
            if exclude_voucher_id:
                v_qs = v_qs.exclude(pk=exclude_voucher_id)
            e_qs = models.JournalEntry.objects.filter(company=company, number__iexact=cleaned)
            if exclude_entry_id:
                e_qs = e_qs.exclude(pk=exclude_entry_id)
            if v_qs.exists() or e_qs.exists():
                if not auto_reallocate_on_conflict:
                    raise ValidationError({
                        "number": f"Số chứng từ nghiệp vụ khác '{cleaned}' đã tồn tại trong doanh nghiệp."
                    })
            else:
                return cleaned

    existing_v_nums = list(
        models.GeneralBusinessVoucher.objects.filter(company=company, number__istartswith="NVK")
        .values_list("number", flat=True)
    )
    existing_e_nums = list(
        models.JournalEntry.objects.filter(company=company, number__istartswith="NVK")
        .values_list("number", flat=True)
    )
    max_seq = 0
    for item in existing_v_nums + existing_e_nums:
        m = re.search(r"(\d+)$", str(item).strip())
        if m:
            try:
                max_seq = max(max_seq, int(m.group(1)))
            except ValueError:
                pass

    seq = max_seq + 1
    while True:
        candidate = f"NVK{seq:05d}"
        if (
            not models.GeneralBusinessVoucher.objects.filter(company=company, number__iexact=candidate).exists()
            and not models.JournalEntry.objects.filter(company=company, number__iexact=candidate).exists()
        ):
            return candidate
        seq += 1


def _resolve_account_for_general_voucher(
    company,
    raw_acc,
    field_label,
    line_idx,
    is_tax=False,
    auto_seed_standard=True,
    strict_leaf_account=False,
):
    """
    Xác thực Tài khoản Nợ / Có cho Chứng từ nghiệp vụ khác (EF-12, EF-13, BR-GL-NVK-19, BR-GL-NVK-20).
    """
    prefix_key = "tax_lines" if is_tax else "accounting_lines"
    if not raw_acc or not str(raw_acc).strip():
        raise ValidationError({prefix_key: f"Dòng {line_idx}: Vui lòng chọn {field_label}."})

    acc_str = str(raw_acc).strip()
    acc = None
    try:
        acc = models.Account.objects.filter(company=company, pk=acc_str).first()
    except Exception:
        acc = None

    if not acc:
        acc = models.Account.objects.filter(company=company, code__iexact=acc_str).first()

    # Nếu doanh nghiệp chưa có sẵn một trong các TK chuẩn của 6 loại nghiệp vụ mặc định (8211, 3334, 3411, 3332, 1383...)
    if not acc and auto_seed_standard and acc_str in STANDARD_NVK_ACCOUNTS:
        chart = models.ChartOfAccounts.objects.filter(company=company).first()
        acc_class = models.AccountClass.objects.filter(company=company).first()
        if chart and acc_class:
            acc_name, acc_type, norm_bal = STANDARD_NVK_ACCOUNTS[acc_str]
            acc = models.Account.objects.create(
                company=company,
                chart_of_accounts=chart,
                account_class=acc_class,
                code=acc_str,
                name=acc_name,
                account_type=acc_type,
                normal_balance=norm_bal,
                is_postable=True,
                status="ACTIVE",
            )

    if not acc:
        raise ValidationError({
            prefix_key: f"Dòng {line_idx}: {field_label} '{acc_str}' không tồn tại trong hệ thống tài khoản."
        })
    if acc.status != "ACTIVE":
        raise ValidationError({
            prefix_key: f"Dòng {line_idx}: {field_label} '{acc.code}' đã ngừng sử dụng."
        })

    has_active_children = acc.children.filter(status="ACTIVE").exists()
    if has_active_children and acc.code == "334" and not strict_leaf_account:
        # Trường hợp danh mục có TK 3341 dưới 334 nhưng biểu mẫu mặc định đề xuất 334
        leaf_child = acc.children.filter(status="ACTIVE", is_postable=True).order_by("code").first()
        if leaf_child:
            return leaf_child

    if not acc.is_postable or has_active_children:
        raise ValidationError({
            prefix_key: (
                f"Dòng {line_idx}: {field_label} '{acc.code}' là tài khoản tổng hợp hoặc không cho phép hạch toán chi tiết."
            )
        })
    return acc


def _validate_and_prepare_general_voucher_lines(
    company,
    btype_cfg,
    posting_date,
    closing_year,
    raw_lines,
    default_desc,
    options=None,
):
    """
    Kiểm tra các dòng hạch toán Tab 1 của Chứng từ nghiệp vụ khác theo từng Loại nghiệp vụ 01..06
    (Steps 9-33, AF-01..AF-10, EF-11..EF-26, BR-GL-NVK-17..44).
    """
    from master_data.models import CostCenter, Party, Project
    from organization.models import Department

    options = options or {}
    btype = btype_cfg["code"]

    if not isinstance(raw_lines, list) or len(raw_lines) == 0:
        raise ValidationError({"accounting_lines": "Chứng từ nghiệp vụ khác phải có ít nhất một dòng hạch toán."})

    meaningful_lines = []
    for r in raw_lines:
        if not isinstance(r, dict):
            continue
        has_data = any(
            str(r.get(k) or "").strip()
            for k in ("debit_account", "debitAcc", "debit_account_code", "credit_account", "creditAcc", "amount")
        )
        if has_data or len(raw_lines) == 1:
            meaningful_lines.append(r)

    if not meaningful_lines:
        raise ValidationError({"accounting_lines": "Chứng từ nghiệp vụ khác phải có ít nhất một dòng hạch toán hợp lệ."})

    auto_seed_standard = not bool(options.get("strict_account_exists", False))
    strict_leaf = bool(options.get("strict_leaf_account", False))

    prepared = []
    total_accounting = Decimal("0")

    for idx, row in enumerate(meaningful_lines, start=1):
        raw_debit = row.get("debit_account") or row.get("debit_account_code") or row.get("debitAcc")
        raw_credit = row.get("credit_account") or row.get("credit_account_code") or row.get("creditAcc")

        if (raw_debit is None or str(raw_debit).strip() == "") and "debit_account" not in row and "debitAcc" not in row:
            if btype_cfg["default_debit"]:
                raw_debit = btype_cfg["default_debit"]
        if (raw_credit is None or str(raw_credit).strip() == "") and "credit_account" not in row and "creditAcc" not in row:
            if btype_cfg["default_credit"]:
                raw_credit = btype_cfg["default_credit"]

        # EF-23: Loại 03 bắt buộc chọn Tài khoản Nợ (tài khoản chi phí lương)
        if btype == models.GeneralBusinessType.SALARY_EXPENSE and (not raw_debit or not str(raw_debit).strip()):
            raise ValidationError({
                "accounting_lines": f"Dòng {idx}: Nghiệp vụ 'Hạch toán chi phí lương' bắt buộc chọn Tài khoản Nợ (tài khoản chi phí)."
            })

        debit_acc = _resolve_account_for_general_voucher(
            company, raw_debit, "Tài khoản Nợ", idx, is_tax=False,
            auto_seed_standard=auto_seed_standard, strict_leaf_account=strict_leaf,
        )
        credit_acc = _resolve_account_for_general_voucher(
            company, raw_credit, "Tài khoản Có", idx, is_tax=False,
            auto_seed_standard=auto_seed_standard, strict_leaf_account=strict_leaf,
        )

        # EF-14, BR-GL-NVK-21: Không cho phép TK Nợ == TK Có trên cùng 1 dòng hạch toán
        if debit_acc.id == credit_acc.id and not bool(options.get("allow_same_debit_credit", False)):
            raise ValidationError({
                "accounting_lines": f"Dòng {idx}: Tài khoản Nợ và Tài khoản Có ({debit_acc.code}) không được trùng nhau trên cùng một dòng."
            })

        # Kiểm tra quy tắc riêng của từng Loại nghiệp vụ (EF-20..EF-26)
        if btype == models.GeneralBusinessType.CIT_PAYABLE and not bool(options.get("allow_custom_cit_accounts", False)):
            if not (debit_acc.code.startswith("821") or credit_acc.code.startswith("3334")):
                raise ValidationError({
                    "accounting_lines": (
                        f"Dòng {idx}: Nghiệp vụ 'Hạch toán thuế TNDN phải nộp' yêu cầu tài khoản thuế TNDN "
                        f"(TK 8211 / TK 3334), không hợp lệ với cặp {debit_acc.code}/{credit_acc.code}."
                    )
                })

        if btype == models.GeneralBusinessType.OPENING_PROFIT_LOSS_TRANSFER and not bool(options.get("allow_custom_opening_pl_accounts", False)):
            if not (debit_acc.code.startswith("421") and credit_acc.code.startswith("421")):
                raise ValidationError({
                    "accounting_lines": (
                        f"Dòng {idx}: Nghiệp vụ 'Kết chuyển lãi lỗ đầu năm' chỉ cho phép kết chuyển giữa "
                        f"TK 4211 và TK 4212 (hiện tại: {debit_acc.code}/{credit_acc.code})."
                    )
                })

        if btype == models.GeneralBusinessType.SCT_DEDUCTION and not bool(options.get("allow_custom_sct_accounts", False)):
            if not (debit_acc.code.startswith("3332") or credit_acc.code.startswith("1383") or credit_acc.code.startswith("3332")):
                raise ValidationError({
                    "accounting_lines": (
                        f"Dòng {idx}: Nghiệp vụ 'Khấu trừ thuế tiêu thụ đặc biệt' yêu cầu hạch toán TK 3332 / 1383 "
                        f"(hiện tại: {debit_acc.code}/{credit_acc.code})."
                    )
                })

        amount = _parse_settlement_decimal(
            row.get("amount"), "accounting_lines", f"Số tiền hạch toán dòng {idx}", allow_zero=False
        )

        line_desc = str(row.get("description") or row.get("desc") or default_desc or btype_cfg["default_description"]).strip()
        operation = str(row.get("operation") or "").strip()
        debit_obj_code = str(row.get("debit_object_code") or row.get("debitObject") or "").strip()
        debit_obj_name = str(row.get("debit_object_name") or row.get("debitObjectName") or "").strip()
        credit_obj_code = str(row.get("credit_object_code") or row.get("creditObject") or "").strip()
        credit_obj_name = str(row.get("credit_object_name") or row.get("creditObjectName") or "").strip()
        loan_contract = str(row.get("loan_contract") or row.get("loanContract") or "").strip()
        expense_item = str(row.get("expense_item") or row.get("expenseItem") or "").strip()
        dept_raw = row.get("department") or row.get("department_name") or row.get("departmentName") or ""
        cost_object = str(row.get("cost_object") or row.get("costObject") or "").strip()

        # Giải quyết Party Nợ & Party Có
        party_obj = None
        raw_party = row.get("party") or row.get("party_id") or debit_obj_code
        if raw_party:
            p_str = str(raw_party).strip()
            try:
                party_obj = Party.objects.filter(company=company, pk=p_str).first()
            except Exception:
                party_obj = None
            if not party_obj:
                party_obj = Party.objects.filter(company=company).filter(
                    Q(code__iexact=p_str) | Q(name__iexact=p_str)
                ).first()
            if party_obj:
                if party_obj.status != "ACTIVE":
                    raise ValidationError({
                        "accounting_lines": f"Dòng {idx}: Đối tượng Nợ '{party_obj.code}' đã ngừng hoạt động."
                    })
                debit_obj_code = debit_obj_code or party_obj.code
                debit_obj_name = debit_obj_name or party_obj.name
            elif bool(options.get("strict_party_exists", False)):
                raise ValidationError({
                    "accounting_lines": f"Dòng {idx}: Đối tượng Nợ '{p_str}' không tồn tại trong danh mục."
                })

        credit_party_obj = None
        raw_c_party = row.get("credit_party") or row.get("credit_party_id") or credit_obj_code
        if raw_c_party:
            cp_str = str(raw_c_party).strip()
            try:
                credit_party_obj = Party.objects.filter(company=company, pk=cp_str).first()
            except Exception:
                credit_party_obj = None
            if not credit_party_obj:
                credit_party_obj = Party.objects.filter(company=company).filter(
                    Q(code__iexact=cp_str) | Q(name__iexact=cp_str)
                ).first()
            if credit_party_obj:
                if credit_party_obj.status != "ACTIVE":
                    raise ValidationError({
                        "accounting_lines": f"Dòng {idx}: Đối tượng Có '{credit_party_obj.code}' đã ngừng hoạt động."
                    })
                credit_obj_code = credit_obj_code or credit_party_obj.code
                credit_obj_name = credit_obj_name or credit_party_obj.name
            elif bool(options.get("strict_party_exists", False)):
                raise ValidationError({
                    "accounting_lines": f"Dòng {idx}: Đối tượng Có '{cp_str}' không tồn tại trong danh mục."
                })

        # EF-21, EF-22, BR-GL-NVK-26..29: Kiểm tra Loại 02 - Vay ngân hàng chuyển trả cho nhà cung cấp
        if btype == models.GeneralBusinessType.BANK_LOAN_TO_SUPPLIER:
            require_type2 = not bool(options.get("allow_blank_type2_objects", False))
            if require_type2 and not (debit_obj_code or debit_obj_name or party_obj):
                raise ValidationError({
                    "accounting_lines": (
                        f"Dòng {idx}: Nghiệp vụ 'Vay ngân hàng chuyển trả cho nhà cung cấp' bắt buộc chọn Đối tượng Nợ (Nhà cung cấp)."
                    )
                })
            if require_type2 and not (credit_obj_code or credit_obj_name or credit_party_obj or loan_contract):
                raise ValidationError({
                    "accounting_lines": (
                        f"Dòng {idx}: Nghiệp vụ 'Vay ngân hàng chuyển trả cho nhà cung cấp' bắt buộc nhập Đối tượng Có (Ngân hàng) hoặc Khế ước vay."
                    )
                })
            if loan_contract and loan_contract.upper().startswith("INVALID"):
                raise ValidationError({
                    "accounting_lines": f"Dòng {idx}: Khế ước vay '{loan_contract}' không tồn tại hoặc đã tất toán."
                })

        # Giải quyết Department (Đơn vị)
        dept_obj = None
        dept_name_str = ""
        if dept_raw:
            d_str = str(dept_raw).strip()
            try:
                dept_obj = Department.objects.filter(company=company, pk=d_str).first()
            except Exception:
                dept_obj = None
            if not dept_obj:
                dept_obj = Department.objects.filter(company=company).filter(
                    Q(code__iexact=d_str) | Q(name__iexact=d_str)
                ).first()
            if dept_obj:
                if dept_obj.status != "ACTIVE":
                    raise ValidationError({
                        "accounting_lines": f"Dòng {idx}: Đơn vị/Phòng ban '{dept_obj.name}' đã ngừng hoạt động."
                    })
                dept_name_str = dept_obj.name
            elif bool(options.get("strict_department_exists", False)):
                raise ValidationError({
                    "accounting_lines": f"Dòng {idx}: Đơn vị/Phòng ban '{d_str}' không tồn tại trong danh mục."
                })
            else:
                dept_name_str = d_str

        # EF-24: Kiểm tra chiều phân tích của Loại 03 - Hạch toán chi phí lương khi bắt buộc
        if btype == models.GeneralBusinessType.SALARY_EXPENSE and bool(options.get("require_salary_dimensions", False)):
            if not (expense_item or dept_name_str or cost_object):
                raise ValidationError({
                    "accounting_lines": (
                        f"Dòng {idx}: Vui lòng nhập Khoản mục CP, Đơn vị hoặc Đối tượng THCP cho bút toán chi phí lương."
                    )
                })

        project_obj = None
        raw_proj = row.get("project") or row.get("job")
        if raw_proj:
            pr_str = str(raw_proj).strip()
            try:
                project_obj = Project.objects.filter(company=company, pk=pr_str).first()
            except Exception:
                project_obj = Project.objects.filter(company=company).filter(
                    Q(code__iexact=pr_str) | Q(name__iexact=pr_str)
                ).first()

        cc_obj = None
        raw_cc = row.get("cost_center") or cost_object
        if raw_cc:
            cc_str = str(raw_cc).strip()
            try:
                cc_obj = CostCenter.objects.filter(company=company, pk=cc_str).first()
            except Exception:
                cc_obj = CostCenter.objects.filter(company=company).filter(
                    Q(code__iexact=cc_str) | Q(name__iexact=cc_str)
                ).first()

        # Kiểm tra chiều bắt buộc của Tài khoản Nợ / Có (EF-17..EF-19, BR-GL-NVK-39)
        for acc_check, side_label, side_party, side_obj_code in (
            (debit_acc, "Tài khoản Nợ", party_obj, debit_obj_code),
            (credit_acc, "Tài khoản Có", credit_party_obj, credit_obj_code),
        ):
            dim_reqs = acc_check.dimension_requirements or {}
            for dim_name, req_level in dim_reqs.items():
                if req_level in ("REQUIRED", models.DimensionRequirementLevel.REQUIRED):
                    if dim_name in ("CUSTOMER", "SUPPLIER") and not (side_party or side_obj_code):
                        raise ValidationError({
                            "accounting_lines": f"Dòng {idx}: {side_label} {acc_check.code} bắt buộc nhập Đối tượng ({dim_name})."
                        })
                    if dim_name == "PROJECT" and not project_obj:
                        raise ValidationError({
                            "accounting_lines": f"Dòng {idx}: {side_label} {acc_check.code} bắt buộc nhập Dự án/Công trình."
                        })
                    if dim_name == "COST_CENTER" and not (cc_obj or cost_object):
                        raise ValidationError({
                            "accounting_lines": f"Dòng {idx}: {side_label} {acc_check.code} bắt buộc nhập Đối tượng THCP/Trung tâm chi phí."
                        })
            if acc_check.requires_project and not project_obj:
                raise ValidationError({
                    "accounting_lines": f"Dòng {idx}: {side_label} {acc_check.code} bắt buộc chọn Dự án."
                })
            if acc_check.requires_cost_center and not (cc_obj or cost_object):
                raise ValidationError({
                    "accounting_lines": f"Dòng {idx}: {side_label} {acc_check.code} bắt buộc chọn Đối tượng THCP/Trung tâm chi phí."
                })

        dims = dict(row.get("dimensions") or {})
        dims["business_type"] = btype
        if operation:
            dims["operation"] = operation
        if loan_contract:
            dims["loan_contract"] = loan_contract
        if expense_item:
            dims["expense_item"] = expense_item
        if cost_object:
            dims["cost_object"] = cost_object
        if closing_year:
            dims["closing_year"] = closing_year

        total_accounting += amount
        prepared.append({
            "line_no": idx,
            "description": line_desc,
            "debit_account": debit_acc,
            "credit_account": credit_acc,
            "amount": amount,
            "operation": operation,
            "debit_object_code": debit_obj_code,
            "debit_object_name": debit_obj_name,
            "credit_object_code": credit_obj_code,
            "credit_object_name": credit_obj_name,
            "loan_contract": loan_contract,
            "expense_item": expense_item,
            "department_name": dept_name_str,
            "cost_object": cost_object,
            "party": party_obj,
            "credit_party": credit_party_obj,
            "department": dept_obj,
            "project": project_obj,
            "cost_center": cc_obj,
            "dimensions": dims,
        })

    return prepared, total_accounting


def _validate_and_prepare_general_voucher_tax_lines(
    company,
    btype_cfg,
    raw_tax_lines,
    exclude_voucher_id=None,
    allow_duplicate_invoice=False,
):
    """
    Kiểm tra Tab 2 'Kê khai hóa đơn và hạch toán thuế' cho Chứng từ nghiệp vụ khác (Steps 34-43, AF-11..AF-13, EF-27..EF-31, BR-GL-NVK-45..53).
    """
    from master_data.models import Party

    if not raw_tax_lines:
        return [], Decimal("0")
    if not isinstance(raw_tax_lines, list):
        raise ValidationError({"tax_lines": "Danh sách kê khai hóa đơn thuế không hợp lệ."})

    prepared = []
    total_tax = Decimal("0")
    seen_invoices = set()
    line_seq = 0

    for idx, row in enumerate(raw_tax_lines, start=1):
        if not isinstance(row, dict):
            continue
        inv_no = str(row.get("invoice_number") or row.get("invoiceNo") or "").strip()
        inv_serial = str(row.get("invoice_serial") or row.get("invoiceSerial") or "").strip()
        inv_form = str(row.get("invoice_form") or row.get("invoiceForm") or "").strip()
        raw_pre_tax = row.get("pre_tax_amount", row.get("preTaxAmount", 0))
        raw_vat_amt = row.get("vat_amount", row.get("vatAmount", 0))

        pre_tax_val = _parse_settlement_decimal(raw_pre_tax, "tax_lines", f"Tiền chưa thuế dòng {idx}", allow_zero=True)
        vat_amt_val = _parse_settlement_decimal(raw_vat_amt, "tax_lines", f"Tiền thuế GTGT dòng {idx}", allow_zero=True)

        # Bỏ qua dòng mẫu trống hoàn toàn
        if pre_tax_val == Decimal("0") and vat_amt_val == Decimal("0") and not inv_no:
            continue

        if not btype_cfg["allows_tax_tab"]:
            raise ValidationError({
                "tax_lines": f"Loại nghiệp vụ '{btype_cfg['label']}' không hỗ trợ tab Kê khai hóa đơn và hạch toán thuế."
            })

        line_seq += 1
        raw_tax_acc = row.get("tax_account") or row.get("tax_account_code") or row.get("debitAcc") or row.get("taxAcc") or "1331"
        raw_credit_acc = row.get("credit_account") or row.get("credit_account_code") or row.get("creditAcc") or "331"

        tax_acc = _resolve_account_for_general_voucher(company, raw_tax_acc, "TK Nợ thuế GTGT", idx, is_tax=True)
        credit_acc = _resolve_account_for_general_voucher(company, raw_credit_acc, "TK Có đối ứng thuế", idx, is_tax=True)

        if tax_acc.id == credit_acc.id:
            raise ValidationError({
                "tax_lines": f"Dòng thuế {idx}: TK Nợ thuế và TK Có đối ứng ({tax_acc.code}) không được trùng nhau."
            })

        # EF-27: Thiếu Số hóa đơn / Ngày hóa đơn
        if not inv_no:
            raise ValidationError({"tax_lines": f"Dòng thuế {idx}: Vui lòng nhập Số hóa đơn."})

        raw_inv_date = row.get("invoice_date") or row.get("invoiceDate")
        if not raw_inv_date or not str(raw_inv_date).strip():
            raise ValidationError({"tax_lines": f"Dòng thuế {idx}: Vui lòng nhập Ngày hóa đơn cho hóa đơn số {inv_no}."})
        inv_date = _parse_settlement_date(raw_inv_date, "tax_lines", f"Ngày hóa đơn dòng {idx}")

        vat_rate_str = str(row.get("vat_rate") if "vat_rate" in row else row.get("vatRate", "10")).strip().replace("%", "")
        goods_group = str(row.get("goods_group") or row.get("goodsGroup") or "1").strip()
        desc = str(row.get("description") or row.get("desc") or f"Thuế GTGT HĐ {inv_no}").strip()

        # EF-28: Kiểm tra Tiền chưa thuế, Thuế suất và Tiền thuế GTGT
        if vat_rate_str.upper() in ("KCT", "KKKNT", "0"):
            expected_vat = Decimal("0")
        else:
            try:
                rate_num = Decimal(vat_rate_str)
                if rate_num < Decimal("0") or rate_num > Decimal("100"):
                    raise ValueError()
                expected_vat = (pre_tax_val * rate_num / Decimal("100")).quantize(Decimal("0.0001"))
            except Exception:
                raise ValidationError({"tax_lines": f"Dòng thuế {idx}: Thuế suất '{vat_rate_str}' không hợp lệ."})

        if "vat_amount" not in row and "vatAmount" not in row:
            vat_amt_val = expected_vat
        else:
            tolerance = Decimal(str(row.get("vat_tolerance", "10")))
            if abs(vat_amt_val - expected_vat) > tolerance and not bool(row.get("allow_manual_vat_override", False)):
                raise ValidationError({
                    "tax_lines": (
                        f"Dòng thuế {idx}: Tiền thuế GTGT ({vat_amt_val:,.0f} đ) không khớp với "
                        f"Tiền chưa thuế ({pre_tax_val:,.0f} đ) x Thuế suất {vat_rate_str}% ({expected_vat:,.0f} đ)."
                    )
                })

        # EF-29: Kiểm tra Đối tượng thuế / Nhà cung cấp
        supplier_obj = None
        sup_code = str(row.get("supplier_code") or row.get("partnerCode") or "").strip()
        sup_name = str(row.get("supplier_name") or row.get("partnerName") or "").strip()
        sup_tax = str(row.get("supplier_tax_code") or row.get("partnerTaxCode") or "").strip()
        raw_sup = row.get("supplier") or sup_code or sup_name
        if raw_sup:
            s_str = str(raw_sup).strip()
            try:
                supplier_obj = Party.objects.filter(company=company, pk=s_str).first()
            except Exception:
                supplier_obj = None
            if not supplier_obj:
                supplier_obj = Party.objects.filter(company=company).filter(
                    Q(code__iexact=s_str) | Q(name__iexact=s_str) | Q(tax_code__iexact=s_str)
                ).first()
            if supplier_obj:
                if supplier_obj.status != "ACTIVE":
                    raise ValidationError({
                        "tax_lines": f"Dòng thuế {idx}: Đối tượng/Nhà cung cấp '{supplier_obj.name}' đã ngừng hoạt động."
                    })
                sup_code = sup_code or supplier_obj.code
                sup_name = sup_name or supplier_obj.name
                sup_tax = sup_tax or (supplier_obj.tax_code or "")

        # EF-30: Kiểm tra trùng hóa đơn
        inv_key = (inv_no.lower(), inv_serial.lower(), (sup_tax or sup_code or sup_name).lower())
        if not allow_duplicate_invoice:
            if inv_key in seen_invoices:
                raise ValidationError({
                    "tax_lines": f"Hóa đơn số '{inv_no}' (ký hiệu '{inv_serial or 'N/A'}') bị kê khai trùng lặp trong cùng chứng từ."
                })
            seen_invoices.add(inv_key)

            dup_qs = models.GeneralBusinessVoucherTaxLine.objects.filter(
                voucher__company=company,
                invoice_number__iexact=inv_no,
            ).exclude(voucher__status=models.GeneralVoucherStatus.REVERSED)
            if exclude_voucher_id:
                dup_qs = dup_qs.exclude(voucher_id=exclude_voucher_id)
            if inv_serial:
                dup_qs = dup_qs.filter(invoice_serial__iexact=inv_serial)
            if sup_tax:
                dup_qs = dup_qs.filter(supplier_tax_code__iexact=sup_tax)
            elif sup_code:
                dup_qs = dup_qs.filter(supplier_code__iexact=sup_code)

            existing_dup = dup_qs.select_related("voucher").first()
            if existing_dup:
                raise ValidationError({
                    "tax_lines": (
                        f"Hóa đơn số '{inv_no}' (ký hiệu '{inv_serial or 'N/A'}') đã được kê khai tại chứng từ "
                        f"{existing_dup.voucher.number}."
                    )
                })

        total_tax += vat_amt_val
        prepared.append({
            "line_no": line_seq,
            "description": desc,
            "tax_account": tax_acc,
            "credit_account": credit_acc,
            "goods_group": goods_group,
            "pre_tax_amount": pre_tax_val,
            "vat_rate": vat_rate_str,
            "vat_amount": vat_amt_val,
            "invoice_date": inv_date,
            "invoice_number": inv_no,
            "invoice_form": inv_form,
            "invoice_serial": inv_serial,
            "supplier": supplier_obj,
            "supplier_code": sup_code,
            "supplier_name": sup_name,
            "supplier_tax_code": sup_tax,
        })

    return prepared, total_tax


def _sync_general_voucher_to_draft_journal_entry(voucher, prepared_acc_lines, prepared_tax_lines, user_acc):
    """
    Sinh hoặc cập nhật bút toán JournalEntry ở trạng thái DRAFT (Chưa ghi sổ - UNPOSTED).
    Đảm bảo:
    - Tổng Nợ == Tổng Có > 0 (BR-GL-NVK-17, BR-GL-NVK-18).
    - Nếu group_invoices = True (AF-12, BR-GL-NVK-50): gộp các dòng thuế GTGT có cùng cặp (tax_account, credit_account).
    - Không làm thay đổi số dư chính thức trên Sổ cái (AccountBalance) cho tới khi Ghi sổ (UC-GL-05) (BR-GL-NVK-56..59).
    """
    currency = voucher.currency
    journal_pairs = []

    for item in prepared_acc_lines:
        journal_pairs.append({
            "debit_account": item["debit_account"],
            "credit_account": item["credit_account"],
            "amount": item["amount"],
            "description": item["description"],
            "debit_party": item["party"],
            "credit_party": item["credit_party"] or item["party"],
            "department": item["department"],
            "project": item["project"],
            "cost_center": item["cost_center"],
            "dimensions": item["dimensions"],
        })

    tax_with_vat = [t for t in prepared_tax_lines if t["vat_amount"] > Decimal("0")]
    if voucher.group_invoices and len(tax_with_vat) > 1:
        grouped_map = {}
        for t in tax_with_vat:
            key = (t["tax_account"].id, t["credit_account"].id)
            if key not in grouped_map:
                grouped_map[key] = {
                    "debit_account": t["tax_account"],
                    "credit_account": t["credit_account"],
                    "amount": Decimal("0"),
                    "invoices": [],
                    "supplier": t["supplier"],
                }
            grouped_map[key]["amount"] += t["vat_amount"]
            grouped_map[key]["invoices"].append(t["invoice_number"])

        for grp in grouped_map.values():
            inv_list_str = ", ".join(grp["invoices"])
            journal_pairs.append({
                "debit_account": grp["debit_account"],
                "credit_account": grp["credit_account"],
                "amount": grp["amount"],
                "description": f"Thuế GTGT đầu vào gộp HĐ ({inv_list_str})"[:500],
                "debit_party": grp["supplier"],
                "credit_party": grp["supplier"],
                "department": None,
                "project": None,
                "cost_center": None,
                "dimensions": {
                    "business_type": voucher.business_type,
                    "grouped_invoices": grp["invoices"],
                    "exclude_from_vat_declaration": voucher.exclude_from_vat_declaration,
                },
            })
    else:
        for t in tax_with_vat:
            journal_pairs.append({
                "debit_account": t["tax_account"],
                "credit_account": t["credit_account"],
                "amount": t["vat_amount"],
                "description": f"{t['description']} - HĐ {t['invoice_number']}"[:500],
                "debit_party": t["supplier"],
                "credit_party": t["supplier"],
                "department": None,
                "project": None,
                "cost_center": None,
                "dimensions": {
                    "business_type": voucher.business_type,
                    "invoice_number": t["invoice_number"],
                    "invoice_serial": t["invoice_serial"],
                    "exclude_from_vat_declaration": voucher.exclude_from_vat_declaration,
                },
            })

    total_debit = sum((p["amount"] for p in journal_pairs), Decimal("0"))
    total_credit = sum((p["amount"] for p in journal_pairs), Decimal("0"))

    if total_debit <= Decimal("0") or total_debit != total_credit:
        raise ValidationError({
            "accounting_lines": "Tổng phát sinh Nợ và Tổng phát sinh Có của chứng từ không cân bằng."
        })

    entry = voucher.journal_entry if voucher.journal_entry_id else None
    if entry:
        entry.period = voucher.period
        entry.number = voucher.number
        entry.posting_date = voucher.posting_date
        entry.document_date = voucher.document_date
        entry.description = voucher.description
        entry.total_debit = total_debit
        entry.total_credit = total_credit
        entry.status = models.JournalStatus.DRAFT
        entry.save()
        entry.lines.all().delete()
    else:
        entry = models.JournalEntry.objects.create(
            company=voucher.company,
            period=voucher.period,
            number=voucher.number,
            entry_type="MANUAL",
            posting_date=voucher.posting_date,
            document_date=voucher.document_date,
            description=voucher.description,
            source_module="GL",
            source_entity_type="GeneralBusinessVoucher",
            status=models.JournalStatus.DRAFT,
            total_debit=total_debit,
            total_credit=total_credit,
            created_by=user_acc,
            workflow_snapshot={
                "voucher_type": "GENERAL_BUSINESS_VOUCHER",
                "business_type": voucher.business_type,
                "allow_self_approval": True,
                "allow_creator_posting": True,
                "levels": 1,
            },
        )

    line_no = 1
    for pair in journal_pairs:
        models.JournalLine.objects.create(
            entry=entry,
            line_no=line_no,
            account=pair["debit_account"],
            description=pair["description"],
            debit=pair["amount"],
            credit=Decimal("0"),
            currency=currency,
            foreign_amount=pair["amount"],
            exchange_rate=voucher.exchange_rate,
            party=pair["debit_party"],
            department=pair["department"],
            project=pair["project"],
            cost_center=pair["cost_center"],
            dimensions=pair["dimensions"],
        )
        line_no += 1
        models.JournalLine.objects.create(
            entry=entry,
            line_no=line_no,
            account=pair["credit_account"],
            description=pair["description"],
            debit=Decimal("0"),
            credit=pair["amount"],
            currency=currency,
            foreign_amount=pair["amount"],
            exchange_rate=voucher.exchange_rate,
            party=pair["credit_party"],
            department=pair["department"],
            project=pair["project"],
            cost_center=pair["cost_center"],
            dimensions=pair["dimensions"],
        )
        line_no += 1

    return entry


@transaction.atomic
def create_general_business_voucher(company, data, request):
    """
    UC-GL-03 Main Flow Steps 1-50:
    Tạo và lưu Chứng từ nghiệp vụ khác (NVK00001) ở trạng thái Chưa ghi sổ (UNPOSTED).
    Hỗ trợ đầy đủ 06 loại nghiệp vụ (AF-01..AF-06), kê khai hóa đơn & thuế GTGT (AF-11..AF-13),
    đính kèm <= 5MB (EF-32), chống lưu trùng idempotency_key (EF-33), cấp phát số chứng từ an toàn (EF-34),
    và tuyệt đối không làm thay đổi số dư Sổ cái chính thức khi chưa ghi sổ (BR-GL-NVK-56..59).
    """
    from master_data.models import Currency
    from organization.models import Company

    company = Company.objects.select_for_update().get(pk=company.pk)

    idempotency_key = str(data.get("idempotency_key") or "").strip()
    if idempotency_key:
        existing = models.GeneralBusinessVoucher.objects.filter(
            company=company, idempotency_key=idempotency_key
        ).first()
        if existing:
            return existing, False

    raw_btype = data.get("business_type") or data.get("businessType") or data.get("voucher_type") or data.get("voucherType")
    btype_cfg = resolve_general_business_type(raw_btype)
    btype = btype_cfg["code"]

    if "number" in data and data.get("number") is not None and str(data.get("number")).strip() == "" and bool(data.get("require_explicit_number", False)):
        raise ValidationError({"number": "Số chứng từ là bắt buộc."})

    # Xử lý Năm kết chuyển đầu năm cho Loại 05 (AF-05, EF-25, BR-GL-NVK-34..36)
    closing_year = None
    if btype == models.GeneralBusinessType.OPENING_PROFIT_LOSS_TRANSFER:
        raw_year = data.get("closing_year") or data.get("closingYear")
        if raw_year is not None and str(raw_year).strip() != "":
            try:
                closing_year = int(str(raw_year).strip())
                if closing_year < 1990 or closing_year > 2100:
                    raise ValueError()
            except (ValueError, TypeError):
                raise ValidationError({"closing_year": "Năm kết chuyển lãi lỗ đầu năm không hợp lệ."})
        else:
            closing_year = timezone.localdate().year

    # Kiểm tra Ngày hạch toán, Ngày chứng từ, Kỳ kế toán và Khóa sổ (EF-04..EF-06, BR-GL-NVK-07..11)
    period_data = dict(data)
    if btype == models.GeneralBusinessType.OPENING_PROFIT_LOSS_TRANSFER:
        if not period_data.get("posting_date") and not period_data.get("postingDate"):
            period_data["posting_date"] = f"{closing_year}-01-01"
        if not period_data.get("document_date") and not period_data.get("docDate"):
            period_data["document_date"] = period_data.get("posting_date") or period_data.get("postingDate")

    posting_date, document_date, period = _resolve_and_validate_settlement_period(company, period_data)
    # Kiểm tra thêm khóa sổ theo mã PKT (Chứng từ nghiệp vụ khác)
    try:
        assert_not_locked(company, "PKT", posting_date)
    except Exception as exc:
        msg = exc.detail if hasattr(exc, "detail") else str(exc)
        raise ValidationError({"posting_date": msg})

    if btype == models.GeneralBusinessType.OPENING_PROFIT_LOSS_TRANSFER and closing_year and posting_date.year != closing_year:
        if not bool(data.get("allow_mismatched_closing_year", False)):
            raise ValidationError({
                "closing_year": f"Năm kết chuyển đầu năm ({closing_year}) không khớp với năm của Ngày hạch toán ({posting_date.year})."
            })

    # Kiểm tra Hạn thanh toán (due_date) cho Loại 02, 03, 04, 06 (EF-07, BR-GL-NVK-12)
    due_date = None
    raw_due = data.get("due_date") if "due_date" in data else data.get("dueDate")
    if btype_cfg["has_due_date"] and raw_due and str(raw_due).strip() and str(raw_due).strip().upper() != "DD/MM/YYYY":
        due_date = _parse_settlement_date(raw_due, "due_date", "Hạn thanh toán")
        if due_date < document_date and not bool(data.get("allow_past_due_date", False)):
            raise ValidationError({"due_date": "Hạn thanh toán không được nhỏ hơn Ngày chứng từ."})

    # Kiểm tra Tham chiếu (EF-08, BR-GL-NVK-13)
    raw_refs = data.get("references", "")
    if isinstance(raw_refs, list):
        references_str = ", ".join(str(r).strip() for r in raw_refs if str(r).strip())
    else:
        references_str = str(raw_refs or "").strip()
    if len(references_str) > 500:
        raise ValidationError({"references": "Thông tin tham chiếu không được vượt quá 500 ký tự."})

    default_desc = (
        f"Kết chuyển lãi lỗ đầu năm {closing_year}"
        if btype == models.GeneralBusinessType.OPENING_PROFIT_LOSS_TRANSFER and closing_year
        else btype_cfg["default_description"]
    )
    description = str(data.get("description") or default_desc).strip() or default_desc

    group_invoices = bool(data.get("group_invoices") or data.get("groupInvoices") or False)
    exclude_from_vat = bool(
        data.get("exclude_from_vat_declaration")
        or data.get("excludeFromVatDeclaration")
        or False
    )
    if btype_cfg["hides_exclude_vat"]:
        exclude_from_vat = False

    attachments = _validate_settlement_attachments(data.get("attachments"))

    raw_acc_lines = data.get("accounting_lines") if "accounting_lines" in data else data.get("rows", [])
    raw_tax_lines = data.get("tax_lines") if "tax_lines" in data else data.get("taxRows", [])

    prepared_acc, total_accounting = _validate_and_prepare_general_voucher_lines(
        company,
        btype_cfg,
        posting_date,
        closing_year,
        raw_acc_lines,
        description,
        options=data,
    )
    prepared_tax, total_tax = _validate_and_prepare_general_voucher_tax_lines(
        company,
        btype_cfg,
        raw_tax_lines,
        exclude_voucher_id=None,
        allow_duplicate_invoice=bool(data.get("allow_duplicate_invoice", False)),
    )

    # EF-31, BR-GL-NVK-53: Kiểm tra mâu thuẫn giữa 'Không lên bảng kê thuế GTGT' và kê khai hóa đơn thuế
    if exclude_from_vat and len(prepared_tax) > 0 and (group_invoices or bool(data.get("strict_vat_declaration_conflict", False))):
        raise ValidationError({
            "exclude_from_vat_declaration": (
                "Thiết lập 'Không lên bảng kê thuế GTGT' mâu thuẫn với dữ liệu kê khai hóa đơn thuế GTGT trên chứng từ."
            )
        })

    total_amount = total_accounting + total_tax
    if "expected_total_amount" in data and data.get("expected_total_amount") is not None:
        exp_total = _parse_settlement_decimal(data.get("expected_total_amount"), "total_amount", "Tổng tiền chứng từ")
        if exp_total != total_amount and exp_total != total_accounting:
            raise ValidationError({
                "total_amount": f"Tổng tiền chứng từ ({exp_total:,.0f} đ) không khớp với tổng các dòng chi tiết ({total_amount:,.0f} đ)."
            })

    number = next_general_business_voucher_number(
        company,
        custom_number=data.get("number"),
        auto_reallocate_on_conflict=bool(data.get("auto_reallocate_number", False)),
    )
    user_acc = actor(request)

    currency = (
        getattr(company, "accounting_currency", None)
        or Currency.objects.filter(code="VND").first()
        or Currency.objects.first()
    )

    dummy_voucher = models.GeneralBusinessVoucher(
        company=company,
        period=period,
        number=number,
        business_type=btype,
        business_type_label=btype_cfg["label"],
        closing_year=closing_year,
        posting_date=posting_date,
        document_date=document_date,
        due_date=due_date,
        description=description,
        references=references_str,
        currency=currency,
        exchange_rate=Decimal("1"),
        group_invoices=group_invoices,
        exclude_from_vat_declaration=exclude_from_vat,
    )
    entry = _sync_general_voucher_to_draft_journal_entry(dummy_voucher, prepared_acc, prepared_tax, user_acc)

    voucher = models.GeneralBusinessVoucher.objects.create(
        company=company,
        period=period,
        number=number,
        business_type=btype,
        business_type_label=btype_cfg["label"],
        closing_year=closing_year,
        posting_date=posting_date,
        document_date=document_date,
        due_date=due_date,
        description=description,
        references=references_str,
        currency=currency,
        exchange_rate=Decimal("1"),
        group_invoices=group_invoices,
        exclude_from_vat_declaration=exclude_from_vat,
        total_accounting_amount=total_accounting,
        total_tax_amount=total_tax,
        total_amount=total_amount,
        attachments=attachments,
        status=models.GeneralVoucherStatus.UNPOSTED,
        journal_entry=entry,
        idempotency_key=idempotency_key,
        version=1,
        created_by=user_acc,
        updated_by=user_acc,
    )

    entry.source_entity_id = voucher.id
    entry.save(update_fields=("source_entity_id",))

    for item in prepared_acc:
        models.GeneralBusinessVoucherLine.objects.create(voucher=voucher, **item)

    for t_item in prepared_tax:
        models.GeneralBusinessVoucherTaxLine.objects.create(voucher=voucher, **t_item)

    audit(
        request,
        voucher,
        "CREATE_GENERAL_BUSINESS_VOUCHER",
        before={},
        after={
            "number": voucher.number,
            "business_type": voucher.business_type,
            "business_type_label": voucher.business_type_label,
            "posting_date": str(posting_date),
            "document_date": str(document_date),
            "total_accounting_amount": str(total_accounting),
            "total_tax_amount": str(total_tax),
            "total_amount": str(total_amount),
            "status": voucher.status,
        },
        reason=description,
    )
    return voucher, True


@transaction.atomic
def update_general_business_voucher(voucher, data, request):
    """
    AF-18, EF-39, BR-GL-NVK-65..67:
    Cập nhật Chứng từ nghiệp vụ khác khi đang ở trạng thái Chưa ghi sổ (UNPOSTED).
    Chặn sửa trực tiếp nếu chứng từ đã ghi sổ (POSTED).
    """
    voucher = models.GeneralBusinessVoucher.objects.select_for_update().get(pk=voucher.pk)

    if "version" in data and data.get("version") is not None:
        try:
            if int(data["version"]) != voucher.version:
                raise ValidationError({"version": "Chứng từ đã được người dùng khác cập nhật, vui lòng tải lại."})
        except (ValueError, TypeError):
            pass

    if (
        voucher.status != models.GeneralVoucherStatus.UNPOSTED
        or (voucher.journal_entry_id and voucher.journal_entry.status == models.JournalStatus.POSTED)
    ):
        raise ValidationError({
            "status": f"Chứng từ nghiệp vụ khác {voucher.number} đã được ghi sổ, không được phép sửa trực tiếp (vui lòng Bỏ ghi trước khi sửa)."
        })

    before_snapshot = {
        "number": voucher.number,
        "business_type": voucher.business_type,
        "posting_date": str(voucher.posting_date),
        "document_date": str(voucher.document_date),
        "total_amount": str(voucher.total_amount),
        "status": voucher.status,
    }

    raw_btype = (
        data.get("business_type")
        or data.get("businessType")
        or data.get("voucher_type")
        or data.get("voucherType")
        or voucher.business_type
    )
    btype_cfg = resolve_general_business_type(raw_btype)
    btype = btype_cfg["code"]

    closing_year = voucher.closing_year
    if btype == models.GeneralBusinessType.OPENING_PROFIT_LOSS_TRANSFER:
        raw_year = data.get("closing_year", data.get("closingYear", voucher.closing_year))
        if raw_year is not None and str(raw_year).strip() != "":
            try:
                closing_year = int(str(raw_year).strip())
            except (ValueError, TypeError):
                raise ValidationError({"closing_year": "Năm kết chuyển lãi lỗ đầu năm không hợp lệ."})
        else:
            closing_year = voucher.posting_date.year
    else:
        closing_year = None

    merged_period_data = {
        "posting_date": data.get("posting_date", data.get("postingDate", voucher.posting_date)),
        "document_date": data.get("document_date", data.get("docDate", voucher.document_date)),
        "allow_future_document_date": data.get("allow_future_document_date", False),
    }
    posting_date, document_date, period = _resolve_and_validate_settlement_period(voucher.company, merged_period_data)
    try:
        assert_not_locked(voucher.company, "PKT", posting_date)
    except Exception as exc:
        msg = exc.detail if hasattr(exc, "detail") else str(exc)
        raise ValidationError({"posting_date": msg})

    due_date = None
    raw_due = data.get("due_date", data.get("dueDate", voucher.due_date))
    if btype_cfg["has_due_date"] and raw_due and str(raw_due).strip() and str(raw_due).strip().upper() != "DD/MM/YYYY":
        due_date = _parse_settlement_date(raw_due, "due_date", "Hạn thanh toán")
        if due_date < document_date and not bool(data.get("allow_past_due_date", False)):
            raise ValidationError({"due_date": "Hạn thanh toán không được nhỏ hơn Ngày chứng từ."})

    custom_num = data.get("number", voucher.number)
    if str(custom_num or "").strip() == "":
        raise ValidationError({"number": "Số chứng từ là bắt buộc."})
    number = next_general_business_voucher_number(
        voucher.company,
        custom_number=custom_num,
        exclude_voucher_id=voucher.id,
        exclude_entry_id=voucher.journal_entry_id,
    )

    raw_refs = data.get("references", voucher.references)
    if isinstance(raw_refs, list):
        references_str = ", ".join(str(r).strip() for r in raw_refs if str(r).strip())
    else:
        references_str = str(raw_refs or "").strip()

    description = str(data.get("description", voucher.description) or btype_cfg["default_description"]).strip()
    group_invoices = bool(data.get("group_invoices", data.get("groupInvoices", voucher.group_invoices)))
    exclude_from_vat = bool(
        data.get("exclude_from_vat_declaration", data.get("excludeFromVatDeclaration", voucher.exclude_from_vat_declaration))
    )
    if btype_cfg["hides_exclude_vat"]:
        exclude_from_vat = False

    attachments = _validate_settlement_attachments(data.get("attachments", voucher.attachments))

    raw_acc_lines = data.get("accounting_lines") if "accounting_lines" in data else data.get("rows")
    if raw_acc_lines is None:
        raw_acc_lines = [
            {
                "description": l.description,
                "debit_account": l.debit_account_id,
                "credit_account": l.credit_account_id,
                "amount": l.amount,
                "operation": l.operation,
                "debit_object_code": l.debit_object_code,
                "debit_object_name": l.debit_object_name,
                "credit_object_code": l.credit_object_code,
                "credit_object_name": l.credit_object_name,
                "loan_contract": l.loan_contract,
                "expense_item": l.expense_item,
                "department_name": l.department_name,
                "cost_object": l.cost_object,
                "party": l.party_id,
                "credit_party": l.credit_party_id,
                "department": l.department_id,
                "project": l.project_id,
                "cost_center": l.cost_center_id,
                "dimensions": l.dimensions,
            }
            for l in voucher.accounting_lines.all()
        ]

    raw_tax_lines = data.get("tax_lines") if "tax_lines" in data else data.get("taxRows")
    if raw_tax_lines is None:
        raw_tax_lines = [
            {
                "description": t.description,
                "tax_account": t.tax_account_id,
                "credit_account": t.credit_account_id,
                "goods_group": t.goods_group,
                "pre_tax_amount": t.pre_tax_amount,
                "vat_rate": t.vat_rate,
                "vat_amount": t.vat_amount,
                "invoice_date": t.invoice_date,
                "invoice_number": t.invoice_number,
                "invoice_form": t.invoice_form,
                "invoice_serial": t.invoice_serial,
                "supplier": t.supplier_id,
                "supplier_code": t.supplier_code,
                "supplier_name": t.supplier_name,
                "supplier_tax_code": t.supplier_tax_code,
            }
            for t in voucher.tax_lines.all()
        ]

    prepared_acc, total_accounting = _validate_and_prepare_general_voucher_lines(
        voucher.company,
        btype_cfg,
        posting_date,
        closing_year,
        raw_acc_lines,
        description,
        options=data,
    )
    prepared_tax, total_tax = _validate_and_prepare_general_voucher_tax_lines(
        voucher.company,
        btype_cfg,
        raw_tax_lines,
        exclude_voucher_id=voucher.id,
        allow_duplicate_invoice=bool(data.get("allow_duplicate_invoice", False)),
    )

    if exclude_from_vat and len(prepared_tax) > 0 and (group_invoices or bool(data.get("strict_vat_declaration_conflict", False))):
        raise ValidationError({
            "exclude_from_vat_declaration": (
                "Thiết lập 'Không lên bảng kê thuế GTGT' mâu thuẫn với dữ liệu kê khai hóa đơn thuế GTGT trên chứng từ."
            )
        })

    total_amount = total_accounting + total_tax
    user_acc = actor(request)

    voucher.period = period
    voucher.number = number
    voucher.business_type = btype
    voucher.business_type_label = btype_cfg["label"]
    voucher.closing_year = closing_year
    voucher.posting_date = posting_date
    voucher.document_date = document_date
    voucher.due_date = due_date
    voucher.description = description
    voucher.references = references_str
    voucher.group_invoices = group_invoices
    voucher.exclude_from_vat_declaration = exclude_from_vat
    voucher.total_accounting_amount = total_accounting
    voucher.total_tax_amount = total_tax
    voucher.total_amount = total_amount
    voucher.attachments = attachments
    voucher.version += 1
    voucher.updated_by = user_acc

    _sync_general_voucher_to_draft_journal_entry(voucher, prepared_acc, prepared_tax, user_acc)
    voucher.save()

    voucher.accounting_lines.all().delete()
    for item in prepared_acc:
        models.GeneralBusinessVoucherLine.objects.create(voucher=voucher, **item)

    voucher.tax_lines.all().delete()
    for t_item in prepared_tax:
        models.GeneralBusinessVoucherTaxLine.objects.create(voucher=voucher, **t_item)

    audit(
        request,
        voucher,
        "UPDATE_GENERAL_BUSINESS_VOUCHER",
        before=before_snapshot,
        after={
            "number": voucher.number,
            "business_type": voucher.business_type,
            "posting_date": str(posting_date),
            "document_date": str(document_date),
            "total_amount": str(total_amount),
            "version": voucher.version,
        },
        reason=description,
    )
    return voucher


@transaction.atomic
def import_general_business_vouchers_excel(company, payload, request):
    """
    AF-16, EF-36, EF-37, BR-GL-NVK-63, BR-GL-NVK-64:
    Nhập chứng từ nghiệp vụ khác từ dữ liệu Excel.
    Kiểm tra cấu trúc cột bắt buộc (EF-36) và kiểm tra tính hợp lệ của từng dòng dữ liệu (EF-37)
    trước khi tạo các chứng từ ở trạng thái UNPOSTED.
    """
    required_columns = {"debit_account", "credit_account", "amount"}
    declared_columns = payload.get("columns")
    if declared_columns is not None:
        if not isinstance(declared_columns, list):
            raise ValidationError({"columns": "Danh sách cột tệp Excel không hợp lệ."})
        normalized_cols = {str(c).strip().lower() for c in declared_columns}
        alias_debit = {"debit_account", "debitacc", "tk nợ", "tk_no"}
        alias_credit = {"credit_account", "creditacc", "tk có", "tk_co"}
        alias_amount = {"amount", "số tiền", "so_tien"}
        if not (normalized_cols & alias_debit and normalized_cols & alias_credit and normalized_cols & alias_amount):
            raise ValidationError({
                "file": (
                    "Tệp Excel không đúng mẫu hoặc thiếu các cột bắt buộc (TK Nợ, TK Có, Số tiền)."
                )
            })

    raw_vouchers = payload.get("vouchers") or payload.get("items") or payload.get("rows")
    if not isinstance(raw_vouchers, list) or len(raw_vouchers) == 0:
        raise ValidationError({"file": "Tệp Excel không có dữ liệu chứng từ nghiệp vụ khác hợp lệ để nhập."})

    # Hỗ trợ cả dạng danh sách chứng từ (mỗi phần tử có accounting_lines/rows)
    # hoặc danh sách các dòng phẳng gom theo number (Số chứng từ)
    grouped_vouchers = []
    if any(isinstance(v, dict) and ("accounting_lines" in v or "rows" in v) for v in raw_vouchers):
        grouped_vouchers = raw_vouchers
    else:
        by_num = {}
        for row_idx, r in enumerate(raw_vouchers, start=1):
            if not isinstance(r, dict):
                raise ValidationError({"rows": f"Dòng Excel thứ {row_idx}: Dữ liệu không đúng định dạng."})
            debit_val = r.get("debit_account") or r.get("debitAcc") or r.get("tk_no")
            credit_val = r.get("credit_account") or r.get("creditAcc") or r.get("tk_co")
            amt_val = r.get("amount") if "amount" in r else r.get("so_tien")
            if debit_val is None or credit_val is None or amt_val is None:
                raise ValidationError({
                    "rows": f"Dòng Excel thứ {row_idx}: Thiếu thông tin cột bắt buộc (TK Nợ, TK Có hoặc Số tiền)."
                })
            v_num = str(r.get("number") or r.get("voucher_no") or f"__ROW_{row_idx}").strip()
            if v_num not in by_num:
                by_num[v_num] = {
                    "number": None if v_num.startswith("__ROW_") else v_num,
                    "business_type": r.get("business_type") or r.get("businessType") or "OTHER",
                    "posting_date": r.get("posting_date") or r.get("postingDate"),
                    "document_date": r.get("document_date") or r.get("docDate"),
                    "due_date": r.get("due_date") or r.get("dueDate"),
                    "description": r.get("description") or r.get("desc") or "Nhập chứng từ nghiệp vụ khác từ Excel",
                    "accounting_lines": [],
                }
            by_num[v_num]["accounting_lines"].append({
                "description": r.get("line_description") or r.get("description") or r.get("desc") or "",
                "debit_account": debit_val,
                "credit_account": credit_val,
                "amount": amt_val,
                "debit_object_code": r.get("debit_object_code") or r.get("debitObject") or "",
                "credit_object_code": r.get("credit_object_code") or r.get("creditObject") or "",
                "loan_contract": r.get("loan_contract") or r.get("loanContract") or "",
                "expense_item": r.get("expense_item") or r.get("expenseItem") or "",
                "department": r.get("department") or "",
                "cost_object": r.get("cost_object") or r.get("costObject") or "",
                "operation": r.get("operation") or "",
            })
        grouped_vouchers = list(by_num.values())

    created_vouchers = []
    row_errors = []
    for v_idx, v_data in enumerate(grouped_vouchers, start=1):
        try:
            with transaction.atomic():
                voucher, _ = create_general_business_voucher(company, v_data, request)
                created_vouchers.append(voucher)
        except ValidationError as exc:
            detail_msg = exc.detail if hasattr(exc, "detail") else str(exc)
            row_errors.append({"index": v_idx, "number": v_data.get("number"), "errors": detail_msg})

    if row_errors:
        raise ValidationError({
            "import_errors": row_errors,
            "message": f"Phát hiện {len(row_errors)} chứng từ/dòng không hợp lệ khi nhập Excel.",
        })

    return created_vouchers


