INELIGIBLE_SOURCE_STATUSES = {
    "CANCELLED",
    "CANCELED",
    "DELETED",
    "VOIDED",
    "REJECTED",
    "DRAFT_ONLY",
    "INELIGIBLE",
    "NOT_FOUND",
    "UNAPPROVED",
}


class SubledgerIngestionException(Exception):
    def __init__(self, code, message, field="detail"):
        super().__init__(message)
        self.code = code
        self.message = message
        self.field = field


def _parse_iso_date(raw_val, field_name="posting_date", default=None):
    if not raw_val:
        if default is not None:
            return default
        raise SubledgerIngestionException(
            "EF_08_INVALID_DATE",
            f"Trường ngày '{field_name}' không được để trống.",
            field=field_name,
        )
    if isinstance(raw_val, date):
        return raw_val
    s = str(raw_val).strip()
    if "/" in s:
        parts = s.split("/")
        if len(parts) == 3:
            try:
                return date(int(parts[2]), int(parts[1]), int(parts[0]))
            except Exception as exc:
                raise SubledgerIngestionException(
                    "EF_08_INVALID_DATE",
                    f"Ngày '{s}' ({field_name}) không đúng định dạng.",
                    field=field_name,
                ) from exc
    try:
        return date.fromisoformat(s[:10])
    except Exception as exc:
        raise SubledgerIngestionException(
            "EF_08_INVALID_DATE",
            f"Ngày '{s}' ({field_name}) không hợp lệ.",
            field=field_name,
        ) from exc


def _parse_decimal(raw_val, field_name="amount", allow_zero=False):
    if raw_val is None or str(raw_val).strip() == "":
        if allow_zero:
            return Decimal("0")
        raise SubledgerIngestionException(
            "EF_15_INVALID_AMOUNT",
            f"Số tiền '{field_name}' không được để trống.",
            field=field_name,
        )
    try:
        val = Decimal(str(raw_val).replace(",", "").strip())
    except Exception as exc:
        raise SubledgerIngestionException(
            "EF_15_INVALID_AMOUNT",
            f"Số tiền '{raw_val}' ({field_name}) không hợp lệ.",
            field=field_name,
        ) from exc
    if val < 0 or (not allow_zero and val <= 0):
        raise SubledgerIngestionException(
            "EF_15_INVALID_AMOUNT",
            f"Số tiền '{field_name}' phải lớn hơn {'hoặc bằng ' if allow_zero else ''}0.",
            field=field_name,
        )
    return val


def _resolve_voucher_currency(company, raw_currency=None):
    from master_data.models import Currency

    if raw_currency:
        cval = str(raw_currency).strip()
        cur = Currency.objects.filter(
            Q(id__iexact=cval) if len(cval) == 36 else Q(code__iexact=cval)
        ).first()
        if cur:
            return cur
    if getattr(company, "accounting_currency_id", None):
        return company.accounting_currency
    cur, _ = Currency.objects.get_or_create(code="VND", defaults={"name": "Đồng Việt Nam"})
    return cur


def _resolve_subledger_account(company, code_or_id, field_label="Tài khoản"):
    if not code_or_id:
        raise SubledgerIngestionException(
            "EF_10_ACCOUNT_MISSING",
            f"{field_label} không được để trống.",
            field="account",
        )
    val = str(code_or_id).strip()
    acc = models.Account.objects.filter(
        Q(id__iexact=val) if len(val) == 36 else Q(code__iexact=val),
        company=company,
    ).first()
    if not acc:
        acc = models.Account.objects.filter(company=company, code__startswith=val, is_postable=True).order_by("code").first()
    if not acc:
        raise SubledgerIngestionException(
            "EF_10_ACCOUNT_NOT_FOUND",
            f"{field_label} '{val}' không tồn tại trong hệ thống tài khoản doanh nghiệp.",
            field="account",
        )
    if acc.status != "ACTIVE":
        raise SubledgerIngestionException(
            "EF_11_ACCOUNT_INACTIVE",
            f"Tài khoản {acc.code} ({acc.name}) đã ngừng sử dụng, không được phép hạch toán.",
            field="account",
        )
    has_active_children = models.Account.objects.filter(
        company=company,
        parent=acc,
        status="ACTIVE",
    ).exists()
    if not acc.is_postable or has_active_children:
        raise SubledgerIngestionException(
            "EF_12_ACCOUNT_NOT_LEAF",
            f"Tài khoản {acc.code} ({acc.name}) là tài khoản tổng hợp hoặc không cho phép định khoản trực tiếp.",
            field="account",
        )
    return acc


def _resolve_subledger_dimensions(company, line_dict, header_dict, posting_date):
    from master_data.models import CostCenter, Party, Project, Warehouse
    from organization.models import Department

    # AF-06 & BR-GL-INT-18: Kế thừa thông tin đối tượng / chiều phân tích từ header chứng từ nguồn nếu dòng chưa chỉ định
    merged_dims = {}
    if isinstance(header_dict.get("dimensions"), dict):
        merged_dims.update(header_dict["dimensions"])
    if isinstance(line_dict.get("dimensions"), dict):
        merged_dims.update(line_dict["dimensions"])

    party_val = (
        line_dict.get("party")
        or line_dict.get("party_id")
        or line_dict.get("object_code")
        or header_dict.get("party")
        or header_dict.get("party_id")
        or header_dict.get("object_code")
    )
    party_obj = None
    if party_val:
        pval = str(party_val).strip()
        party_obj = Party.objects.filter(
            Q(id__iexact=pval) if len(pval) == 36 else (Q(code__iexact=pval) | Q(name__iexact=pval)),
            company=company,
        ).first()
        if not party_obj:
            raise SubledgerIngestionException(
                "EF_14_PARTY_INVALID",
                f"Đối tượng hạch toán '{pval}' không tồn tại hoặc không thuộc doanh nghiệp.",
                field="party",
            )
        if getattr(party_obj, "status", "ACTIVE") != "ACTIVE":
            raise SubledgerIngestionException(
                "EF_14_PARTY_INACTIVE",
                f"Đối tượng hạch toán '{party_obj.code}' đang ngừng hoạt động.",
                field="party",
            )

    dept_val = (
        line_dict.get("department")
        or line_dict.get("department_id")
        or header_dict.get("department")
        or header_dict.get("department_id")
    )
    dept_obj = None
    if dept_val:
        dval = str(dept_val).strip()
        dept_obj = Department.objects.filter(
            Q(id__iexact=dval) if len(dval) == 36 else (Q(code__iexact=dval) | Q(name__iexact=dval)),
            company=company,
        ).first()
        if not dept_obj:
            raise SubledgerIngestionException(
                "EF_14_DEPARTMENT_INVALID",
                f"Phòng ban/đơn vị '{dval}' không tồn tại hoặc không hợp lệ.",
                field="department",
            )
        if getattr(dept_obj, "status", "ACTIVE") != "ACTIVE":
            raise SubledgerIngestionException(
                "EF_14_DEPARTMENT_INACTIVE",
                f"Phòng ban/đơn vị '{dept_obj.code}' đã ngừng hoạt động.",
                field="department",
            )

    proj_val = (
        line_dict.get("project")
        or line_dict.get("project_id")
        or header_dict.get("project")
        or header_dict.get("project_id")
    )
    proj_obj = None
    if proj_val:
        prval = str(proj_val).strip()
        proj_obj = Project.objects.filter(
            Q(id__iexact=prval) if len(prval) == 36 else (Q(code__iexact=prval) | Q(name__iexact=prval)),
            company=company,
        ).first()
        if not proj_obj:
            raise SubledgerIngestionException(
                "EF_14_PROJECT_INVALID",
                f"Dự án/công trình '{prval}' không tồn tại hoặc không hợp lệ.",
                field="project",
            )
        if getattr(proj_obj, "status", "ACTIVE") != "ACTIVE":
            raise SubledgerIngestionException(
                "EF_14_PROJECT_INACTIVE",
                f"Dự án/công trình '{proj_obj.code}' không còn hiệu lực.",
                field="project",
            )

    cc_val = (
        line_dict.get("cost_center")
        or line_dict.get("cost_center_id")
        or line_dict.get("cost_object")
        or header_dict.get("cost_center")
        or header_dict.get("cost_center_id")
        or header_dict.get("cost_object")
    )
    cc_obj = None
    if cc_val:
        ccval = str(cc_val).strip()
        cc_obj = CostCenter.objects.filter(
            Q(id__iexact=ccval) if len(ccval) == 36 else (Q(code__iexact=ccval) | Q(name__iexact=ccval)),
            company=company,
        ).first()
        if not cc_obj:
            raise SubledgerIngestionException(
                "EF_14_COST_CENTER_INVALID",
                f"Đối tượng tập hợp chi phí '{ccval}' không tồn tại hoặc không hợp lệ.",
                field="cost_center",
            )
        if getattr(cc_obj, "status", "ACTIVE") != "ACTIVE":
            raise SubledgerIngestionException(
                "EF_14_COST_CENTER_INACTIVE",
                f"Đối tượng tập hợp chi phí '{cc_obj.code}' đã ngừng hoạt động.",
                field="cost_center",
            )

    wh_val = (
        line_dict.get("warehouse")
        or line_dict.get("warehouse_id")
        or header_dict.get("warehouse")
        or header_dict.get("warehouse_id")
    )
    wh_obj = None
    if wh_val:
        wval = str(wh_val).strip()
        wh_obj = Warehouse.objects.filter(
            Q(id__iexact=wval) if len(wval) == 36 else (Q(code__iexact=wval) | Q(name__iexact=wval)),
            company=company,
        ).first()
        if not wh_obj:
            raise SubledgerIngestionException(
                "EF_14_WAREHOUSE_INVALID",
                f"Kho '{wval}' không tồn tại hoặc không hợp lệ.",
                field="warehouse",
            )
        if getattr(wh_obj, "status", "ACTIVE") != "ACTIVE":
            raise SubledgerIngestionException(
                "EF_14_WAREHOUSE_INACTIVE",
                f"Kho '{wh_obj.code}' đã ngừng hoạt động.",
                field="warehouse",
            )

    for extra_key in ("bank_account", "bank_account_id", "statistical_code", "statistical_code_id", "expense_item", "contract", "employee_id", "loan_contract"):
        val = line_dict.get(extra_key) or header_dict.get(extra_key)
        if val and extra_key not in merged_dims:
            merged_dims[extra_key] = str(val).strip()

    stat_val = merged_dims.get("statistical_code_id") or merged_dims.get("statistical_code")
    if stat_val:
        from django.core.exceptions import ValidationError as DjangoValidationError
        from master_data.statistical_code_services import validate_statistical_code_selection
        try:
            validate_statistical_code_selection(
                company=company,
                code_or_id=stat_val,
                transaction_date=posting_date,
            )
        except DjangoValidationError as exc:
            msg = exc.messages[0] if hasattr(exc, "messages") else str(exc)
            raise SubledgerIngestionException("EF_14_STATISTICAL_CODE_INVALID", msg, field="statistical_code") from exc

    return {
        "party": party_obj,
        "department": dept_obj,
        "project": proj_obj,
        "cost_center": cc_obj,
        "warehouse": wh_obj,
        "dimensions": merged_dims,
    }


def _assert_account_required_dimensions(account, resolved_dims):
    party_obj = resolved_dims["party"]
    proj_obj = resolved_dims["project"]
    cc_obj = resolved_dims["cost_center"]
    wh_obj = resolved_dims["warehouse"]
    dims = resolved_dims["dimensions"] or {}

    dim_reqs = account.dimension_requirements or {}
    for dim_name, req_level in dim_reqs.items():
        if req_level in ("REQUIRED", models.DimensionRequirementLevel.REQUIRED):
            if dim_name in ("CUSTOMER", "SUPPLIER") and not party_obj:
                raise SubledgerIngestionException(
                    "EF_13_MISSING_REQUIRED_DIMENSION",
                    f"Tài khoản {account.code} bắt buộc nhập đối tượng {dim_name} (Party).",
                    field="party",
                )
            if dim_name == "EMPLOYEE" and not (party_obj or dims.get("employee_id")):
                raise SubledgerIngestionException(
                    "EF_13_MISSING_REQUIRED_DIMENSION",
                    f"Tài khoản {account.code} bắt buộc nhập nhân viên (Employee).",
                    field="employee_id",
                )
            if dim_name == "PROJECT" and not proj_obj:
                raise SubledgerIngestionException(
                    "EF_13_MISSING_REQUIRED_DIMENSION",
                    f"Tài khoản {account.code} bắt buộc nhập dự án/công trình (Project).",
                    field="project",
                )
            if dim_name == "COST_CENTER" and not cc_obj:
                raise SubledgerIngestionException(
                    "EF_13_MISSING_REQUIRED_DIMENSION",
                    f"Tài khoản {account.code} bắt buộc nhập đối tượng tập hợp chi phí (Cost Center).",
                    field="cost_center",
                )
            if dim_name == "WAREHOUSE" and not wh_obj:
                raise SubledgerIngestionException(
                    "EF_13_MISSING_REQUIRED_DIMENSION",
                    f"Tài khoản {account.code} bắt buộc nhập kho (Warehouse).",
                    field="warehouse",
                )
            if dim_name == "BANK_ACCOUNT" and not (dims.get("bank_account") or dims.get("bank_account_id")):
                raise SubledgerIngestionException(
                    "EF_13_MISSING_REQUIRED_DIMENSION",
                    f"Tài khoản {account.code} bắt buộc nhập tài khoản ngân hàng (Bank Account).",
                    field="bank_account",
                )
            if dim_name == "STATISTICAL_CODE" and not (dims.get("statistical_code") or dims.get("statistical_code_id")):
                raise SubledgerIngestionException(
                    "EF_13_MISSING_REQUIRED_DIMENSION",
                    f"Tài khoản {account.code} bắt buộc nhập mã thống kê (Statistical Code).",
                    field="statistical_code",
                )

    employee_tracked = dim_reqs.get("EMPLOYEE") == "REQUIRED" and dims.get("employee_id")
    if account.requires_party and not employee_tracked and not party_obj:
        raise SubledgerIngestionException(
            "EF_13_MISSING_REQUIRED_DIMENSION",
            f"Tài khoản {account.code} bắt buộc nhập đối tượng (Party).",
            field="party",
        )
    if account.requires_project and not proj_obj:
        raise SubledgerIngestionException(
            "EF_13_MISSING_REQUIRED_DIMENSION",
            f"Tài khoản {account.code} bắt buộc nhập dự án (Project).",
            field="project",
        )
    if account.requires_cost_center and not cc_obj:
        raise SubledgerIngestionException(
            "EF_13_MISSING_REQUIRED_DIMENSION",
            f"Tài khoản {account.code} bắt buộc nhập trung tâm chi phí (Cost Center).",
            field="cost_center",
        )
    if account.requires_warehouse and not wh_obj:
        raise SubledgerIngestionException(
            "EF_13_MISSING_REQUIRED_DIMENSION",
            f"Tài khoản {account.code} bắt buộc nhập kho (Warehouse).",
            field="warehouse",
        )


def _normalize_entry_group_lines(
    company,
    group_payload,
    header_payload,
    source_module,
    source_business_type,
    posting_date,
    header_currency,
    header_exchange_rate,
):
    """
    AF-01, AF-02, AF-03, AF-05, EF-06, EF-07, EF-15, EF-16, EF-17:
    Chuẩn hóa danh sách dòng Nợ/Có cho một bút toán GL được sinh từ phân hệ nguồn.
    Hỗ trợ 3 dạng dữ liệu đầu vào:
    1. lines: Danh sách các dòng đơn lẻ {account, debit, credit, ...}
    2. accounting_lines / paired_lines: Danh sách cặp {debit_account, credit_account, amount, ...}
    3. Không truyền tài khoản (AF-02): Tự động suy diễn từ SubledgerPostingRule hoặc DEFAULT_SUBLEDGER_POSTING_RULES
       dựa trên {amount / pre_tax_amount, tax_amount / vat_amount}.
    """
    raw_lines = group_payload.get("lines")
    paired_lines = group_payload.get("accounting_lines") or group_payload.get("paired_lines")
    used_rule = None

    expanded_raw = []
    if isinstance(raw_lines, list) and len(raw_lines) > 0:
        # Kiểm tra xem raw_lines là dòng đơn (account + debit/credit) hay dòng cặp (debit_account + credit_account + amount)
        for item in raw_lines:
            if not isinstance(item, dict):
                raise SubledgerIngestionException("EF_15_INVALID_LINE_FORMAT", "Dòng hạch toán không đúng định dạng.", field="lines")
            if ("debit_account" in item or "debitAcc" in item) and ("credit_account" in item or "creditAcc" in item):
                amt = _parse_decimal(item.get("amount"), field_name="amount", allow_zero=False)
                f_amt = _parse_decimal(item.get("foreign_amount", 0), field_name="foreign_amount", allow_zero=True)
                desc = str(item.get("description") or group_payload.get("description") or header_payload.get("description") or "").strip()
                expanded_raw.append({
                    **item,
                    "account": item.get("debit_account") or item.get("debitAcc"),
                    "debit": amt,
                    "credit": Decimal("0"),
                    "foreign_amount": f_amt,
                    "description": desc,
                })
                expanded_raw.append({
                    **item,
                    "account": item.get("credit_account") or item.get("creditAcc"),
                    "debit": Decimal("0"),
                    "credit": amt,
                    "foreign_amount": f_amt,
                    "description": desc,
                })
            else:
                expanded_raw.append(item)
    elif isinstance(paired_lines, list) and len(paired_lines) > 0:
        for item in paired_lines:
            if not isinstance(item, dict):
                raise SubledgerIngestionException("EF_15_INVALID_LINE_FORMAT", "Dòng định khoản không đúng định dạng.", field="accounting_lines")
            amt = _parse_decimal(item.get("amount"), field_name="amount", allow_zero=False)
            f_amt = _parse_decimal(item.get("foreign_amount", 0), field_name="foreign_amount", allow_zero=True)
            desc = str(item.get("description") or group_payload.get("description") or header_payload.get("description") or "").strip()
            expanded_raw.append({
                **item,
                "account": item.get("debit_account") or item.get("debitAcc"),
                "debit": amt,
                "credit": Decimal("0"),
                "foreign_amount": f_amt,
                "description": desc,
            })
            expanded_raw.append({
                **item,
                "account": item.get("credit_account") or item.get("creditAcc"),
                "debit": Decimal("0"),
                "credit": amt,
                "foreign_amount": f_amt,
                "description": desc,
            })
    else:
        # AF-02: Phân hệ nguồn chỉ gửi dữ liệu nghiệp vụ, GL tự xác định tài khoản theo quy tắc hạch toán
        btype = str(group_payload.get("source_business_type") or source_business_type or "").strip().upper()
        used_rule = models.SubledgerPostingRule.objects.filter(
            company=company,
            source_module=source_module,
            source_business_type__iexact=btype,
        ).select_related("debit_account", "credit_account", "tax_account").first()

        if used_rule and not used_rule.is_active:
            raise SubledgerIngestionException(
                "EF_06_RULE_INACTIVE",
                f"Quy tắc hạch toán '{used_rule.name}' ({source_module}/{btype}) đang ngừng hiệu lực.",
                field="source_business_type",
            )

        debit_acc_ref = None
        credit_acc_ref = None
        tax_acc_ref = None
        if used_rule:
            debit_acc_ref = used_rule.debit_account.code
            credit_acc_ref = used_rule.credit_account.code
            tax_acc_ref = used_rule.tax_account.code if used_rule.tax_account else None
        elif header_payload.get("use_default_rule", True):
            fallback = DEFAULT_SUBLEDGER_POSTING_RULES.get((source_module, btype))
            if fallback:
                debit_acc_ref = fallback["debit_code"]
                credit_acc_ref = fallback["credit_code"]
                tax_acc_ref = fallback.get("tax_code") or None

        if not debit_acc_ref or not credit_acc_ref:
            raise SubledgerIngestionException(
                "EF_06_MISSING_POSTING_RULE",
                f"Chưa cấu hình quy tắc hạch toán cho phân hệ '{source_module}' - loại nghiệp vụ '{btype}'.",
                field="source_business_type",
            )

        # Kiểm tra tài khoản trong quy tắc có tồn tại không (EF-07)
        try:
            _resolve_subledger_account(company, debit_acc_ref, "Tài khoản Nợ theo quy tắc")
            _resolve_subledger_account(company, credit_acc_ref, "Tài khoản Có theo quy tắc")
            if tax_acc_ref and _parse_decimal(group_payload.get("tax_amount") or header_payload.get("tax_amount") or 0, allow_zero=True) > 0:
                _resolve_subledger_account(company, tax_acc_ref, "Tài khoản Thuế theo quy tắc")
        except SubledgerIngestionException as exc:
            if exc.code == "EF_10_ACCOUNT_NOT_FOUND":
                raise SubledgerIngestionException(
                    "EF_07_RULE_ACCOUNT_NOT_FOUND",
                    f"Quy tắc hạch toán ({source_module}/{btype}) tham chiếu đến tài khoản không tồn tại: {exc.message}",
                    field="account",
                ) from exc
            raise

        base_amount = _parse_decimal(
            group_payload.get("amount")
            if group_payload.get("amount") is not None
            else (header_payload.get("amount") or header_payload.get("pre_tax_amount") or 0),
            field_name="amount",
            allow_zero=False,
        )
        tax_amount = _parse_decimal(
            group_payload.get("tax_amount")
            if group_payload.get("tax_amount") is not None
            else (header_payload.get("tax_amount") or header_payload.get("vat_amount") or 0),
            field_name="tax_amount",
            allow_zero=True,
        )
        foreign_base = _parse_decimal(
            group_payload.get("foreign_amount")
            if group_payload.get("foreign_amount") is not None
            else (header_payload.get("foreign_amount") or 0),
            field_name="foreign_amount",
            allow_zero=True,
        )
        desc = str(
            group_payload.get("description")
            or header_payload.get("description")
            or (used_rule.description_template if used_rule and used_rule.description_template else f"Hạch toán {source_module}/{btype}")
        ).strip()

        if tax_amount > 0 and tax_acc_ref:
            # Nếu là bán hàng (SAL): Nợ 131 (base + tax) / Có 511 (base) + Có 33311 (tax)
            if source_module == "SAL":
                expanded_raw.append({
                    "account": debit_acc_ref,
                    "debit": base_amount + tax_amount,
                    "credit": Decimal("0"),
                    "foreign_amount": foreign_base,
                    "description": desc,
                })
                expanded_raw.append({
                    "account": credit_acc_ref,
                    "debit": Decimal("0"),
                    "credit": base_amount,
                    "foreign_amount": Decimal("0"),
                    "description": desc,
                })
                expanded_raw.append({
                    "account": tax_acc_ref,
                    "debit": Decimal("0"),
                    "credit": tax_amount,
                    "foreign_amount": Decimal("0"),
                    "description": f"Thuế GTGT đầu ra - {desc}",
                })
            else:
                # Mua hàng / chi phí (PUR, AP, ...): Nợ 156/642 (base) + Nợ 1331 (tax) / Có 331 (base + tax)
                expanded_raw.append({
                    "account": debit_acc_ref,
                    "debit": base_amount,
                    "credit": Decimal("0"),
                    "foreign_amount": Decimal("0"),
                    "description": desc,
                })
                expanded_raw.append({
                    "account": tax_acc_ref,
                    "debit": tax_amount,
                    "credit": Decimal("0"),
                    "foreign_amount": Decimal("0"),
                    "description": f"Thuế GTGT đầu vào - {desc}",
                })
                expanded_raw.append({
                    "account": credit_acc_ref,
                    "debit": Decimal("0"),
                    "credit": base_amount + tax_amount,
                    "foreign_amount": foreign_base,
                    "description": desc,
                })
        else:
            expanded_raw.append({
                "account": debit_acc_ref,
                "debit": base_amount,
                "credit": Decimal("0"),
                "foreign_amount": foreign_base,
                "description": desc,
            })
            expanded_raw.append({
                "account": credit_acc_ref,
                "debit": Decimal("0"),
                "credit": base_amount,
                "foreign_amount": foreign_base,
                "description": desc,
            })

    if len(expanded_raw) < 2:
        raise SubledgerIngestionException(
            "EF_15_INSUFFICIENT_LINES",
            "Bút toán tiếp nhận phải có tối thiểu một dòng Nợ và một dòng Có.",
            field="lines",
        )

    is_foreign = header_currency.code.upper() != "VND"
    if is_foreign and header_exchange_rate <= 0:
        raise SubledgerIngestionException(
            "EF_16_INVALID_EXCHANGE_RATE",
            f"Nghiệp vụ ngoại tệ ({header_currency.code}) bắt buộc có tỷ giá hối đoái lớn hơn 0.",
            field="exchange_rate",
        )

    validated_lines = []
    total_debit = Decimal("0")
    total_credit = Decimal("0")

    for idx, line_item in enumerate(expanded_raw, start=1):
        acc = _resolve_subledger_account(company, line_item.get("account"), f"Dòng {idx} - Tài khoản")
        try:
            debit = Decimal(str(line_item.get("debit") or 0))
            credit = Decimal(str(line_item.get("credit") or 0))
        except Exception as exc:
            raise SubledgerIngestionException(
                "EF_15_INVALID_AMOUNT",
                f"Dòng {idx}: Số tiền Nợ/Có không hợp lệ.",
                field="lines",
            ) from exc

        if debit < 0 or credit < 0 or (debit == 0 and credit == 0) or (debit > 0 and credit > 0):
            raise SubledgerIngestionException(
                "EF_15_INVALID_LINE_AMOUNT",
                f"Dòng {idx} (TK {acc.code}): Số tiền hạch toán phải lớn hơn 0 ở đúng một phía Nợ hoặc Có.",
                field="lines",
            )

        line_rate = header_exchange_rate
        if line_item.get("exchange_rate") is not None:
            try:
                line_rate = Decimal(str(line_item["exchange_rate"]))
            except Exception as exc:
                raise SubledgerIngestionException("EF_16_INVALID_EXCHANGE_RATE", f"Dòng {idx}: Tỷ giá không hợp lệ.", field="exchange_rate") from exc
            if line_rate <= 0:
                raise SubledgerIngestionException("EF_16_INVALID_EXCHANGE_RATE", f"Dòng {idx}: Tỷ giá phải lớn hơn 0.", field="exchange_rate")

        foreign_amt = Decimal("0")
        if line_item.get("foreign_amount") is not None and str(line_item.get("foreign_amount")) != "":
            try:
                foreign_amt = Decimal(str(line_item["foreign_amount"]))
            except Exception as exc:
                raise SubledgerIngestionException("EF_16_INVALID_FOREIGN_AMOUNT", f"Dòng {idx}: Số tiền nguyên tệ không hợp lệ.", field="foreign_amount") from exc
            if foreign_amt < 0:
                raise SubledgerIngestionException("EF_16_INVALID_FOREIGN_AMOUNT", f"Dòng {idx}: Số tiền nguyên tệ không được âm.", field="foreign_amount")

        # AF-05, EF-16, BR-GL-INT-24, BR-GL-INT-25: Kiểm tra quy đổi ngoại tệ
        converted_side = debit if debit > 0 else credit
        if is_foreign:
            if foreign_amt <= 0:
                foreign_amt = (converted_side / line_rate).quantize(Decimal("0.0001"))
            else:
                expected_converted = (foreign_amt * line_rate).quantize(Decimal("0.0001"))
                tolerance = Decimal(str(header_payload.get("fx_rounding_tolerance") or "5"))
                if abs(expected_converted - converted_side) > tolerance:
                    raise SubledgerIngestionException(
                        "EF_16_FX_CONVERSION_MISMATCH",
                        (
                            f"Dòng {idx} (TK {acc.code}): Số tiền quy đổi ({converted_side}) chênh lệch quá ngưỡng cho phép "
                            f"so với Nguyên tệ ({foreign_amt}) x Tỷ giá ({line_rate}) = {expected_converted}."
                        ),
                        field="foreign_amount",
                    )

        resolved_dims = _resolve_subledger_dimensions(company, line_item, header_payload, posting_date)
        _assert_account_required_dimensions(acc, resolved_dims)

        total_debit += debit
        total_credit += credit
        validated_lines.append({
            "line_no": idx,
            "account": acc,
            "account_code": acc.code,
            "account_name": acc.name,
            "description": str(line_item.get("description") or header_payload.get("description") or "").strip(),
            "debit": debit,
            "credit": credit,
            "currency": header_currency,
            "foreign_amount": foreign_amt,
            "exchange_rate": line_rate,
            "party": resolved_dims["party"],
            "department": resolved_dims["department"],
            "project": resolved_dims["project"],
            "cost_center": resolved_dims["cost_center"],
            "warehouse": resolved_dims["warehouse"],
            "dimensions": resolved_dims["dimensions"],
        })

    if not any(l["debit"] > 0 for l in validated_lines) or not any(l["credit"] > 0 for l in validated_lines):
        raise SubledgerIngestionException(
            "EF_15_MISSING_DEBIT_OR_CREDIT",
            "Bút toán phải có ít nhất một dòng Nợ > 0 và một dòng Có > 0.",
            field="lines",
        )

    if total_debit <= 0 or total_debit != total_credit:
        raise SubledgerIngestionException(
            "EF_17_UNBALANCED_ENTRY",
            f"Bút toán không cân đối: Tổng Nợ ({total_debit}) khác Tổng Có ({total_credit}).",
            field="total_debit",
        )

    return validated_lines, total_debit, total_credit, used_rule


def _check_subledger_period_and_lock(company, source_module, posting_date):
    period = models.AccountingPeriod.objects.filter(
        company=company,
        start_date__lte=posting_date,
        end_date__gte=posting_date,
    ).first()
    if not period:
        raise SubledgerIngestionException(
            "EF_08_PERIOD_NOT_FOUND",
            f"Không xác định được kỳ kế toán cho ngày hạch toán {posting_date.isoformat()}.",
            field="posting_date",
        )

    is_locked = False
    lock_reason = ""
    if period.status == "CLOSED":
        is_locked = True
        lock_reason = f"Kỳ kế toán {period.code} đã khóa/đóng sổ (CLOSED)."
    else:
        lock_code = journal_lock_code(
            type(
                "DummyEntry",
                (),
                {
                    "entry_type": "SUBLEDGER",
                    "source_module": source_module,
                    "source_event_id": "",
                    "source_entity_type": "",
                },
            )()
        )
        try:
            assert_not_locked(company, lock_code, posting_date)
        except ValidationError as exc:
            is_locked = True
            lock_reason = str(exc.detail[0] if isinstance(exc.detail, list) else exc.detail)

    return period, is_locked, lock_reason


def _generate_subledger_journal_number(company, source_module, source_document_number, group_idx=1):
    base_prefix = f"SL-{source_module}-{source_document_number}"
    if group_idx > 1:
        base_prefix = f"{base_prefix}-G{group_idx}"
    candidate = base_prefix[:50]
    suffix = 1
    while models.JournalEntry.objects.filter(company=company, number=candidate).exists():
        suffix += 1
        candidate = f"{base_prefix[:44]}-{suffix}"
    return candidate


def _persist_failed_ingestion(
    company,
    payload,
    actor_user,
    error_code,
    error_message,
    existing_ingestion=None,
):
    """
    BR-GL-INT-42, BR-GL-INT-43: Lưu nhận diện bản ghi tiếp nhận lỗi (status=ERROR)
    để Kế toán tổng hợp tra cứu nguyên nhân và thực hiện Thử lại (Retry) sau khi xử lý.
    """
    source_event_id = str(payload.get("source_event_id") or "").strip()
    source_module = str(payload.get("source_module") or "GL").strip().upper()
    if source_module not in models.SubledgerSourceModule.values:
        source_module = models.SubledgerSourceModule.GL
    if not company or not source_event_id:
        return None

    posting_date = _parse_iso_date(payload.get("posting_date"), "posting_date", default=timezone.localdate())
    document_date = _parse_iso_date(payload.get("document_date"), "document_date", default=posting_date)
    period = models.AccountingPeriod.objects.filter(
        company=company,
        start_date__lte=posting_date,
        end_date__gte=posting_date,
    ).first()
    currency = _resolve_voucher_currency(company, payload.get("currency"))

    with transaction.atomic():
        target = existing_ingestion or models.SubledgerJournalIngestion.objects.filter(
            company=company,
            source_event_id=source_event_id,
        ).first()
        if target and target.status in (
            models.SubledgerIngestionStatus.POSTED,
            models.SubledgerIngestionStatus.UNPOSTED,
            models.SubledgerIngestionStatus.REVERSED,
        ):
            return target

        defaults = {
            "source_module": source_module,
            "source_business_type": str(payload.get("source_business_type") or "GENERAL").strip()[:80],
            "source_document_type": str(payload.get("source_document_type") or source_module).strip()[:80],
            "source_document_id": str(payload.get("source_document_id") or "UNKNOWN").strip()[:120],
            "source_document_number": str(payload.get("source_document_number") or "UNKNOWN").strip()[:80],
            "source_document_status": str(payload.get("source_document_status") or "ELIGIBLE").strip().upper()[:40],
            "document_date": document_date,
            "posting_date": posting_date,
            "period": period,
            "description": str(payload.get("description") or "").strip()[:500],
            "currency": currency,
            "exchange_rate": Decimal("1"),
            "posting_mode": str(payload.get("posting_mode") or models.SubledgerPostingMode.AUTO_POST).strip().upper()[:20],
            "status": models.SubledgerIngestionStatus.ERROR,
            "error_code": str(error_code)[:80],
            "error_message": str(error_message),
            "raw_payload": payload if isinstance(payload, dict) else {},
            "updated_by": actor_user,
        }
        if target:
            for k, v in defaults.items():
                setattr(target, k, v)
            target.retry_count += 1
            target.version += 1
            target.save()
            return target
        else:
            defaults["created_by"] = actor_user
            return models.SubledgerJournalIngestion.objects.create(
                company=company,
                source_event_id=source_event_id,
                **defaults,
            )


def ingest_subledger_journal_event(company, payload, request, existing_ingestion=None):
    """
    UC-GL-04 – Tiếp nhận bút toán từ các phân hệ (Steps 1–36, AF-01..AF-14, EF-01..EF-27, BR-GL-INT-01..65).
    Trả về tuple: (ingestion, created_new)
    """
    actor_user = actor(request)

    # EF-03, BR-GL-INT-09: Kiểm tra doanh nghiệp nguồn tồn tại và đang hoạt động
    if not company or getattr(company, "status", "ACTIVE") != "ACTIVE":
        raise ValidationError({"company": "EF-03: Doanh nghiệp nguồn không tồn tại hoặc không ở trạng thái hoạt động."})

    # EF-04, BR-GL-INT-10: Kiểm tra đồng nhất phạm vi doanh nghiệp giữa phân hệ nguồn và GL
    payload_company_id = payload.get("company_id") or payload.get("source_company_id") or payload.get("company")
    if payload_company_id and str(payload_company_id).strip() != str(company.id):
        raise ValidationError({
            "company": "EF-04: Chứng từ nguồn không thuộc cùng phạm vi doanh nghiệp với Sổ cái (GL)."
        })

    # EF-05, BR-GL-INT-04..08: Kiểm tra định danh sự kiện hạch toán (source_event_id)
    source_event_id = str(payload.get("source_event_id") or payload.get("event_id") or "").strip()
    if not source_event_id:
        raise ValidationError({
            "source_event_id": "EF-05: Thiếu mã sự kiện hạch toán nguồn (source_event_id) để chống tiếp nhận trùng."
        })

    # AF-10, EF-18, EF-25, BR-GL-INT-06..08: Kiểm tra Idempotency theo (company, source_event_id)
    existing_by_event = existing_ingestion or models.SubledgerJournalIngestion.objects.select_related(
        "primary_journal_entry", "period", "currency", "posting_rule"
    ).prefetch_related("journal_entries__lines__account").filter(
        company=company,
        source_event_id=source_event_id,
    ).first()
    if existing_by_event and existing_by_event.status in (
        models.SubledgerIngestionStatus.POSTED,
        models.SubledgerIngestionStatus.UNPOSTED,
        models.SubledgerIngestionStatus.REVERSED,
    ):
        return existing_by_event, False

    try:
        with transaction.atomic():
            source_module = str(payload.get("source_module") or "").strip().upper()
            if source_module not in models.SubledgerSourceModule.values:
                raise SubledgerIngestionException(
                    "EF_01_INVALID_SOURCE_MODULE",
                    f"Phân hệ nguồn '{source_module}' không hợp lệ. Các phân hệ hỗ trợ: {', '.join(models.SubledgerSourceModule.values)}.",
                    field="source_module",
                )

            source_document_id = str(payload.get("source_document_id") or "").strip()
            source_document_number = str(payload.get("source_document_number") or "").strip()
            source_document_type = str(payload.get("source_document_type") or source_module).strip()
            source_business_type = str(payload.get("source_business_type") or "").strip().upper()

            if not source_document_id or not source_document_number:
                raise SubledgerIngestionException(
                    "EF_01_SOURCE_DOCUMENT_MISSING",
                    "Thiếu định danh chứng từ nguồn (source_document_id / source_document_number).",
                    field="source_document_id",
                )
            if not source_business_type:
                raise SubledgerIngestionException(
                    "EF_01_SOURCE_BUSINESS_TYPE_MISSING",
                    "Thiếu loại nghiệp vụ nguồn (source_business_type).",
                    field="source_business_type",
                )

            # EF-01, EF-02, BR-GL-INT-03, BR-GL-INT-64: Kiểm tra trạng thái chứng từ nguồn
            source_doc_status = str(payload.get("source_document_status") or "ELIGIBLE").strip().upper()
            if source_doc_status == "NOT_FOUND" or payload.get("source_document_exists") is False:
                raise SubledgerIngestionException(
                    "EF_01_SOURCE_DOCUMENT_NOT_FOUND",
                    f"Chứng từ nguồn '{source_document_number}' ({source_document_id}) không tồn tại.",
                    field="source_document_status",
                )
            if source_doc_status in INELIGIBLE_SOURCE_STATUSES:
                raise SubledgerIngestionException(
                    "EF_02_SOURCE_DOCUMENT_INELIGIBLE",
                    f"Chứng từ nguồn '{source_document_number}' đang ở trạng thái '{source_doc_status}', không đủ điều kiện phát sinh bút toán GL.",
                    field="source_document_status",
                )

            # EF-18, AF-12, EF-26, BR-GL-INT-06, BR-GL-INT-47: Kiểm tra trùng nghiệp vụ nguồn khi đã có bút toán hiệu lực
            if not payload.get("allow_multiple_events", False):
                duplicate_doc_ing = models.SubledgerJournalIngestion.objects.filter(
                    company=company,
                    source_module=source_module,
                    source_document_id=source_document_id,
                    source_business_type=source_business_type,
                    status__in=(
                        models.SubledgerIngestionStatus.POSTED,
                        models.SubledgerIngestionStatus.UNPOSTED,
                    ),
                ).exclude(source_event_id=source_event_id).first()
                if duplicate_doc_ing:
                    if duplicate_doc_ing.status == models.SubledgerIngestionStatus.POSTED:
                        raise SubledgerIngestionException(
                            "EF_18_DUPLICATE_POSTED_SOURCE",
                            (
                                f"Chứng từ nguồn '{source_document_number}' ({source_module}/{source_business_type}) "
                                f"đã có bút toán GL đã ghi sổ ({duplicate_doc_ing.primary_journal_entry.number if duplicate_doc_ing.primary_journal_entry else duplicate_doc_ing.source_event_id}). "
                                "Không được phép ghi đè hoặc tiếp nhận trùng; vui lòng thực hiện nghiệp vụ đảo/điều chỉnh."
                            ),
                            field="source_document_id",
                        )
                    raise SubledgerIngestionException(
                        "EF_18_DUPLICATE_ACTIVE_SOURCE",
                        (
                            f"Chứng từ nguồn '{source_document_number}' ({source_module}/{source_business_type}) "
                            "đã được tiếp nhận ở trạng thái chưa ghi sổ. Hãy sử dụng chức năng đồng bộ/cập nhật bút toán chưa ghi sổ (AF-13)."
                        ),
                        field="source_document_id",
                    )

            posting_date = _parse_iso_date(payload.get("posting_date"), "posting_date", default=timezone.localdate())
            document_date = _parse_iso_date(payload.get("document_date"), "document_date", default=posting_date)

            # EF-08, EF-09, AF-11, BR-GL-INT-27..29: Kiểm tra kỳ kế toán và khóa sổ
            period, is_locked, lock_reason = _check_subledger_period_and_lock(company, source_module, posting_date)

            requested_mode = str(payload.get("posting_mode") or "").strip().upper()
            if requested_mode and requested_mode not in models.SubledgerPostingMode.values:
                raise SubledgerIngestionException(
                    "EF_20_INVALID_POSTING_MODE",
                    f"Chế độ hạch toán '{requested_mode}' không hợp lệ.",
                    field="posting_mode",
                )

            allow_unposted_in_locked = bool(payload.get("allow_unposted_in_locked_period", False))
            if is_locked:
                if allow_unposted_in_locked and period.status == "OPEN":
                    # AF-11: Cho phép giữ ở trạng thái UNPOSTED nhưng tuyệt đối không AUTO_POST vào kỳ khóa
                    requested_mode = models.SubledgerPostingMode.UNPOSTED
                else:
                    raise SubledgerIngestionException(
                        "EF_09_PERIOD_LOCKED",
                        f"Kỳ kế toán cho ngày {posting_date.isoformat()} đang bị khóa: {lock_reason}",
                        field="posting_date",
                    )

            currency = _resolve_voucher_currency(company, payload.get("currency"))
            try:
                exchange_rate = Decimal(str(payload.get("exchange_rate") if payload.get("exchange_rate") is not None else 1))
            except Exception as exc:
                raise SubledgerIngestionException("EF_16_INVALID_EXCHANGE_RATE", "Tỷ giá không hợp lệ.", field="exchange_rate") from exc
            if exchange_rate <= 0:
                raise SubledgerIngestionException("EF_16_INVALID_EXCHANGE_RATE", "Tỷ giá hối đoái phải lớn hơn 0.", field="exchange_rate")

            # AF-04, BR-GL-INT-23: Hỗ trợ một chứng từ nguồn sinh một hoặc nhiều nhóm bút toán GL (entry_groups)
            raw_groups = payload.get("entry_groups")
            if not isinstance(raw_groups, list) or len(raw_groups) == 0:
                raw_groups = [payload]

            normalized_groups = []
            overall_debit = Decimal("0")
            overall_credit = Decimal("0")
            primary_rule = None

            for g_idx, g_payload in enumerate(raw_groups, start=1):
                if not isinstance(g_payload, dict):
                    raise SubledgerIngestionException("EF_15_INVALID_GROUP", f"Nhóm bút toán thứ {g_idx} không hợp lệ.", field="entry_groups")
                g_lines, g_debit, g_credit, g_rule = _normalize_entry_group_lines(
                    company=company,
                    group_payload=g_payload,
                    header_payload=payload,
                    source_module=source_module,
                    source_business_type=g_payload.get("source_business_type") or source_business_type,
                    posting_date=posting_date,
                    header_currency=currency,
                    header_exchange_rate=exchange_rate,
                )
                if g_rule and not primary_rule:
                    primary_rule = g_rule
                overall_debit += g_debit
                overall_credit += g_credit
                normalized_groups.append({
                    "group_index": g_idx,
                    "description": str(
                        g_payload.get("description")
                        or payload.get("description")
                        or f"Tiếp nhận từ {source_module} - {source_document_number}"
                    ).strip()[:500],
                    "lines": g_lines,
                    "total_debit": g_debit,
                    "total_credit": g_credit,
                    "rule": g_rule,
                })

            effective_mode = requested_mode or (
                primary_rule.posting_mode if primary_rule else models.SubledgerPostingMode.AUTO_POST
            )
            if is_locked and effective_mode == models.SubledgerPostingMode.AUTO_POST:
                raise SubledgerIngestionException(
                    "EF_21_PERIOD_LOCKED_ON_AUTO_POST",
                    f"Không thể tự động ghi sổ vào kỳ kế toán đã khóa: {lock_reason}",
                    field="posting_date",
                )

            # Nếu đây là bản ghi retry từ ERROR hoặc tạo mới
            ingestion = existing_by_event
            resolved_summary = []
            for grp in normalized_groups:
                for ln in grp["lines"]:
                    resolved_summary.append({
                        "group_index": grp["group_index"],
                        "line_no": ln["line_no"],
                        "account_code": ln["account_code"],
                        "account_name": ln["account_name"],
                        "description": ln["description"],
                        "debit": str(ln["debit"]),
                        "credit": str(ln["credit"]),
                        "currency_code": ln["currency"].code,
                        "foreign_amount": str(ln["foreign_amount"]),
                        "exchange_rate": str(ln["exchange_rate"]),
                        "party_code": ln["party"].code if ln["party"] else "",
                        "department_code": ln["department"].code if ln["department"] else "",
                        "project_code": ln["project"].code if ln["project"] else "",
                        "cost_center_code": ln["cost_center"].code if ln["cost_center"] else "",
                        "warehouse_code": ln["warehouse"].code if ln["warehouse"] else "",
                    })

            description_text = str(
                payload.get("description") or f"Bút toán {source_module} - {source_document_number}"
            ).strip()[:500]

            if ingestion:
                ingestion.source_module = source_module
                ingestion.source_business_type = source_business_type
                ingestion.source_document_type = source_document_type
                ingestion.source_document_id = source_document_id
                ingestion.source_document_number = source_document_number
                ingestion.source_document_status = source_doc_status
                ingestion.document_date = document_date
                ingestion.posting_date = posting_date
                ingestion.period = period
                ingestion.description = description_text
                ingestion.currency = currency
                ingestion.exchange_rate = exchange_rate
                ingestion.total_debit = overall_debit
                ingestion.total_credit = overall_credit
                ingestion.posting_mode = effective_mode
                ingestion.posting_rule = primary_rule
                ingestion.raw_payload = payload
                ingestion.resolved_lines = resolved_summary
                ingestion.error_code = ""
                ingestion.error_message = ""
                ingestion.updated_by = actor_user
                ingestion.version += 1
                ingestion.save()
            else:
                ingestion = models.SubledgerJournalIngestion.objects.create(
                    company=company,
                    source_module=source_module,
                    source_business_type=source_business_type,
                    source_document_type=source_document_type,
                    source_document_id=source_document_id,
                    source_document_number=source_document_number,
                    source_document_status=source_doc_status,
                    source_event_id=source_event_id,
                    document_date=document_date,
                    posting_date=posting_date,
                    period=period,
                    description=description_text,
                    currency=currency,
                    exchange_rate=exchange_rate,
                    total_debit=overall_debit,
                    total_credit=overall_credit,
                    posting_mode=effective_mode,
                    status=models.SubledgerIngestionStatus.RECEIVED,
                    posting_rule=primary_rule,
                    raw_payload=payload,
                    resolved_lines=resolved_summary,
                    created_by=actor_user,
                    updated_by=actor_user,
                )

            import uuid

            created_entries = []
            for grp in normalized_groups:
                g_idx = grp["group_index"]
                event_key = source_event_id if g_idx == 1 else f"{source_event_id}#G{g_idx}"
                je_number = _generate_subledger_journal_number(
                    company, source_module, source_document_number, group_idx=g_idx
                )
                try:
                    resolved_entity_uuid = uuid.UUID(str(source_document_id))
                except (ValueError, TypeError):
                    resolved_entity_uuid = uuid.uuid5(
                        uuid.NAMESPACE_OID,
                        f"{company.id}:{source_module}:{source_document_id}",
                    )
                je_initial_status = (
                    "APPROVED"
                    if effective_mode == models.SubledgerPostingMode.AUTO_POST
                    else ("PENDING_APPROVAL" if effective_mode == models.SubledgerPostingMode.WORKFLOW else "DRAFT")
                )
                je = models.JournalEntry.objects.create(
                    company=company,
                    period=period,
                    number=je_number,
                    entry_type="SUBLEDGER",
                    posting_date=posting_date,
                    document_date=document_date,
                    description=grp["description"],
                    source_module=source_module,
                    source_entity_type=source_document_type,
                    source_entity_id=resolved_entity_uuid,
                    source_event_id=event_key,
                    status=je_initial_status,
                    total_debit=grp["total_debit"],
                    total_credit=grp["total_credit"],
                    workflow_snapshot={
                        "allow_creator_posting": True,
                        "source_module": source_module,
                        "source_business_type": source_business_type,
                        "source_document_number": source_document_number,
                        "posting_mode": effective_mode,
                    },
                    submitted_at=timezone.now() if effective_mode == models.SubledgerPostingMode.WORKFLOW else None,
                    approved_by=actor_user if effective_mode == models.SubledgerPostingMode.AUTO_POST else None,
                    approved_at=timezone.now() if effective_mode == models.SubledgerPostingMode.AUTO_POST else None,
                    created_by=actor_user,
                )
                for ln in grp["lines"]:
                    models.JournalLine.objects.create(
                        entry=je,
                        line_no=ln["line_no"],
                        account=ln["account"],
                        description=ln["description"],
                        debit=ln["debit"],
                        credit=ln["credit"],
                        currency=ln["currency"],
                        foreign_amount=ln["foreign_amount"],
                        exchange_rate=ln["exchange_rate"],
                        party=ln["party"],
                        department=ln["department"],
                        project=ln["project"],
                        cost_center=ln["cost_center"],
                        warehouse=ln["warehouse"],
                        dimensions=ln["dimensions"],
                    )
                if effective_mode == models.SubledgerPostingMode.WORKFLOW:
                    models.JournalApproval.objects.create(
                        company=company,
                        entry=je,
                        decision="SUBMITTED",
                        actor=actor_user,
                        comment="Chuyển phê duyệt tự động khi tiếp nhận từ phân hệ nguồn (AF-09).",
                    )
                elif effective_mode == models.SubledgerPostingMode.AUTO_POST:
                    # AF-07, EF-21, EF-22, EF-23, BR-GL-INT-35, BR-GL-INT-38: Tự động ghi sổ ngay trong transaction
                    je = post(je, request)
                created_entries.append(je)

            ingestion.primary_journal_entry = created_entries[0]
            ingestion.journal_entries.set(created_entries)
            ingestion.status = (
                models.SubledgerIngestionStatus.POSTED
                if effective_mode == models.SubledgerPostingMode.AUTO_POST
                else models.SubledgerIngestionStatus.UNPOSTED
            )
            ingestion.processed_at = timezone.now()

            # EF-24, BR-GL-INT-44, BR-GL-INT-45: Xử lý phản hồi trạng thái về phân hệ nguồn độc lập với bút toán GL
            if payload.get("simulate_callback_failure"):
                ingestion.callback_status = models.SubledgerCallbackStatus.FAILED
                ingestion.callback_error = "EF-24: Không thể gửi phản hồi trạng thái hạch toán về phân hệ nguồn (Mất kết nối callback)."
            elif payload.get("callback_required", True) is False:
                ingestion.callback_status = models.SubledgerCallbackStatus.NOT_REQUIRED
                ingestion.callback_error = ""
            else:
                ingestion.callback_status = models.SubledgerCallbackStatus.SYNCED
                ingestion.callback_error = ""

            ingestion.save(
                update_fields=(
                    "primary_journal_entry",
                    "status",
                    "processed_at",
                    "callback_status",
                    "callback_error",
                    "updated_at",
                )
            )

            audit(
                request,
                ingestion,
                "INGEST_SUBLEDGER",
                after={
                    "source_module": source_module,
                    "source_business_type": source_business_type,
                    "source_document_number": source_document_number,
                    "source_event_id": source_event_id,
                    "status": ingestion.status,
                    "journal_numbers": [e.number for e in created_entries],
                    "total_debit": str(overall_debit),
                    "total_credit": str(overall_credit),
                },
            )
            return ingestion, True

    except SubledgerIngestionException as exc:
        if payload.get("record_error_on_failure", True):
            err_ing = _persist_failed_ingestion(
                company=company,
                payload=payload,
                actor_user=actor_user,
                error_code=exc.code,
                error_message=exc.message,
                existing_ingestion=existing_by_event,
            )
            if payload.get("raise_on_error", True) is False and err_ing is not None:
                return err_ing, True
        raise ValidationError({
            exc.field: f"[{exc.code}] {exc.message}",
            "error_code": exc.code,
            "message": exc.message,
        }) from exc


def retry_subledger_journal_ingestion(ingestion, payload_override, request):
    """
    BR-GL-INT-43: Cho phép kế toán xử lý lại (Retry) yêu cầu tiếp nhận bút toán đang ở trạng thái ERROR
    sau khi đã khắc phục nguyên nhân (mở khóa kỳ, cấu hình quy tắc tài khoản, bổ sung chiều hạch toán...).
    """
    if ingestion.status in (
        models.SubledgerIngestionStatus.POSTED,
        models.SubledgerIngestionStatus.UNPOSTED,
    ):
        return ingestion, False
    if ingestion.status == models.SubledgerIngestionStatus.REVERSED:
        raise ValidationError({
            "status": "Bản ghi tiếp nhận đã bị đảo (REVERSED), không thể thử lại."
        })

    merged_payload = dict(ingestion.raw_payload or {})
    if isinstance(payload_override, dict):
        for k, v in payload_override.items():
            if v is not None:
                merged_payload[k] = v
    merged_payload["source_event_id"] = ingestion.source_event_id
    ingestion.retry_count += 1
    ingestion.save(update_fields=("retry_count", "updated_at"))
    return ingest_subledger_journal_event(
        company=ingestion.company,
        payload=merged_payload,
        request=request,
        existing_ingestion=ingestion,
    )


@transaction.atomic
def retry_subledger_source_callback(ingestion, request):
    """
    EF-24, BR-GL-INT-44, BR-GL-INT-45: Đồng bộ lại trạng thái phản hồi về phân hệ nguồn
    mà không tạo lại bút toán GL trùng lặp.
    """
    ingestion = models.SubledgerJournalIngestion.objects.select_for_update().get(pk=ingestion.pk)
    if ingestion.status not in (
        models.SubledgerIngestionStatus.POSTED,
        models.SubledgerIngestionStatus.UNPOSTED,
        models.SubledgerIngestionStatus.REVERSED,
    ):
        raise ValidationError({
            "status": "Chỉ đồng bộ lại phản hồi cho bản ghi đã tạo bút toán GL."
        })
    ingestion.callback_status = models.SubledgerCallbackStatus.SYNCED
    ingestion.callback_error = ""
    ingestion.updated_by = actor(request)
    ingestion.save(update_fields=("callback_status", "callback_error", "updated_by", "updated_at"))
    audit(
        request,
        ingestion,
        "RETRY_SUBLEDGER_CALLBACK",
        after={"callback_status": ingestion.callback_status},
    )
    return ingestion


@transaction.atomic
def sync_unposted_subledger_entry(ingestion, payload, request):
    """
    AF-13 vs AF-12 / EF-26 (BR-GL-INT-46..50):
    - Nếu bút toán GL đang ở trạng thái UNPOSTED (Chưa ghi sổ): cho phép cập nhật/sinh lại hoặc hủy hiệu lực
      khi chứng từ nguồn thay đổi hoặc bị hủy trước khi ghi sổ.
    - Nếu bút toán GL đã POSTED (Đã ghi sổ): tuyệt đối từ chối ghi đè hoặc xóa trực tiếp (EF-26).
    """
    ingestion = models.SubledgerJournalIngestion.objects.select_for_update().prefetch_related("journal_entries").get(pk=ingestion.pk)
    entries = list(ingestion.journal_entries.all())
    if ingestion.primary_journal_entry and ingestion.primary_journal_entry not in entries:
        entries.insert(0, ingestion.primary_journal_entry)

    if ingestion.status == models.SubledgerIngestionStatus.POSTED or any(e.status == "POSTED" for e in entries):
        raise ValidationError({
            "status": (
                "EF-26 / AF-12: Bút toán GL liên kết đã được ghi sổ vào Sổ cái (POSTED). "
                "Không được phép xóa hoặc ghi đè trực tiếp; phải thực hiện bỏ ghi hoặc lập bút toán đảo/điều chỉnh."
            )
        })
    if ingestion.status == models.SubledgerIngestionStatus.REVERSED:
        raise ValidationError({"status": "Bút toán đã đảo (REVERSED), không thể cập nhật trực tiếp."})

    action_type = str(payload.get("sync_action") or "UPDATE").strip().upper()
    if action_type in ("CANCEL", "VOID", "DELETE_UNPOSTED"):
        for e in entries:
            e.lines.all().delete()
            e.delete()
        ingestion.primary_journal_entry = None
        ingestion.status = models.SubledgerIngestionStatus.REVERSED
        ingestion.source_document_status = "CANCELLED"
        ingestion.updated_by = actor(request)
        ingestion.version += 1
        ingestion.save(
            update_fields=(
                "primary_journal_entry",
                "status",
                "source_document_status",
                "updated_by",
                "version",
                "updated_at",
            )
        )
        audit(
            request,
            ingestion,
            "CANCEL_UNPOSTED_SUBLEDGER",
            after={"status": ingestion.status, "source_document_number": ingestion.source_document_number},
        )
        return ingestion

    # Xóa các JournalEntry chưa ghi sổ cũ để sinh lại theo dữ liệu nguồn mới
    for e in entries:
        e.lines.all().delete()
        e.delete()
    ingestion.primary_journal_entry = None
    ingestion.status = models.SubledgerIngestionStatus.RECEIVED
    ingestion.save(update_fields=("primary_journal_entry", "status", "updated_at"))

    merged_payload = dict(ingestion.raw_payload or {})
    if isinstance(payload, dict):
        for k, v in payload.items():
            if v is not None and k != "sync_action":
                merged_payload[k] = v
    merged_payload["source_event_id"] = ingestion.source_event_id
    if "posting_mode" not in payload:
        merged_payload["posting_mode"] = models.SubledgerPostingMode.UNPOSTED

    updated_ing, _ = ingest_subledger_journal_event(
        company=ingestion.company,
        payload=merged_payload,
        request=request,
        existing_ingestion=ingestion,
    )
    return updated_ing


@transaction.atomic
def post_subledger_ingestion_entry(ingestion, request):
    """
    Hỗ trợ ghi sổ bút toán phân hệ đang ở trạng thái UNPOSTED sang POSTED (liên thông UC-GL-05).
    """
    ingestion = models.SubledgerJournalIngestion.objects.select_for_update().prefetch_related("journal_entries").get(pk=ingestion.pk)
    if ingestion.status == models.SubledgerIngestionStatus.POSTED:
        raise ValidationError({"status": "Bút toán tiếp nhận này đã được ghi sổ."})
    if ingestion.status != models.SubledgerIngestionStatus.UNPOSTED:
        raise ValidationError({"status": f"Chỉ bút toán ở trạng thái UNPOSTED mới được ghi sổ (hiện tại: {ingestion.status})."})

    entries = list(ingestion.journal_entries.all())
    if ingestion.primary_journal_entry and ingestion.primary_journal_entry not in entries:
        entries.insert(0, ingestion.primary_journal_entry)
    if not entries:
        raise ValidationError({"journal_entries": "Không tìm thấy bút toán GL liên kết để ghi sổ."})

    actor_user = actor(request)
    for je in entries:
        if je.status == "PENDING_APPROVAL":
            raise ValidationError({
                "status": f"Bút toán {je.number} đang chờ phê duyệt (PENDING_APPROVAL), chưa đủ điều kiện ghi sổ."
            })
        if je.status in ("DRAFT", "APPROVED"):
            if je.status == "DRAFT":
                je.status = "APPROVED"
                je.approved_by = actor_user
                je.approved_at = timezone.now()
            wf = dict(je.workflow_snapshot or {})
            wf["allow_creator_posting"] = True
            je.workflow_snapshot = wf
            je.save(update_fields=("status", "approved_by", "approved_at", "workflow_snapshot", "updated_at"))
            post(je, request)

    if ingestion.primary_journal_entry:
        ingestion.primary_journal_entry.refresh_from_db()
    ingestion.status = models.SubledgerIngestionStatus.POSTED
    ingestion.processed_at = timezone.now()
    ingestion.updated_by = actor_user
    ingestion.save(update_fields=("status", "processed_at", "updated_by", "updated_at"))
    return ingestion


def trace_subledger_source_link(company, query_params):
    """
    BR-GL-INT-32, BR-GL-INT-33, BR-GL-INT-60, EF-27:
    Truy vết hai chiều giữa Chứng từ nguồn (Subledger Document) và Bút toán GL (JournalEntry).
    """
    ingestion_id = query_params.get("ingestion_id")
    journal_entry_id = query_params.get("journal_entry_id")
    journal_number = query_params.get("journal_number")
    source_document_id = query_params.get("source_document_id")
    source_document_number = query_params.get("source_document_number")
    source_module = query_params.get("source_module")
    source_event_id = query_params.get("source_event_id")

    qs = models.SubledgerJournalIngestion.objects.filter(company=company).select_related(
        "primary_journal_entry", "period", "currency", "posting_rule"
    ).prefetch_related("journal_entries__lines__account")

    if ingestion_id:
        qs = qs.filter(id=ingestion_id)
    if journal_entry_id:
        qs = qs.filter(Q(primary_journal_entry_id=journal_entry_id) | Q(journal_entries__id=journal_entry_id)).distinct()
    if journal_number:
        qs = qs.filter(
            Q(primary_journal_entry__number__iexact=journal_number)
            | Q(journal_entries__number__iexact=journal_number)
        ).distinct()
    if source_document_id:
        qs = qs.filter(source_document_id=source_document_id)
    if source_document_number:
        qs = qs.filter(source_document_number__iexact=source_document_number)
    if source_module:
        qs = qs.filter(source_module=str(source_module).upper())
    if source_event_id:
        qs = qs.filter(source_event_id=source_event_id)

    matched = list(qs[:20])
    if not matched:
        raise ValidationError({
            "trace": "EF-27: Không tìm thấy liên kết truy vết giữa bút toán GL và chứng từ nguồn theo điều kiện tra cứu."
        })

    results = []
    for ing in matched:
        entries = list(ing.journal_entries.all())
        if ing.primary_journal_entry and ing.primary_journal_entry not in entries:
            entries.insert(0, ing.primary_journal_entry)
        results.append({
            "ingestion_id": str(ing.id),
            "status": ing.status,
            "posting_mode": ing.posting_mode,
            "callback_status": ing.callback_status,
            "source": {
                "source_module": ing.source_module,
                "source_module_label": ing.get_source_module_display(),
                "source_business_type": ing.source_business_type,
                "source_document_type": ing.source_document_type,
                "source_document_id": ing.source_document_id,
                "source_document_number": ing.source_document_number,
                "source_document_status": ing.source_document_status,
                "source_event_id": ing.source_event_id,
                "document_date": ing.document_date.isoformat() if ing.document_date else None,
                "posting_date": ing.posting_date.isoformat() if ing.posting_date else None,
            },
            "gl_entries": [
                {
                    "id": str(e.id),
                    "number": e.number,
                    "status": e.status,
                    "posting_date": e.posting_date.isoformat() if e.posting_date else None,
                    "total_debit": str(e.total_debit),
                    "total_credit": str(e.total_credit),
                    "lines": [
                        {
                            "line_no": ln.line_no,
                            "account_code": ln.account.code,
                            "account_name": ln.account.name,
                            "debit": str(ln.debit),
                            "credit": str(ln.credit),
                            "description": ln.description,
                        }
                        for ln in e.lines.all()
                    ],
                }
                for e in entries
            ],
        })
    return results


