@transaction.atomic
def unpost_subledger_ingestion_entry(ingestion, request):
    """
    UC-GL-05 (AF-10, AF-19, EF-26, BR-GL-POST-52..54):
    Bỏ ghi sổ bút toán tiếp nhận từ phân hệ nguồn (chỉ được phép khi có xác nhận từ phân hệ nguồn
    hoặc cấu hình cho phép Bỏ ghi sổ tại GL).
    """
    ingestion = (
        models.SubledgerJournalIngestion.objects.select_for_update()
        .prefetch_related("journal_entries")
        .get(pk=ingestion.pk)
    )
    if ingestion.status != models.SubledgerIngestionStatus.POSTED:
        raise ValidationError({
            "status": f"Chỉ bản ghi tiếp nhận ở trạng thái POSTED mới được phép bỏ ghi sổ (hiện tại: {ingestion.status}).",
            "error_code": "INVALID_STATE_FOR_UNPOST",
        })

    entries = list(ingestion.journal_entries.all())
    if ingestion.primary_journal_entry and ingestion.primary_journal_entry not in entries:
        entries.insert(0, ingestion.primary_journal_entry)
    if not entries:
        raise ValidationError({"journal_entries": "Không tìm thấy bút toán GL liên kết để bỏ ghi sổ."})

    for je in entries:
        if je.status == "POSTED":
            unpost(je, request)

    if ingestion.primary_journal_entry:
        ingestion.primary_journal_entry.refresh_from_db()
    ingestion.status = models.SubledgerIngestionStatus.UNPOSTED
    ingestion.updated_by = actor(request)
    ingestion.save(update_fields=("status", "updated_by", "updated_at"))
    return ingestion


