def _resolve_book_type_uc_gl_14(params):
    """
    UC-GL-14 (Section 1.1.A, EF-03, BR-GL-TRACE-22):
    Xác định loại sổ / chế độ tra cứu từ `book_type`, `inquiry_mode` hoặc `report_name`.
    """
    raw_bt = str(
        params.get("book_type")
        or params.get("inquiry_mode")
        or params.get("mode")
        or ""
    ).strip().upper()
    if raw_bt in BOOK_TYPE_CATALOG_UC_GL_14:
        return BOOK_TYPE_CATALOG_UC_GL_14[raw_bt]

    raw_name = str(params.get("report_name") or params.get("book_name") or "").strip().lower()
    if raw_name in REPORT_NAME_TO_BOOK_TYPE_UC_GL_14:
        mapped = REPORT_NAME_TO_BOOK_TYPE_UC_GL_14[raw_name]
        return BOOK_TYPE_CATALOG_UC_GL_14[mapped]

    if not raw_bt and not raw_name:
        return BOOK_TYPE_CATALOG_UC_GL_14["GENERAL_JOURNAL"]

    raise ValidationError({
        "book_type": (
            f"Loại sổ kế toán / chế độ tra cứu '{raw_bt or raw_name}' không tồn tại hoặc chưa được hỗ trợ "
            f"(EF-03, BR-GL-TRACE-22). Các mã hỗ trợ: {', '.join(BOOK_TYPE_CATALOG_UC_GL_14.keys())}."
        ),
        "error_code": "INVALID_BOOK_TYPE",
    })


def _resolve_inquiry_dates_uc_gl_14(company, params):
    """
    UC-GL-14 (Section 1.1.B, EF-04, EF-05, BR-GL-TRACE-16..20, 56..58):
    Xác định kỳ kế toán hoặc khoảng Từ ngày - Đến ngày hợp lệ.
    Cho phép tra cứu cả kỳ đang mở (OPEN), khóa một phần (PARTIALLY_LOCKED) và đã khóa (CLOSED).
    """
    period_obj = None
    period_input = params.get("period") or params.get("period_id") or params.get("period_code")
    if period_input:
        period_obj = (
            models.AccountingPeriod.objects.filter(company=company)
            .filter(Q(id__iexact=str(period_input)) if len(str(period_input)) == 36 else Q(code__iexact=str(period_input)))
            .first()
        )
        if not period_obj:
            raise ValidationError({
                "period": f"Kỳ kế toán '{period_input}' không tồn tại trong doanh nghiệp (EF-04, BR-GL-TRACE-16).",
                "error_code": "PERIOD_NOT_FOUND",
            })

    raw_from = params.get("from_date") or params.get("date_from") or params.get("start_date")
    raw_to = params.get("to_date") or params.get("date_to") or params.get("end_date")

    from_date = _parse_iso_date(raw_from, "from_date") if raw_from else (period_obj.start_date if period_obj else None)
    to_date = _parse_iso_date(raw_to, "to_date") if raw_to else (period_obj.end_date if period_obj else None)

    if not from_date or not to_date:
        latest_period = models.AccountingPeriod.objects.filter(company=company).order_by("-fiscal_year", "-period_number").first()
        if latest_period:
            period_obj = period_obj or latest_period
            from_date = from_date or latest_period.start_date
            to_date = to_date or latest_period.end_date
        else:
            today = timezone.now().date()
            from_date = from_date or today.replace(day=1)
            to_date = to_date or today

    if from_date > to_date:
        raise ValidationError({
            "from_date": f"Khoảng thời gian tra cứu không hợp lệ: Từ ngày ({from_date}) không được lớn hơn Đến ngày ({to_date}) (EF-05, BR-GL-TRACE-17).",
            "error_code": "INVALID_DATE_RANGE",
        })

    if not period_obj:
        period_obj = (
            models.AccountingPeriod.objects.filter(
                company=company, start_date__lte=to_date, end_date__gte=from_date
            )
            .order_by("start_date")
            .first()
        )

    return {
        "period": period_obj,
        "from_date": from_date,
        "to_date": to_date,
        "period_code": period_obj.code if period_obj else f"{from_date}..{to_date}",
        "period_status": period_obj.status if period_obj else "OPEN",
    }


def _enforce_data_scope_uc_gl_14(company, params):
    """
    UC-GL-14 (Section 1.1.F, EF-08, BR-GL-TRACE-04..06, 34, 80, 97, 98):
    Kiểm tra phạm vi dữ liệu (Data Scope) theo đơn vị/chi nhánh/phòng ban.
    Không trả về dữ liệu ngoài phạm vi quyền của Actor.
    """
    allowed_branches = params.get("allowed_branch_ids")
    requested_branch = params.get("branch") or params.get("branch_id")
    if allowed_branches is not None:
        allowed_branch_set = {str(b) for b in (allowed_branches if isinstance(allowed_branches, (list, tuple, set)) else [allowed_branches]) if b}
        if requested_branch and str(requested_branch) not in allowed_branch_set:
            raise ValidationError({
                "branch": "Đơn vị / Chi nhánh yêu cầu tra cứu nằm ngoài phạm vi dữ liệu (Data Scope) được cấp quyền (EF-08, BR-GL-TRACE-05, 06).",
                "error_code": "OUT_OF_DATA_SCOPE",
            })
    else:
        allowed_branch_set = None

    allowed_depts = params.get("allowed_department_ids")
    requested_dept = params.get("department") or params.get("department_id")
    if allowed_depts is not None:
        allowed_dept_set = {str(d) for d in (allowed_depts if isinstance(allowed_depts, (list, tuple, set)) else [allowed_depts]) if d}
        if requested_dept and str(requested_dept) not in allowed_dept_set:
            raise ValidationError({
                "department": "Phòng ban yêu cầu tra cứu nằm ngoài phạm vi dữ liệu (Data Scope) được cấp quyền (EF-08, BR-GL-TRACE-05, 06).",
                "error_code": "OUT_OF_DATA_SCOPE",
            })
    else:
        allowed_dept_set = None

    return {
        "allowed_branch_set": allowed_branch_set,
        "requested_branch": str(requested_branch) if requested_branch else None,
        "allowed_dept_set": allowed_dept_set,
        "requested_dept": str(requested_dept) if requested_dept else None,
    }


def _resolve_target_accounts_uc_gl_14(company, params):
    """
    UC-GL-14 (Section 1.1.C, AF-11, AF-12, EF-06, EF-07, BR-GL-TRACE-04, 28..30):
    Xác định danh sách tài khoản cần tra cứu (hỗ trợ cả tài khoản tổng hợp có gồm tài khoản con
    và tài khoản chi tiết, kiểm tra tài khoản thuộc đúng doanh nghiệp).
    """
    include_children = str(params.get("include_child_accounts", "true")).lower() not in ("false", "0", "no")
    account_id = params.get("account_id") or params.get("account")
    raw_codes = params.get("account_codes") or params.get("account_code") or ""

    requested_codes = []
    if isinstance(raw_codes, (list, tuple, set)):
        requested_codes = [str(c).strip() for c in raw_codes if str(c).strip()]
    elif str(raw_codes).strip():
        requested_codes = [c.strip() for c in str(raw_codes).split(",") if c.strip()]

    if account_id:
        acc_obj = models.Account.objects.filter(pk=account_id).first()
        if not acc_obj:
            raise ValidationError({
                "account": f"Tài khoản '{account_id}' không tồn tại trong hệ thống (EF-06).",
                "error_code": "ACCOUNT_NOT_FOUND",
            })
        if acc_obj.company_id != company.id:
            raise ValidationError({
                "account": f"Tài khoản '{acc_obj.code}' không thuộc doanh nghiệp đang làm việc (EF-07, BR-GL-TRACE-04).",
                "error_code": "ACCOUNT_COMPANY_MISMATCH",
            })
        if acc_obj.code not in requested_codes:
            requested_codes.append(acc_obj.code)

    for code in requested_codes:
        exists_in_company = models.Account.objects.filter(company=company, code=code).exists()
        if not exists_in_company:
            # Check if prefix matches only when allow_prefix is True; otherwise check if it belongs to another company
            other_co = models.Account.objects.exclude(company=company).filter(code=code).exists()
            if other_co and not models.Account.objects.filter(company=company, code__startswith=code).exists():
                raise ValidationError({
                    "account_code": f"Tài khoản '{code}' thuộc doanh nghiệp khác, không thuộc doanh nghiệp hiện tại (EF-07, BR-GL-TRACE-04).",
                    "error_code": "ACCOUNT_COMPANY_MISMATCH",
                })
            if not models.Account.objects.filter(company=company, code__startswith=code).exists():
                raise ValidationError({
                    "account_code": f"Tài khoản '{code}' không tồn tại trong Hệ thống tài khoản của doanh nghiệp (EF-06, BR-GL-TRACE-18).",
                    "error_code": "ACCOUNT_NOT_FOUND",
                })

    all_company_accounts = list(models.Account.objects.filter(company=company).order_by("code"))
    if not requested_codes:
        return {
            "requested_codes": [],
            "include_child_accounts": include_children,
            "matched_accounts": all_company_accounts,
            "matched_account_ids": {a.id for a in all_company_accounts},
        }

    matched_accounts = []
    seen_ids = set()
    for acc in all_company_accounts:
        for req_code in requested_codes:
            if include_children:
                if acc.code == req_code or acc.code.startswith(req_code):
                    if acc.id not in seen_ids:
                        matched_accounts.append(acc)
                        seen_ids.add(acc.id)
            else:
                if acc.code == req_code:
                    if acc.id not in seen_ids:
                        matched_accounts.append(acc)
                        seen_ids.add(acc.id)

    return {
        "requested_codes": requested_codes,
        "include_child_accounts": include_children,
        "matched_accounts": matched_accounts,
        "matched_account_ids": seen_ids,
    }


def _compute_account_opening_balances_uc_gl_14(company, account_ids, from_date, scope_info, currency_code=None):
    """
    UC-GL-14 (Steps 12–16, AF-02, AF-16, EF-11, BR-GL-TRACE-25..32):
    Tính số dư đầu kỳ (Nợ / Có và Ngoại tệ) cho tập tài khoản trước `from_date`
    từ Số dư đầu kỳ đã chốt (UC-GL-03: `entry_type="OPENING"`) + các dòng phát sinh `POSTED` trước `from_date`.
    Hỗ trợ tách theo đối tượng (`party_id`) cho tài khoản lưỡng tính (`131`, `331`, `138`, `338`).
    """
    # Map: account_id -> {"debit": Decimal, "credit": Decimal, "fc_by_ccy": {ccy: Decimal}}
    acc_open = {}
    # Map: (account_id, party_key) -> {"party_code": str, "party_name": str, "debit": Decimal, "credit": Decimal}
    party_open = {}
    ob_entry_ids = set()

    pre_lines_qs = (
        models.JournalLine.objects.select_related("entry", "account", "party", "currency")
        .filter(
            entry__company=company,
            entry__status__in=("POSTED", "REVERSED"),
            account_id__in=account_ids,
        )
        .filter(
            Q(entry__posting_date__lt=from_date)
            | Q(entry__posting_date=from_date, entry__entry_type="OPENING")
        )
    )
    if scope_info["requested_branch"]:
        pre_lines_qs = pre_lines_qs.filter(entry__branch_id=scope_info["requested_branch"])
    elif scope_info["allowed_branch_set"] is not None:
        pre_lines_qs = pre_lines_qs.filter(
            Q(entry__branch_id__in=scope_info["allowed_branch_set"]) | Q(entry__branch__isnull=True)
        )
    if scope_info["requested_dept"]:
        pre_lines_qs = pre_lines_qs.filter(department_id=scope_info["requested_dept"])
    elif scope_info["allowed_dept_set"] is not None:
        pre_lines_qs = pre_lines_qs.filter(
            Q(department_id__in=scope_info["allowed_dept_set"]) | Q(department__isnull=True)
        )
    if currency_code:
        pre_lines_qs = pre_lines_qs.filter(currency__code__iexact=currency_code)

    for ln in pre_lines_qs:
        aid = ln.account_id
        slot = acc_open.setdefault(aid, {"debit": Decimal("0"), "credit": Decimal("0"), "fc_by_ccy": {}})
        slot["debit"] += ln.debit or Decimal("0")
        slot["credit"] += ln.credit or Decimal("0")
        ccy = ln.currency.code if ln.currency_id else "VND"
        fc_amt = ln.foreign_amount or Decimal("0")
        fc_delta = fc_amt if (ln.debit or Decimal("0")) > Decimal("0") else -fc_amt
        slot["fc_by_ccy"][ccy] = slot["fc_by_ccy"].get(ccy, Decimal("0")) + fc_delta

        pkey = str(ln.party_id or "NO_PARTY")
        pslot = party_open.setdefault(
            (aid, pkey),
            {
                "party_id": str(ln.party_id) if ln.party_id else None,
                "party_code": ln.party.code if ln.party_id else "",
                "party_name": ln.party.name if ln.party_id else "Không chi tiết đối tượng",
                "debit": Decimal("0"),
                "credit": Decimal("0"),
            },
        )
        pslot["debit"] += ln.debit or Decimal("0")
        pslot["credit"] += ln.credit or Decimal("0")

    return acc_open, party_open, ob_entry_ids


def _resolve_reciprocal_accounts(entry_lines, current_line):
    """
    Xác định danh sách Tài khoản đối ứng (TK đối ứng) cho 1 dòng bút toán trên Sổ cái / Nhật ký.
    """
    is_debit = (current_line.debit or Decimal("0")) > Decimal("0")
    reciprocals = []
    for other in entry_lines:
        if other.id == current_line.id:
            continue
        if is_debit and (other.credit or Decimal("0")) > Decimal("0"):
            if other.account.code not in reciprocals:
                reciprocals.append(other.account.code)
        elif not is_debit and (other.debit or Decimal("0")) > Decimal("0"):
            if other.account.code not in reciprocals:
                reciprocals.append(other.account.code)
    if not reciprocals:
        for other in entry_lines:
            if other.id != current_line.id and other.account.code not in reciprocals:
                reciprocals.append(other.account.code)
    return ", ".join(reciprocals)


def _determine_entry_trace_summary(entry, denied_source_modules=None):
    """
    UC-GL-14 (Section 1.2.B, AF-17..19, EF-17..21, BR-GL-TRACE-38..55, 108..111):
    Xác định nhanh trạng thái khả năng truy vết (`trace_status`) cho một bút toán Sổ cái:
    - `TRACEABLE`: Có liên kết hợp lệ tới chứng từ nguồn và Actor có quyền xem
    - `PARTIAL_TRACE`: Có chứng từ nguồn nhưng thiếu một phần tài liệu tham chiếu phụ
    - `NO_SOURCE`: Bút toán tổng hợp trực tiếp tại GL (MANUAL, ALLOCATION, REVALUATION, CLOSING, ADJUSTMENT, REVERSAL, OPENING)
    - `BROKEN_LINK`: Bút toán có nguồn từ phân hệ hoặc khai báo `source_entity_id` nhưng bản ghi nguồn không tồn tại
    - `ACCESS_RESTRICTED`: Chứng từ nguồn tồn tại nhưng Actor không có quyền xem phân hệ nguồn (AF-19, EF-19)
    """
    denied_set = {str(m).strip().upper() for m in (denied_source_modules or []) if m}
    src_mod = (entry.source_module or "GL").strip().upper()
    src_type = (entry.source_entity_type or "").strip().upper()
    src_id = entry.source_entity_id

    if src_mod in denied_set:
        return {
            "trace_status": "ACCESS_RESTRICTED",
            "source_module": src_mod,
            "source_document_type": src_type or entry.entry_type,
            "source_document_id": str(src_id) if src_id else (entry.source_event_id or ""),
            "message": f"Bạn có quyền xem bút toán Sổ cái nhưng không có quyền mở chứng từ nguồn tại phân hệ {src_mod} (AF-19, EF-19, BR-GL-TRACE-52, 53).",
        }

    # Kiểm tra các chứng từ nghiệp vụ thuộc GL hoặc phân hệ con
    if src_id:
        found_source = False
        doc_no = ""
        if src_type in ("ADVANCE_SETTLEMENT", "ADVANCE_SETTLEMENT_VOUCHER") or models.AdvanceSettlementVoucher.objects.filter(pk=src_id).exists():
            v = models.AdvanceSettlementVoucher.objects.filter(pk=src_id).first()
            if v:
                found_source = True
                doc_no = v.number
        elif src_type in ("OPENING_BALANCE", "OPENING_BALANCE_HEADER") and entry.entry_type == "OPENING":
            found_source = True
            doc_no = entry.number
        elif src_type in ("GENERAL_VOUCHER", "GENERAL_BUSINESS_VOUCHER") or models.GeneralBusinessVoucher.objects.filter(pk=src_id).exists():
            v = models.GeneralBusinessVoucher.objects.filter(pk=src_id).first()
            if v:
                found_source = True
                doc_no = v.number
        elif src_type in ("ALLOCATION", "ALLOCATION_RUN") or models.AllocationRun.objects.filter(pk=src_id).exists():
            v = models.AllocationRun.objects.filter(pk=src_id).first()
            if v:
                found_source = True
                doc_no = v.number
        elif src_type in ("FX_REVALUATION", "FOREIGN_CURRENCY_REVALUATION_RUN") or models.ForeignCurrencyRevaluationRun.objects.filter(pk=src_id).exists():
            v = models.ForeignCurrencyRevaluationRun.objects.filter(pk=src_id).first()
            if v:
                found_source = True
                doc_no = v.number
        elif src_type in ("CLOSING", "CLOSING_RUN") or models.ClosingRun.objects.filter(pk=src_id).exists():
            v = models.ClosingRun.objects.filter(pk=src_id).first()
            if v:
                found_source = True
                doc_no = v.number or entry.number
        elif models.SubledgerJournalIngestion.objects.filter(Q(pk=src_id) | Q(source_document_id=str(src_id))).exists():
            ing = models.SubledgerJournalIngestion.objects.filter(Q(pk=src_id) | Q(source_document_id=str(src_id))).first()
            if ing:
                found_source = True
                doc_no = ing.source_document_number

        if not found_source:
            return {
                "trace_status": "BROKEN_LINK",
                "source_module": src_mod,
                "source_document_type": src_type or entry.entry_type,
                "source_document_id": str(src_id),
                "message": "Bút toán có khai báo liên kết chứng từ nguồn nhưng không tìm thấy bản ghi chứng từ nguồn trong hệ thống (EF-17, EF-18, BR-GL-TRACE-49, 50).",
            }

        has_partial_missing = bool((entry.workflow_snapshot or {}).get("missing_secondary_reference"))
        return {
            "trace_status": "PARTIAL_TRACE" if has_partial_missing else "TRACEABLE",
            "source_module": src_mod,
            "source_document_type": src_type or entry.entry_type,
            "source_document_id": str(src_id),
            "source_document_number": doc_no or entry.number,
            "message": (
                "Truy vết thành công tới chứng từ nguồn nhưng thiếu một số chứng từ tham chiếu phụ (PARTIAL_TRACE)."
                if has_partial_missing
                else "Truy vết đầy đủ tới chứng từ nghiệp vụ nguồn (TRACEABLE)."
            ),
        }

    # Kiểm tra qua SubledgerJournalIngestion hoặc chứng từ GL gắn entry
    ing = (
        models.SubledgerJournalIngestion.objects.filter(
            Q(primary_journal_entry=entry) | Q(journal_entries=entry)
        )
        .distinct()
        .first()
    )
    if ing:
        doc_type = ing.source_business_type or ing.source_document_type
        if ing.source_module.upper() in denied_set:
            return {
                "trace_status": "ACCESS_RESTRICTED",
                "source_module": ing.source_module,
                "source_document_type": doc_type,
                "source_document_id": ing.source_document_id,
                "source_document_number": ing.source_document_number,
                "message": f"Không có quyền mở chứng từ gốc tại phân hệ {ing.source_module} (ACCESS_RESTRICTED).",
            }
        if (entry.workflow_snapshot or {}).get("broken_source_link") or ing.status == "ERROR":
            return {
                "trace_status": "BROKEN_LINK",
                "source_module": ing.source_module,
                "source_document_type": doc_type,
                "source_document_id": ing.source_document_id,
                "source_document_number": ing.source_document_number,
                "message": "Liên kết chứng từ nguồn bị đứt gãy hoặc không tồn tại (BROKEN_LINK).",
            }
        return {
            "trace_status": "TRACEABLE",
            "source_module": ing.source_module,
            "source_document_type": doc_type,
            "source_document_id": ing.source_document_id,
            "source_document_number": ing.source_document_number,
            "message": "Truy vết đầy đủ tới chứng từ phân hệ nguồn (TRACEABLE).",
        }

    gbv = models.GeneralBusinessVoucher.objects.filter(journal_entry=entry).first()
    if gbv:
        return {
            "trace_status": "TRACEABLE",
            "source_module": "GL",
            "source_document_type": "GENERAL_BUSINESS_VOUCHER",
            "source_document_id": str(gbv.id),
            "source_document_number": gbv.number,
            "message": "Truy vết đầy đủ tới Chứng từ nghiệp vụ khác (UC-GL-04).",
        }

    asv = models.AdvanceSettlementVoucher.objects.filter(journal_entry=entry).first()
    if asv:
        return {
            "trace_status": "TRACEABLE",
            "source_module": "GL",
            "source_document_type": "ADVANCE_SETTLEMENT_VOUCHER",
            "source_document_id": str(asv.id),
            "source_document_number": asv.number,
            "message": "Truy vết đầy đủ tới Chứng từ quyết toán tạm ứng (UC-GL-02).",
        }

    fxr = models.ForeignCurrencyRevaluationRun.objects.filter(entry=entry).first()
    if fxr:
        return {
            "trace_status": "TRACEABLE",
            "source_module": "GL",
            "source_document_type": "FX_REVALUATION_RUN",
            "source_document_id": str(fxr.id),
            "source_document_number": fxr.number,
            "message": "Truy vết đầy đủ tới Đợt đánh giá lại ngoại tệ (UC-GL-08).",
        }

    alr = models.AllocationRun.objects.filter(entry=entry).first()
    if alr:
        return {
            "trace_status": "TRACEABLE",
            "source_module": "GL",
            "source_document_type": "ALLOCATION_RUN",
            "source_document_id": str(alr.id),
            "source_document_number": alr.number,
            "message": "Truy vết đầy đủ tới Chứng từ phân bổ chi phí (UC-GL-07).",
        }

    clr = models.ClosingRun.objects.filter(entry=entry).first()
    if clr:
        return {
            "trace_status": "TRACEABLE",
            "source_module": "GL",
            "source_document_type": "CLOSING_RUN",
            "source_document_id": str(clr.id),
            "source_document_number": clr.number or entry.number,
            "message": "Truy vết đầy đủ tới Đợt kết chuyển lãi lỗ cuối kỳ (UC-GL-09).",
        }

    # Nếu bút toán khai báo phân hệ nguồn khác GL (PUR, SAL, CASH, BANK, INV, FA...) nhưng không có bản ghi nguồn
    if src_mod not in ("", "GL") or entry.entry_type == "SUBLEDGER":
        return {
            "trace_status": "BROKEN_LINK",
            "source_module": src_mod or "SUBLEDGER",
            "source_document_type": src_type or "SUBLEDGER_VOUCHER",
            "source_document_id": str(src_id or ""),
            "message": f"Bút toán từ phân hệ {src_mod or 'SUBLEDGER'} bị thiếu liên kết chứng từ nguồn (EF-17, BR-GL-TRACE-49, 110).",
        }

    # AF-17, BR-GL-TRACE-48, 109: Bút toán tổng hợp trực tiếp tại GL không có chứng từ phân hệ nguồn
    return {
        "trace_status": "NO_SOURCE",
        "source_module": "GL",
        "source_document_type": entry.entry_type,
        "source_document_id": "",
        "source_document_number": entry.number,
        "message": "Bút toán được lập trực tiếp tại phân hệ Kế toán tổng hợp (GL), không qua chứng từ phân hệ nguồn (AF-17, BR-GL-TRACE-48, 109).",
    }


def query_accounting_book_uc_gl_14(company, params=None, request=None):
    """
    UC-GL-14 – Tra cứu Sổ cái / Nhật ký / truy vết chứng từ (Main Flow Steps 1–23, AF-01..16, AF-24, EF-01..15, BR-GL-TRACE-01..34, 56..75):
    Hỗ trợ tra cứu đầy đủ 16 chế độ Sổ kế toán & Tra cứu bút toán theo Thông tư 99/2025/TT-BTC.
    Đảm bảo tuyệt đối không làm thay đổi dữ liệu kế toán (Zero GL Mutation — BR-GL-TRACE-01).
    """
    params = dict(params or {})
    book_meta = _resolve_book_type_uc_gl_14(params)
    book_type = book_meta["book_type"]
    is_official_book = book_meta["is_official_book"]

    dates_info = _resolve_inquiry_dates_uc_gl_14(company, params)
    from_date = dates_info["from_date"]
    to_date = dates_info["to_date"]
    period_obj = dates_info["period"]

    scope_info = _enforce_data_scope_uc_gl_14(company, params)

    # EF-09, BR-GL-TRACE-10, 11, 12, 100: Kiểm tra trạng thái bút toán trên Sổ kế toán chính thức
    raw_status = str(params.get("entry_status") or params.get("status") or "").strip().upper()
    include_unposted = str(params.get("include_unposted", "false")).strip().lower() in ("true", "1", "yes")
    if is_official_book:
        if include_unposted or raw_status in ("UNPOSTED", "DRAFT", "PENDING_APPROVAL", "APPROVED", "REJECTED", "CANCELLED"):
            raise ValidationError({
                "entry_status": (
                    f"Sổ kế toán chính thức ({book_meta['title']} - {book_meta['form_code']}) chỉ được phép phản ánh "
                    "các bút toán đã ghi sổ (POSTED). Không được trộn bút toán chưa ghi sổ (UNPOSTED/DRAFT) vào Sổ cái / Nhật ký chính thức "
                    "(EF-09, BR-GL-TRACE-10, 11, 100). Vui lòng dùng chế độ 'Tra cứu bút toán GL' (GL_ENTRY_INQUIRY) để tra cứu chứng từ chưa ghi sổ."
                ),
                "error_code": "UNPOSTED_NOT_ALLOWED_IN_OFFICIAL_BOOK",
            })
        allowed_statuses = ("POSTED", "REVERSED")
    else:
        if raw_status == "UNPOSTED":
            allowed_statuses = ("DRAFT", "PENDING_APPROVAL", "APPROVED")
        elif raw_status and raw_status != "ALL":
            allowed_statuses = (raw_status,)
        else:
            allowed_statuses = ("DRAFT", "PENDING_APPROVAL", "APPROVED", "POSTED", "REVERSED", "REJECTED", "CANCELLED")

    # Xác định phạm vi tài khoản theo từng loại sổ chuyên biệt (AF-06..10)
    acc_info = _resolve_target_accounts_uc_gl_14(company, params)
    matched_accounts = acc_info["matched_accounts"]
    matched_account_ids = set(acc_info["matched_account_ids"])

    if book_type in ("CASH_RECEIPT_JOURNAL", "CASH_PAYMENT_JOURNAL") and not acc_info["requested_codes"]:
        cash_accs = [a for a in matched_accounts if a.code.startswith(("111", "112"))]
        if cash_accs:
            matched_accounts = cash_accs
            matched_account_ids = {a.id for a in cash_accs}

    currency_filter = str(params.get("currency_code") or params.get("currency") or "").strip().upper()
    if book_type == "FOREIGN_CURRENCY_LEDGER":
        # EF-14, BR-GL-TRACE-71..75: Kiểm tra điều kiện ngoại tệ
        if currency_filter == "VND":
            raise ValidationError({
                "currency_code": "Sổ theo dõi thanh toán bằng ngoại tệ yêu cầu chọn mã ngoại tệ (USD, EUR, JPY...) hoặc tất cả ngoại tệ khác VND (EF-14, BR-GL-TRACE-71).",
                "error_code": "INVALID_FOREIGN_CURRENCY_FILTER",
            })

    # Tính số dư đầu kỳ cho các tài khoản liên quan
    acc_open, party_open, ob_entry_ids = _compute_account_opening_balances_uc_gl_14(
        company,
        matched_account_ids,
        from_date,
        scope_info,
        currency_code=currency_filter if currency_filter else None,
    )

    # Truy vấn các dòng phát sinh trong kỳ [from_date, to_date]
    lines_qs = (
        models.JournalLine.objects.select_related(
            "entry",
            "entry__period",
            "entry__branch",
            "entry__created_by",
            "entry__posted_by",
            "entry__original_entry",
            "account",
            "currency",
            "party",
            "department",
            "project",
            "cost_center",
            "warehouse",
        )
        .prefetch_related("entry__lines__account", "entry__related_entries")
        .filter(
            entry__company=company,
            entry__status__in=allowed_statuses,
            entry__posting_date__gte=from_date,
            entry__posting_date__lte=to_date,
        )
    )
    if is_official_book:
        # Không lặp lại bút toán OPENING đầu kỳ trong phát sinh trong kỳ nếu đã tính vào Số dư đầu kỳ
        lines_qs = lines_qs.exclude(entry__posting_date=from_date, entry__entry_type="OPENING")
        if ob_entry_ids:
            lines_qs = lines_qs.exclude(entry_id__in=ob_entry_ids)

    if acc_info["requested_codes"] or book_type in ("CASH_RECEIPT_JOURNAL", "CASH_PAYMENT_JOURNAL"):
        lines_qs = lines_qs.filter(account_id__in=matched_account_ids)

    # Áp dụng Data Scope
    if scope_info["requested_branch"]:
        lines_qs = lines_qs.filter(entry__branch_id=scope_info["requested_branch"])
    elif scope_info["allowed_branch_set"] is not None:
        lines_qs = lines_qs.filter(
            Q(entry__branch_id__in=scope_info["allowed_branch_set"]) | Q(entry__branch__isnull=True)
        )
    if scope_info["requested_dept"]:
        lines_qs = lines_qs.filter(department_id=scope_info["requested_dept"])
    elif scope_info["allowed_dept_set"] is not None:
        lines_qs = lines_qs.filter(
            Q(department_id__in=scope_info["allowed_dept_set"]) | Q(department__isnull=True)
        )

    # Các bộ lọc bổ sung (Section 1.1.C, D, E, G)
    voucher_number = str(params.get("voucher_number") or params.get("number") or "").strip()
    if voucher_number:
        lines_qs = lines_qs.filter(
            Q(entry__number__icontains=voucher_number)
            | Q(entry__source_event_id__icontains=voucher_number)
        )

    entry_type_filter = str(params.get("entry_type") or "").strip().upper()
    if entry_type_filter:
        lines_qs = lines_qs.filter(entry__entry_type=entry_type_filter)

    source_module_filter = str(params.get("source_module") or "").strip().upper()
    if source_module_filter:
        lines_qs = lines_qs.filter(entry__source_module__iexact=source_module_filter)

    keyword = str(params.get("keyword") or params.get("search") or params.get("description") or "").strip()
    if keyword:
        lines_qs = lines_qs.filter(
            Q(description__icontains=keyword)
            | Q(entry__description__icontains=keyword)
            | Q(entry__number__icontains=keyword)
            | Q(account__code__icontains=keyword)
            | Q(party__code__icontains=keyword)
            | Q(party__name__icontains=keyword)
        )

    party_filter = params.get("party_id") or params.get("party") or params.get("party_code")
    if party_filter:
        lines_qs = lines_qs.filter(
            Q(party_id=party_filter) if len(str(party_filter)) == 36 else Q(party__code__iexact=str(party_filter))
        )

    project_filter = params.get("project_id") or params.get("project") or params.get("project_code")
    if project_filter:
        lines_qs = lines_qs.filter(
            Q(project_id=project_filter) if len(str(project_filter)) == 36 else Q(project__code__iexact=str(project_filter))
        )

    cost_center_filter = params.get("cost_center_id") or params.get("cost_center") or params.get("cost_center_code")
    if cost_center_filter:
        lines_qs = lines_qs.filter(
            Q(cost_center_id=cost_center_filter) if len(str(cost_center_filter)) == 36 else Q(cost_center__code__iexact=str(cost_center_filter))
        )

    if currency_filter:
        lines_qs = lines_qs.filter(currency__code__iexact=currency_filter)
    elif book_type == "FOREIGN_CURRENCY_LEDGER":
        lines_qs = lines_qs.exclude(currency__code__iexact="VND")

    min_amount = params.get("min_amount")
    if min_amount not in (None, ""):
        min_dec = Decimal(str(min_amount))
        lines_qs = lines_qs.filter(Q(debit__gte=min_dec) | Q(credit__gte=min_dec))

    max_amount = params.get("max_amount")
    if max_amount not in (None, ""):
        max_dec = Decimal(str(max_amount))
        lines_qs = lines_qs.filter(
            (Q(debit__gt=0) & Q(debit__lte=max_dec)) | (Q(credit__gt=0) & Q(credit__lte=max_dec))
        )

    # Bộ lọc riêng cho Nhật ký chuyên biệt (AF-06..09)
    if book_type == "CASH_RECEIPT_JOURNAL":
        lines_qs = lines_qs.filter(account__code__startswith="11", debit__gt=0)
    elif book_type == "CASH_PAYMENT_JOURNAL":
        lines_qs = lines_qs.filter(account__code__startswith="11", credit__gt=0)
    elif book_type == "PURCHASE_JOURNAL":
        lines_qs = lines_qs.filter(
            Q(entry__source_module__in=("PUR", "AP", "INV"))
            | Q(account__code__startswith=("152", "153", "156", "211", "331"))
        )
    elif book_type == "SALES_JOURNAL":
        lines_qs = lines_qs.filter(
            Q(entry__source_module__in=("SAL", "AR"))
            | Q(account__code__startswith=("511", "131"))
        )

    # BR-GL-TRACE-23, 24: Sắp xếp cố định và nhất quán theo (posting_date, number, created_at, line_no)
    ordered_lines = list(
        lines_qs.order_by("entry__posting_date", "entry__number", "entry__created_at", "line_no")
    )

    reciprocal_filter = str(params.get("reciprocal_account_code") or params.get("reciprocal_account") or "").strip()
    cost_item_filter = str(params.get("cost_item_code") or params.get("expense_item") or "").strip()
    contract_filter = str(params.get("contract_code") or params.get("contract") or "").strip()
    stat_code_filter = str(params.get("stat_code") or params.get("statistical_code") or "").strip()
    denied_source_modules = params.get("denied_source_modules") or []

    # Lọc hậu xử lý cho TK đối ứng và các chiều mở rộng lưu trong JSON dimensions
    filtered_lines = []
    for ln in ordered_lines:
        all_entry_lines = list(ln.entry.lines.all())
        recip_str = _resolve_reciprocal_accounts(all_entry_lines, ln)
        if reciprocal_filter and reciprocal_filter not in [r.strip() for r in recip_str.split(",") if r.strip()] and not any(
            r.strip().startswith(reciprocal_filter) for r in recip_str.split(",") if r.strip()
        ):
            continue
        dims = ln.dimensions or {}
        if cost_item_filter and str(dims.get("cost_item_code") or dims.get("expense_item") or "") != cost_item_filter:
            continue
        if contract_filter and str(dims.get("contract_code") or dims.get("contract") or "") != contract_filter:
            continue
        if stat_code_filter and str(dims.get("stat_code") or dims.get("statistical_code") or "") != stat_code_filter:
            continue
        filtered_lines.append((ln, recip_str))

    # Tính số dư lũy kế sau từng dòng (Running balance — BR-GL-TRACE-24, 25) theo tài khoản
    running_by_acc = {}
    running_fc_by_acc_ccy = {}
    for acc in matched_accounts:
        op = acc_open.get(acc.id, {"debit": Decimal("0"), "credit": Decimal("0"), "fc_by_ccy": {}})
        running_by_acc[acc.id] = (op["debit"] - op["credit"])
        for ccy, fc_val in op.get("fc_by_ccy", {}).items():
            running_fc_by_acc_ccy[(acc.id, ccy)] = fc_val

    movement_rows = []
    period_debit_total = Decimal("0")
    period_credit_total = Decimal("0")
    acc_period_turnovers = {}
    party_period_turnovers = {}
    currency_summaries = {}
    t_account_map = {}

    for idx, (ln, recip_str) in enumerate(filtered_lines, start=1):
        entry = ln.entry
        acc = ln.account
        deb = ln.debit or Decimal("0")
        cred = ln.credit or Decimal("0")
        period_debit_total += deb
        period_credit_total += cred

        # Cập nhật phát sinh theo tài khoản
        acc_slot = acc_period_turnovers.setdefault(acc.id, {"debit": Decimal("0"), "credit": Decimal("0")})
        acc_slot["debit"] += deb
        acc_slot["credit"] += cred

        # Cập nhật phát sinh theo đối tượng (phục vụ TK lưỡng tính 131, 331 — AF-16, BR-GL-TRACE-31, 32)
        pkey = str(ln.party_id or "NO_PARTY")
        pslot = party_period_turnovers.setdefault(
            (acc.id, pkey),
            {
                "party_id": str(ln.party_id) if ln.party_id else None,
                "party_code": ln.party.code if ln.party_id else "",
                "party_name": ln.party.name if ln.party_id else "Không chi tiết đối tượng",
                "debit": Decimal("0"),
                "credit": Decimal("0"),
            },
        )
        pslot["debit"] += deb
        pslot["credit"] += cred

        # Cập nhật Running Balance
        net_after = running_by_acc.get(acc.id, Decimal("0")) + deb - cred
        running_by_acc[acc.id] = net_after
        if acc.normal_balance == "CREDIT":
            run_deb = net_after if net_after > Decimal("0") else Decimal("0")
            run_cred = -net_after if net_after < Decimal("0") else Decimal("0")
        else:
            run_deb = net_after if net_after > Decimal("0") else Decimal("0")
            run_cred = -net_after if net_after < Decimal("0") else Decimal("0")

        # Ngoại tệ (AF-10, BR-GL-TRACE-71..75: Không cộng ngang USD + EUR)
        ccy_code = ln.currency.code if ln.currency_id else "VND"
        fc_amt = ln.foreign_amount or Decimal("0")
        fc_deb = fc_amt if deb > Decimal("0") else Decimal("0")
        fc_cred = fc_amt if cred > Decimal("0") else Decimal("0")
        fc_net_after = running_fc_by_acc_ccy.get((acc.id, ccy_code), Decimal("0")) + fc_deb - fc_cred
        running_fc_by_acc_ccy[(acc.id, ccy_code)] = fc_net_after

        ccy_slot = currency_summaries.setdefault(
            ccy_code,
            {
                "currency_code": ccy_code,
                "period_debit_fc": Decimal("0"),
                "period_credit_fc": Decimal("0"),
                "period_debit_vnd": Decimal("0"),
                "period_credit_vnd": Decimal("0"),
                "line_count": 0,
            },
        )
        ccy_slot["period_debit_fc"] += fc_deb
        ccy_slot["period_credit_fc"] += fc_cred
        ccy_slot["period_debit_vnd"] += deb
        ccy_slot["period_credit_vnd"] += cred
        ccy_slot["line_count"] += 1

        # Bảng chữ T (T_ACCOUNT_SUMMARY)
        t_slot = t_account_map.setdefault(
            acc.code,
            {
                "account_code": acc.code,
                "account_name": acc.name,
                "debit_by_reciprocal": {},
                "credit_by_reciprocal": {},
                "total_debit": Decimal("0"),
                "total_credit": Decimal("0"),
            },
        )
        first_recip = (recip_str.split(",")[0].strip() if recip_str else "KHAC") or "KHAC"
        if deb > Decimal("0"):
            t_slot["debit_by_reciprocal"][first_recip] = t_slot["debit_by_reciprocal"].get(first_recip, Decimal("0")) + deb
            t_slot["total_debit"] += deb
        if cred > Decimal("0"):
            t_slot["credit_by_reciprocal"][first_recip] = t_slot["credit_by_reciprocal"].get(first_recip, Decimal("0")) + cred
            t_slot["total_credit"] += cred

        trace_info = _determine_entry_trace_summary(entry, denied_source_modules=denied_source_modules)
        related_reversal_numbers = [r.number for r in entry.related_entries.all()]
        dims = ln.dimensions or {}

        movement_rows.append({
            "row_no": idx,
            "line_id": str(ln.id),
            "entry_id": str(entry.id),
            "line_no": ln.line_no,
            "posting_date": str(entry.posting_date),
            "document_date": str(entry.document_date or entry.posting_date),
            "period_code": entry.period.code if entry.period_id else dates_info["period_code"],
            "voucher_number": entry.number,
            "entry_type": entry.entry_type,
            "entry_status": entry.status,
            "description": ln.description or entry.description,
            "header_description": entry.description,
            "account_code": acc.code,
            "account_name": acc.name,
            "reciprocal_account_code": recip_str,
            "debit": str(deb),
            "credit": str(cred),
            "running_debit": str(run_deb),
            "running_credit": str(run_cred),
            "running_balance_side": "DEBIT" if run_deb > Decimal("0") else ("CREDIT" if run_cred > Decimal("0") else "ZERO"),
            "currency_code": ccy_code,
            "exchange_rate": str(ln.exchange_rate or Decimal("1")),
            "debit_fc": str(fc_deb),
            "credit_fc": str(fc_cred),
            "running_balance_fc": str(fc_net_after),
            "party_code": ln.party.code if ln.party_id else "",
            "party_name": ln.party.name if ln.party_id else "",
            "department_code": ln.department.code if ln.department_id else "",
            "department_name": ln.department.name if ln.department_id else "",
            "project_code": ln.project.code if ln.project_id else "",
            "cost_center_code": ln.cost_center.code if ln.cost_center_id else "",
            "cost_item_code": str(dims.get("cost_item_code") or dims.get("expense_item") or ""),
            "contract_code": str(dims.get("contract_code") or dims.get("contract") or ""),
            "stat_code": str(dims.get("stat_code") or dims.get("statistical_code") or ""),
            "source_module": trace_info["source_module"],
            "source_document_type": trace_info["source_document_type"],
            "source_document_id": trace_info["source_document_id"],
            "source_document_number": trace_info.get("source_document_number") or entry.number,
            "trace_status": trace_info["trace_status"],
            "trace_message": trace_info["message"],
            "is_reversed_or_adjusted": bool(entry.status == "REVERSED" or entry.is_adjusted or entry.original_entry_id or related_reversal_numbers),
            "original_entry_number": entry.original_entry.number if entry.original_entry_id else "",
            "related_entry_numbers": related_reversal_numbers,
        })

    # Tổng hợp số dư Đầu kỳ - Phát sinh - Cuối kỳ theo từng Tài khoản & Tài khoản tổng hợp (AF-02, AF-05, AF-11, AF-16, BR-GL-TRACE-25..32)
    account_summaries = []
    detail_partner_summaries = []
    leaf_opening_debit = Decimal("0")
    leaf_opening_credit = Decimal("0")
    leaf_closing_debit = Decimal("0")
    leaf_closing_credit = Decimal("0")

    # Bước 1: Tính số dư từng tài khoản chi tiết (leaf accounts), có xét lưỡng tính theo đối tượng cho 131, 331, 138, 338
    leaf_summary_by_code = {}
    for acc in matched_accounts:
        has_children_in_matched = any(
            other.id != acc.id and other.code.startswith(acc.code) for other in matched_accounts
        )
        if has_children_in_matched:
            continue

        is_bilateral = acc.normal_balance == "BOTH" or acc.code.startswith(("131", "331", "138", "338"))
        op_slot = acc_open.get(acc.id, {"debit": Decimal("0"), "credit": Decimal("0")})
        pr_slot = acc_period_turnovers.get(acc.id, {"debit": Decimal("0"), "credit": Decimal("0")})

        if is_bilateral:
            # AF-16, BR-GL-TRACE-31, 32: Không bù trừ chéo công nợ giữa các đối tượng khác nhau
            party_keys = {
                k[1] for k in list(party_open.keys()) + list(party_period_turnovers.keys()) if k[0] == acc.id
            }
            if party_keys:
                op_deb = Decimal("0")
                op_cred = Decimal("0")
                cl_deb = Decimal("0")
                cl_cred = Decimal("0")
                for pkey in sorted(party_keys):
                    po = party_open.get((acc.id, pkey), {"debit": Decimal("0"), "credit": Decimal("0"), "party_code": "", "party_name": ""})
                    pp = party_period_turnovers.get((acc.id, pkey), {"debit": Decimal("0"), "credit": Decimal("0"), "party_code": "", "party_name": ""})
                    p_open_net = po["debit"] - po["credit"]
                    p_open_d = p_open_net if p_open_net > Decimal("0") else Decimal("0")
                    p_open_c = -p_open_net if p_open_net < Decimal("0") else Decimal("0")
                    p_close_net = p_open_net + pp["debit"] - pp["credit"]
                    p_close_d = p_close_net if p_close_net > Decimal("0") else Decimal("0")
                    p_close_c = -p_close_net if p_close_net < Decimal("0") else Decimal("0")
                    op_deb += p_open_d
                    op_cred += p_open_c
                    cl_deb += p_close_d
                    cl_cred += p_close_c

                    if any(x != Decimal("0") for x in (p_open_d, p_open_c, pp["debit"], pp["credit"], p_close_d, p_close_c)):
                        detail_partner_summaries.append({
                            "account_code": acc.code,
                            "account_name": acc.name,
                            "party_id": po.get("party_id") or pp.get("party_id"),
                            "party_code": po.get("party_code") or pp.get("party_code") or "KHAC",
                            "party_name": po.get("party_name") or pp.get("party_name") or "Không chi tiết đối tượng",
                            "opening_debit": str(p_open_d),
                            "opening_credit": str(p_open_c),
                            "period_debit": str(pp["debit"]),
                            "period_credit": str(pp["credit"]),
                            "closing_debit": str(p_close_d),
                            "closing_credit": str(p_close_c),
                        })
            else:
                open_net = op_slot["debit"] - op_slot["credit"]
                op_deb = open_net if open_net > Decimal("0") else Decimal("0")
                op_cred = -open_net if open_net < Decimal("0") else Decimal("0")
                close_net = open_net + pr_slot["debit"] - pr_slot["credit"]
                cl_deb = close_net if close_net > Decimal("0") else Decimal("0")
                cl_cred = -close_net if close_net < Decimal("0") else Decimal("0")
        else:
            open_net = op_slot["debit"] - op_slot["credit"]
            op_deb = open_net if open_net > Decimal("0") else Decimal("0")
            op_cred = -open_net if open_net < Decimal("0") else Decimal("0")
            close_net = open_net + pr_slot["debit"] - pr_slot["credit"]
            cl_deb = close_net if close_net > Decimal("0") else Decimal("0")
            cl_cred = -close_net if close_net < Decimal("0") else Decimal("0")

        leaf_opening_debit += op_deb
        leaf_opening_credit += op_cred
        leaf_closing_debit += cl_deb
        leaf_closing_credit += cl_cred

        leaf_summary_by_code[acc.code] = {
            "account_id": str(acc.id),
            "account_code": acc.code,
            "account_name": acc.name,
            "account_level": acc.account_level,
            "is_parent": False,
            "is_bilateral": is_bilateral,
            "opening_debit": op_deb,
            "opening_credit": op_cred,
            "period_debit": pr_slot["debit"],
            "period_credit": pr_slot["credit"],
            "closing_debit": cl_deb,
            "closing_credit": cl_cred,
        }

    # Bước 2: Rollup tài khoản cha từ các tài khoản con chi tiết (BR-GL-TRACE-28..30: không cộng trùng cha + con)
    include_zero = str(params.get("include_zero_balance", "false")).strip().lower() in ("true", "1", "yes")
    for acc in matched_accounts:
        if acc.code in leaf_summary_by_code:
            row_data = leaf_summary_by_code[acc.code]
        else:
            child_leaves = [v for k, v in leaf_summary_by_code.items() if k.startswith(acc.code)]
            is_bilateral = acc.normal_balance == "BOTH" or acc.code.startswith(("131", "331", "138", "338"))
            op_d = sum((c["opening_debit"] for c in child_leaves), Decimal("0"))
            op_c = sum((c["opening_credit"] for c in child_leaves), Decimal("0"))
            pr_d = sum((c["period_debit"] for c in child_leaves), Decimal("0"))
            pr_c = sum((c["period_credit"] for c in child_leaves), Decimal("0"))
            cl_d = sum((c["closing_debit"] for c in child_leaves), Decimal("0"))
            cl_c = sum((c["closing_credit"] for c in child_leaves), Decimal("0"))
            if not is_bilateral:
                open_net = op_d - op_c
                op_d = open_net if open_net > Decimal("0") else Decimal("0")
                op_c = -open_net if open_net < Decimal("0") else Decimal("0")
                close_net = cl_d - cl_c
                cl_d = close_net if close_net > Decimal("0") else Decimal("0")
                cl_c = -close_net if close_net < Decimal("0") else Decimal("0")
            row_data = {
                "account_id": str(acc.id),
                "account_code": acc.code,
                "account_name": acc.name,
                "account_level": acc.account_level,
                "is_parent": True,
                "is_bilateral": is_bilateral,
                "opening_debit": op_d,
                "opening_credit": op_c,
                "period_debit": pr_d,
                "period_credit": pr_c,
                "closing_debit": cl_d,
                "closing_credit": cl_c,
            }

        has_activity = any(
            row_data[k] != Decimal("0")
            for k in ("opening_debit", "opening_credit", "period_debit", "period_credit", "closing_debit", "closing_credit")
        )
        if has_activity or include_zero or acc.code in acc_info["requested_codes"]:
            account_summaries.append({
                "account_id": row_data["account_id"],
                "account_code": row_data["account_code"],
                "account_name": row_data["account_name"],
                "account_level": row_data["account_level"],
                "is_parent": row_data["is_parent"],
                "is_bilateral": row_data["is_bilateral"],
                "opening_debit": str(row_data["opening_debit"]),
                "opening_credit": str(row_data["opening_credit"]),
                "period_debit": str(row_data["period_debit"]),
                "period_credit": str(row_data["period_credit"]),
                "closing_debit": str(row_data["closing_debit"]),
                "closing_credit": str(row_data["closing_credit"]),
            })

    # Sổ chi tiết tài khoản nhiều kỳ (MULTI_PERIOD_DETAIL_LEDGER — AF-04): Nhóm theo từng kỳ kế toán
    multi_period_groups = []
    if book_type == "MULTI_PERIOD_DETAIL_LEDGER":
        period_buckets = {}
        for row in movement_rows:
            pcode = row["period_code"]
            b = period_buckets.setdefault(
                pcode,
                {"period_code": pcode, "period_debit": Decimal("0"), "period_credit": Decimal("0"), "rows": []},
            )
            b["period_debit"] += Decimal(row["debit"])
            b["period_credit"] += Decimal(row["credit"])
            b["rows"].append(row)
        for pcode, b in period_buckets.items():
            multi_period_groups.append({
                "period_code": pcode,
                "period_debit": str(b["period_debit"]),
                "period_credit": str(b["period_credit"]),
                "row_count": len(b["rows"]),
                "rows": b["rows"],
            })

    # Kiểm tra nhất quán với Bảng cân đối / Tổng hợp số dư UC-GL-10 (EF-13, BR-GL-TRACE-26, 27, 102)
    consistency_status = "MATCHED"
    consistency_message = "Số dư đầu kỳ, phát sinh trong kỳ và số dư cuối kỳ khớp 100% với Bảng tổng hợp số dư tài khoản (UC-GL-10)."
    if period_obj:
        latest_agg = (
            models.BalanceAggregationRun.objects.filter(company=company, period=period_obj)
            .order_by("-started_at")
            .first()
        )
        if latest_agg and latest_agg.status == "STALE":
            consistency_status = "STALE_WARNING"
            consistency_message = (
                f"Bảng tổng hợp số dư kỳ {period_obj.code} tại UC-GL-10 đang ở trạng thái STALE (có bút toán mới sau lần tổng hợp trước). "
                "Sổ cái UC-GL-14 đã tự động tính trực tiếp trên nguồn POSTED mới nhất (EF-13, BR-GL-TRACE-26, 27)."
            )

    # Phân trang (EF-25, BR-GL-TRACE-59..63)
    page = max(int(params.get("page") or 1), 1)
    page_size = min(max(int(params.get("page_size") or 200), 1), 2000)
    total_movement_rows = len(movement_rows)
    start_idx = (page - 1) * page_size
    end_idx = start_idx + page_size
    paginated_movements = movement_rows[start_idx:end_idx]

    currency_totals_list = [
        {
            "currency_code": k,
            "period_debit_fc": str(v["period_debit_fc"]),
            "period_credit_fc": str(v["period_credit_fc"]),
            "period_debit_vnd": str(v["period_debit_vnd"]),
            "period_credit_vnd": str(v["period_credit_vnd"]),
            "line_count": v["line_count"],
        }
        for k, v in sorted(currency_summaries.items())
    ]

    t_account_list = [
        {
            "account_code": k,
            "account_name": v["account_name"],
            "debit_by_reciprocal": {rk: str(rv) for rk, rv in sorted(v["debit_by_reciprocal"].items())},
            "credit_by_reciprocal": {rk: str(rv) for rk, rv in sorted(v["credit_by_reciprocal"].items())},
            "total_debit": str(v["total_debit"]),
            "total_credit": str(v["total_credit"]),
        }
        for k, v in sorted(t_account_map.items())
    ]

    return {
        "book_type": book_type,
        "book_title": book_meta["title"],
        "form_code": book_meta["form_code"],
        "circular_ref": book_meta["circular_ref"],
        "is_official_book": is_official_book,
        "company_id": str(company.id),
        "company_name": company.name,
        "period_code": dates_info["period_code"],
        "period_status": dates_info["period_status"],
        "from_date": str(from_date),
        "to_date": str(to_date),
        "filters_applied": {
            "account_codes": acc_info["requested_codes"],
            "include_child_accounts": acc_info["include_child_accounts"],
            "reciprocal_account_code": reciprocal_filter,
            "voucher_number": voucher_number,
            "entry_type": entry_type_filter,
            "source_module": source_module_filter,
            "entry_status": raw_status or ("POSTED" if is_official_book else "ALL"),
            "currency_code": currency_filter,
            "keyword": keyword,
        },
        "summary_totals": {
            "opening_debit": str(leaf_opening_debit),
            "opening_credit": str(leaf_opening_credit),
            "period_debit": str(period_debit_total),
            "period_credit": str(period_credit_total),
            "closing_debit": str(leaf_closing_debit),
            "closing_credit": str(leaf_closing_credit),
            "is_balanced": (leaf_opening_debit == leaf_opening_credit) and (period_debit_total == period_credit_total) and (leaf_closing_debit == leaf_closing_credit),
            "foreign_currency_note": (
                "Cộng phát sinh ngoại tệ được tách riêng theo từng loại ngoại tệ (USD, EUR...), "
                "tuyệt đối không cộng ngang nguyên tệ khác loại tiền (BR-GL-TRACE-72)."
            ),
        },
        "consistency_with_uc_gl_10": {
            "status": consistency_status,
            "message": consistency_message,
        },
        "pagination": {
            "page": page,
            "page_size": page_size,
            "total_rows": total_movement_rows,
            "total_pages": max((total_movement_rows + page_size - 1) // page_size, 1),
        },
        "rows": paginated_movements,
        "account_summaries": account_summaries,
        "detail_partner_summaries": detail_partner_summaries,
        "currency_totals": currency_totals_list,
        "t_account_summaries": t_account_list,
        "multi_period_groups": multi_period_groups,
        "empty_result_message": (
            "Không có dữ liệu phát sinh thỏa điều kiện lọc trong kỳ đã chọn (AF-27, BR-GL-TRACE-21)."
            if total_movement_rows == 0 and not account_summaries
            else ""
        ),
    }


def trace_gl_entry_and_source_voucher_uc_gl_14(company, params=None, request=None):
    """
    UC-GL-14 – Truy vết chuỗi 2 chiều:
    Sổ/Báo cáo (UC-GL-10, 11, 13, 14) ↔ Dòng hạch toán (`JournalLine`) ↔ Bút toán GL (`JournalEntry` + Chuỗi Đảo/Điều chỉnh UC-GL-06)
    ↔ Chứng từ nghiệp vụ nguồn (`UC-GL-01, 02, 03, 04, 04A, 07, 08, 09` & các phân hệ `PUR, AP, SAL, AR, CASH, BANK, INV, FA...`).
    Đảm bảo không làm thay đổi dữ liệu kế toán (Zero GL Mutation — BR-GL-TRACE-01, 51).
    """
    params = dict(params or {})
    scope_info = _enforce_data_scope_uc_gl_14(company, params)
    denied_source_modules = params.get("denied_source_modules") or []
    denied_set = {str(m).strip().upper() for m in denied_source_modules if m}

    entry = None
    selected_line = None

    line_id = params.get("line_id") or params.get("journal_line_id")
    entry_id = params.get("entry_id") or params.get("journal_entry_id")
    voucher_number = str(params.get("voucher_number") or params.get("number") or "").strip()
    source_document_id = str(params.get("source_document_id") or params.get("source_entity_id") or "").strip()
    source_module_param = str(params.get("source_module") or "").strip().upper()

    if line_id:
        selected_line = (
            models.JournalLine.objects.select_related("entry", "account", "party", "department", "project", "cost_center", "currency")
            .filter(pk=line_id, entry__company=company)
            .first()
        )
        if not selected_line:
            raise ValidationError({
                "line_id": f"Dòng hạch toán '{line_id}' không tồn tại hoặc không thuộc doanh nghiệp hiện tại (EF-16).",
                "error_code": "JOURNAL_LINE_NOT_FOUND",
            })
        entry = selected_line.entry

    if not entry and entry_id:
        entry = models.JournalEntry.objects.filter(pk=entry_id, company=company).first()
        if not entry:
            raise ValidationError({
                "entry_id": f"Bút toán Sổ cái '{entry_id}' không tồn tại hoặc đã bị loại khỏi phạm vi truy cập (EF-16, BR-GL-TRACE-36).",
                "error_code": "JOURNAL_ENTRY_NOT_FOUND",
            })

    if not entry and voucher_number:
        entry = models.JournalEntry.objects.filter(company=company, number=voucher_number).first()
        if not entry:
            ing = models.SubledgerJournalIngestion.objects.filter(
                company=company, source_document_number=voucher_number
            ).select_related("primary_journal_entry").first()
            if ing and ing.primary_journal_entry_id:
                entry = ing.primary_journal_entry

    # AF-23, BR-GL-TRACE-85, 105: Truy vết ngược từ Chứng từ nghiệp vụ nguồn sang các Bút toán Sổ cái liên quan
    if not entry and source_document_id:
        entry_qs = models.JournalEntry.objects.filter(company=company)
        try:
            uuid_val = uuid.UUID(source_document_id)
            entry = entry_qs.filter(source_entity_id=uuid_val).first()
        except ValueError:
            entry = None
        if not entry:
            ing = models.SubledgerJournalIngestion.objects.filter(
                company=company,
                source_document_id=source_document_id,
            ).select_related("primary_journal_entry").first()
            if ing and ing.primary_journal_entry_id:
                entry = ing.primary_journal_entry

    if not entry:
        raise ValidationError({
            "voucher_number": "Không tìm thấy bút toán Sổ cái hoặc chứng từ nguồn tương ứng với điều kiện truy vết (EF-16, BR-GL-TRACE-36).",
            "error_code": "TRACE_TARGET_NOT_FOUND",
        })

    # Kiểm tra Data Scope trên bút toán
    if scope_info["allowed_branch_set"] is not None and entry.branch_id and str(entry.branch_id) not in scope_info["allowed_branch_set"]:
        raise ValidationError({
            "entry_id": "Bút toán nằm ngoài phạm vi dữ liệu (Data Scope) được cấp quyền của người dùng (EF-08, BR-GL-TRACE-05).",
            "error_code": "OUT_OF_DATA_SCOPE",
        })

    all_lines = list(
        entry.lines.select_related("account", "currency", "party", "department", "project", "cost_center", "warehouse").order_by("line_no")
    )
    lines_payload = []
    for ln in all_lines:
        recip_str = _resolve_reciprocal_accounts(all_lines, ln)
        dims = ln.dimensions or {}
        lines_payload.append({
            "line_id": str(ln.id),
            "line_no": ln.line_no,
            "account_code": ln.account.code,
            "account_name": ln.account.name,
            "reciprocal_account_code": recip_str,
            "description": ln.description or entry.description,
            "debit": str(ln.debit or Decimal("0")),
            "credit": str(ln.credit or Decimal("0")),
            "currency_code": ln.currency.code if ln.currency_id else "VND",
            "exchange_rate": str(ln.exchange_rate or Decimal("1")),
            "foreign_amount": str(ln.foreign_amount or Decimal("0")),
            "party_code": ln.party.code if ln.party_id else "",
            "party_name": ln.party.name if ln.party_id else "",
            "department_code": ln.department.code if ln.department_id else "",
            "project_code": ln.project.code if ln.project_id else "",
            "cost_center_code": ln.cost_center.code if ln.cost_center_id else "",
            "cost_item_code": str(dims.get("cost_item_code") or dims.get("expense_item") or ""),
            "contract_code": str(dims.get("contract_code") or dims.get("contract") or ""),
            "is_selected_line": bool(selected_line and selected_line.id == ln.id),
        })

    # Chuỗi điều chỉnh / đảo bút toán (AF-20, AF-21, BR-GL-TRACE-13..15, 45..47)
    original_entry_info = None
    if entry.original_entry_id:
        orig = entry.original_entry
        original_entry_info = {
            "entry_id": str(orig.id),
            "number": orig.number,
            "entry_type": orig.entry_type,
            "posting_date": str(orig.posting_date),
            "status": orig.status,
            "total_debit": str(orig.total_debit),
            "total_credit": str(orig.total_credit),
            "description": orig.description,
            "relationship": "REVERSAL_OF" if entry.entry_type == "REVERSAL" else "ADJUSTMENT_OF",
        }

    related_entries_list = []
    for rel in entry.related_entries.all().order_by("posting_date", "created_at"):
        related_entries_list.append({
            "entry_id": str(rel.id),
            "number": rel.number,
            "entry_type": rel.entry_type,
            "posting_date": str(rel.posting_date),
            "status": rel.status,
            "total_debit": str(rel.total_debit),
            "total_credit": str(rel.total_credit),
            "description": rel.description,
            "correction_reason": rel.correction_reason,
            "relationship": "REVERSED_BY" if rel.entry_type == "REVERSAL" else "ADJUSTED_BY",
        })

    for rep in entry.replacement_entries.all().order_by("posting_date", "created_at"):
        related_entries_list.append({
            "entry_id": str(rep.id),
            "number": rep.number,
            "entry_type": rep.entry_type,
            "posting_date": str(rep.posting_date),
            "status": rep.status,
            "total_debit": str(rep.total_debit),
            "total_credit": str(rep.total_credit),
            "description": rep.description,
            "correction_reason": rep.correction_reason,
            "relationship": "REPLACED_BY",
        })

    # Xác định trạng thái truy vết & chi tiết Chứng từ nguồn (Section 1.2.B, D)
    trace_summary = _determine_entry_trace_summary(entry, denied_source_modules=denied_set)
    trace_status = trace_summary["trace_status"]
    source_voucher_detail = None
    reference_documents = []

    if trace_status == "ACCESS_RESTRICTED":
        source_voucher_detail = {
            "access_restricted": True,
            "source_module": trace_summary["source_module"],
            "source_document_type": trace_summary["source_document_type"],
            "source_document_id": trace_summary["source_document_id"],
            "source_document_number": trace_summary.get("source_document_number") or "",
            "message": trace_summary["message"],
        }
    elif trace_status in ("TRACEABLE", "PARTIAL_TRACE"):
        # Lấy thông tin chi tiết chứng từ nguồn theo đúng loại chứng từ
        ing = (
            models.SubledgerJournalIngestion.objects.filter(
                Q(primary_journal_entry=entry)
                | Q(journal_entries=entry)
                | (Q(pk=entry.source_entity_id) if entry.source_entity_id else Q(pk__isnull=True))
            )
            .select_related("currency")
            .distinct()
            .first()
        )
        asv = models.AdvanceSettlementVoucher.objects.filter(
            Q(journal_entry=entry) | (Q(pk=entry.source_entity_id) if entry.source_entity_id else Q(pk__isnull=True))
        ).select_related("advance_request", "employee", "department").first()
        gbv = models.GeneralBusinessVoucher.objects.filter(
            Q(journal_entry=entry) | (Q(pk=entry.source_entity_id) if entry.source_entity_id else Q(pk__isnull=True))
        ).select_related("currency").first()
        alr = models.AllocationRun.objects.filter(
            Q(entry=entry) | (Q(pk=entry.source_entity_id) if entry.source_entity_id else Q(pk__isnull=True))
        ).first()
        fxr = models.ForeignCurrencyRevaluationRun.objects.filter(
            Q(entry=entry) | (Q(pk=entry.source_entity_id) if entry.source_entity_id else Q(pk__isnull=True))
        ).select_related("currency").first()
        clr = models.ClosingRun.objects.filter(
            Q(entry=entry) | (Q(pk=entry.source_entity_id) if entry.source_entity_id else Q(pk__isnull=True))
        ).first()

        if asv:
            source_voucher_detail = {
                "source_module": "GL",
                "source_use_case": "UC-GL-02",
                "source_document_type": "ADVANCE_SETTLEMENT_VOUCHER",
                "source_document_type_label": "Chứng từ quyết toán tạm ứng",
                "source_document_id": str(asv.id),
                "source_document_number": asv.number,
                "document_date": str(asv.document_date),
                "posting_date": str(asv.posting_date),
                "partner_or_employee": asv.employee.full_name if asv.employee_id else "",
                "description": asv.description,
                "total_amount": str(asv.total_amount),
                "currency_code": "VND",
                "status": asv.status,
            }
            if asv.advance_request_id:
                reference_documents.append({
                    "ref_type": "ADVANCE_SETTLEMENT_REQUEST (UC-GL-01)",
                    "ref_id": str(asv.advance_request.id),
                    "ref_number": asv.advance_request.number,
                    "ref_date": str(asv.advance_request.request_date),
                    "status": asv.advance_request.status,
                })
        elif gbv:
            source_voucher_detail = {
                "source_module": "GL",
                "source_use_case": "UC-GL-04",
                "source_document_type": "GENERAL_BUSINESS_VOUCHER",
                "source_document_type_label": "Chứng từ nghiệp vụ khác",
                "source_document_id": str(gbv.id),
                "source_document_number": gbv.number,
                "document_date": str(gbv.document_date),
                "posting_date": str(gbv.posting_date),
                "partner_or_employee": "",
                "description": gbv.description,
                "total_amount": str(gbv.total_amount),
                "currency_code": gbv.currency.code if gbv.currency_id else "VND",
                "status": gbv.status,
            }
        elif alr:
            source_voucher_detail = {
                "source_module": "GL",
                "source_use_case": "UC-GL-07",
                "source_document_type": "ALLOCATION_RUN",
                "source_document_type_label": "Chứng từ phân bổ chi phí",
                "source_document_id": str(alr.id),
                "source_document_number": alr.number,
                "document_date": str(alr.posting_date),
                "posting_date": str(alr.posting_date),
                "partner_or_employee": "",
                "description": alr.description,
                "total_amount": str(alr.amount),
                "currency_code": "VND",
                "status": alr.status,
            }
        elif fxr:
            source_voucher_detail = {
                "source_module": "GL",
                "source_use_case": "UC-GL-08",
                "source_document_type": "FX_REVALUATION_RUN",
                "source_document_type_label": "Chứng từ đánh giá lại ngoại tệ",
                "source_document_id": str(fxr.id),
                "source_document_number": fxr.number,
                "document_date": str(fxr.document_date),
                "posting_date": str(fxr.posting_date),
                "partner_or_employee": "",
                "description": fxr.description,
                "total_amount": str(abs(fxr.net_difference)),
                "currency_code": fxr.currency.code if fxr.currency_id else "USD",
                "status": fxr.status,
            }
        elif clr:
            source_voucher_detail = {
                "source_module": "GL",
                "source_use_case": "UC-GL-09",
                "source_document_type": "CLOSING_RUN",
                "source_document_type_label": "Chứng từ kết chuyển lãi lỗ",
                "source_document_id": str(clr.id),
                "source_document_number": clr.number or entry.number,
                "document_date": str(entry.document_date or entry.posting_date),
                "posting_date": str(entry.posting_date),
                "partner_or_employee": "",
                "description": entry.description,
                "total_amount": str(entry.total_debit),
                "currency_code": "VND",
                "status": clr.status,
            }
        elif ing:
            doc_type = ing.source_business_type or ing.source_document_type
            source_voucher_detail = {
                "source_module": ing.source_module,
                "source_use_case": "UC-GL-04A",
                "source_document_type": doc_type,
                "source_document_type_label": f"Chứng từ phân hệ {ing.source_module} ({doc_type})",
                "source_document_id": ing.source_document_id,
                "source_document_number": ing.source_document_number,
                "source_event_id": ing.source_event_id,
                "document_date": str(ing.document_date or ing.posting_date),
                "posting_date": str(ing.posting_date),
                "partner_or_employee": str((ing.raw_payload or {}).get("party_code") or ""),
                "description": ing.description,
                "total_amount": str(ing.total_debit),
                "currency_code": ing.currency.code if ing.currency_id else "VND",
                "status": ing.status,
            }

    # Lịch sử Ghi sổ / Bỏ ghi sổ (UC-GL-05)
    posting_history_list = [
        {
            "action": ph.action,
            "status_before": ph.status_before,
            "status_after": ph.status_after,
            "reference": ph.reference,
            "reason": ph.reason,
            "actor": (getattr(ph.actor, "email", None) or getattr(ph.actor, "full_name", None) or "system") if ph.actor_id else "system",
            "occurred_at": ph.occurred_at.isoformat() if ph.occurred_at else "",
        }
        for ph in entry.posting_histories.select_related("actor").all()[:20]
    ]

    # Tìm tất cả bút toán GL cùng sinh từ chứng từ nguồn này (AF-23, BR-GL-TRACE-85, 105)
    sibling_entries = []
    if source_voucher_detail and source_voucher_detail.get("source_document_id"):
        src_doc_id = source_voucher_detail["source_document_id"]
        sib_qs = models.JournalEntry.objects.filter(company=company).filter(
            Q(id=entry.id)
            | (Q(source_entity_id=entry.source_entity_id) if entry.source_entity_id else Q(pk__isnull=True))
            | Q(original_entry=entry)
        ).order_by("posting_date", "created_at")
        for s in sib_qs:
            sibling_entries.append({
                "entry_id": str(s.id),
                "number": s.number,
                "entry_type": s.entry_type,
                "posting_date": str(s.posting_date),
                "status": s.status,
                "total_debit": str(s.total_debit),
                "total_credit": str(s.total_credit),
            })

    return {
        "trace_status": trace_status,
        "trace_message": trace_summary["message"],
        "trace_chain_breadcrumb": [
            "Sổ kế toán / Báo cáo (UC-GL-14)",
            f"Dòng phát sinh TK {selected_line.account.code}" if selected_line else "Dòng phát sinh GL",
            f"Bút toán GL [{entry.number}] ({entry.status})",
            (
                f"Chứng từ nguồn [{source_voucher_detail.get('source_document_number') or trace_summary.get('source_document_id')}] ({trace_summary['source_module']})"
                if trace_status in ("TRACEABLE", "PARTIAL_TRACE", "ACCESS_RESTRICTED")
                else ("Bút toán gốc tại GL (NO_SOURCE)" if trace_status == "NO_SOURCE" else "Thiếu liên kết nguồn (BROKEN_LINK)")
            ),
        ],
        "gl_entry": {
            "entry_id": str(entry.id),
            "number": entry.number,
            "entry_type": entry.entry_type,
            "status": entry.status,
            "posting_date": str(entry.posting_date),
            "document_date": str(entry.document_date or entry.posting_date),
            "period_code": entry.period.code if entry.period_id else "",
            "period_status": entry.period.status if entry.period_id else "OPEN",
            "description": entry.description,
            "source_module": entry.source_module or "GL",
            "source_entity_type": entry.source_entity_type or "",
            "source_entity_id": str(entry.source_entity_id or ""),
            "source_event_id": entry.source_event_id or "",
            "total_debit": str(entry.total_debit),
            "total_credit": str(entry.total_credit),
            "is_balanced": entry.total_debit == entry.total_credit,
            "created_by": (getattr(entry.created_by, "email", None) or getattr(entry.created_by, "full_name", None) or "system") if entry.created_by_id else "system",
            "created_at": entry.created_at.isoformat() if entry.created_at else "",
            "posted_by": (getattr(entry.posted_by, "email", None) or getattr(entry.posted_by, "full_name", None) or "") if entry.posted_by_id else "",
            "posted_at": entry.posted_at.isoformat() if entry.posted_at else "",
            "is_adjusted": entry.is_adjusted,
            "reversal_method": entry.reversal_method,
            "correction_reason": entry.correction_reason,
            "lines": lines_payload,
        },
        "adjustment_reversal_chain": {
            "original_entry": original_entry_info,
            "related_entries": related_entries_list,
            "has_chain": bool(original_entry_info or related_entries_list),
        },
        "source_voucher": source_voucher_detail,
        "reference_documents": reference_documents,
        "sibling_gl_entries": sibling_entries,
        "posting_history": posting_history_list,
    }


def export_accounting_book_uc_gl_14(company, params=None, request=None):
    """
    UC-GL-14 (Steps 41–44, AF-25, AF-26, EF-22..24, BR-GL-TRACE-64..70, 94, 95):
    In / Xuất Sổ kế toán (Excel, PDF, CSV, PRINT) theo đúng bộ lọc và Data Scope hiện tại.
    Ghi nhận Audit Log và tuyệt đối không làm thay đổi dữ liệu kế toán.
    """
    params = dict(params or {})
    if str(params.get("deny_export_permission", "false")).strip().lower() in ("true", "1", "yes"):
        raise ValidationError({
            "export": "Người dùng không có quyền xuất dữ liệu Sổ kế toán ra file ngoài (EF-22, BR-GL-TRACE-09, 69).",
            "error_code": "EXPORT_PERMISSION_DENIED",
        })

    export_format = str(params.get("format") or params.get("export_format") or "EXCEL").strip().upper()
    if export_format not in ("EXCEL", "XLSX", "PDF", "CSV", "PRINT"):
        raise ValidationError({
            "format": f"Định dạng in/xuất '{export_format}' không được hỗ trợ (EF-23). Chỉ hỗ trợ EXCEL, XLSX, PDF, CSV, PRINT.",
            "error_code": "UNSUPPORTED_EXPORT_FORMAT",
        })

    # Lấy dữ liệu khớp 100% với điều kiện lọc và Data Scope hiện tại (BR-GL-TRACE-64..68)
    book_data = query_accounting_book_uc_gl_14(company, params, request=request)
    actor_user = actor(request) if request else None

    if request:
        period_or_company = (
            models.AccountingPeriod.objects.filter(company=company, code=book_data["period_code"]).first()
            or company
        )
        audit(
            request,
            period_or_company,
            f"EXPORT_ACCOUNTING_BOOK_{export_format}",
            after={
                "book_type": book_data["book_type"],
                "form_code": book_data["form_code"],
                "period_code": book_data["period_code"],
                "from_date": book_data["from_date"],
                "to_date": book_data["to_date"],
                "format": export_format,
                "total_rows": book_data["pagination"]["total_rows"],
            },
        )

    ext = "xlsx" if export_format in ("EXCEL", "XLSX") else ("pdf" if export_format == "PDF" else "csv")
    return {
        "export_status": "SUCCESS",
        "format": export_format,
        "file_name": f"{book_data['form_code']}_{book_data['book_type']}_{book_data['from_date']}_{book_data['to_date']}.{ext}",
        "exported_at": timezone.now().isoformat(),
        "exported_by": (getattr(actor_user, "email", None) or getattr(actor_user, "full_name", None) or "system") if actor_user else "system",
        "company_name": company.name,
        "book_type": book_data["book_type"],
        "book_title": book_data["book_title"],
        "form_code": book_data["form_code"],
        "circular_ref": book_data["circular_ref"],
        "period_code": book_data["period_code"],
        "from_date": book_data["from_date"],
        "to_date": book_data["to_date"],
        "filters_applied": book_data["filters_applied"],
        "summary_totals": book_data["summary_totals"],
        "row_count": book_data["pagination"]["total_rows"],
        "rows": book_data["rows"],
        "account_summaries": book_data["account_summaries"],
        "currency_totals": book_data["currency_totals"],
    }









